insert into public.preguntas (id,oposicion,tema,pregunta,opciones,correcta,articulo,explicacion,examen) values
('adm-cm:24-1e0e681962','adm-cm',24,'La Agencia Española de Protección de Datos es:','["Una autoridad administrativa independiente de ámbito estatal", "Una dirección general adscrita al Ministerio del Interior, sin personalidad jurídica", "Un órgano adscrito al Consejo General del Poder Judicial", "Una agencia de la Unión Europea con sede en España"]'::jsonb,0,'Art. 44.1 LO 3/2018','Es una autoridad administrativa independiente de ámbito estatal.',null),
('adm-cm:24-a1483b86a7','adm-cm',24,'El mandato de la Presidencia de la Agencia Española de Protección de Datos es de:','["Cuatro años, no renovable", "Cinco años, renovable por otro periodo de igual duración", "Seis años, no renovable, contados desde su toma de posesión", "Cuatro años, renovable por otro periodo de igual duración"]'::jsonb,1,'Art. 48.5 LO 3/2018','El mandato es de cinco años y puede renovarse por otro periodo de igual duración.',null),
('adm-cm:24-cb11a53015','adm-cm',24,'¿Cuándo prescriben las infracciones leves en materia de protección de datos?','["A los seis meses", "A los dos años", "Al año", "A los tres años"]'::jsonb,2,'Art. 74 LO 3/2018','Las infracciones muy graves prescriben a los tres años (art. 72), las graves a los dos años (art. 73) y las leves al año (art. 74).',null),
('adm-cm:24-f858cbe811','adm-cm',24,'Las sanciones de protección de datos de importe superior a 300.000 euros prescriben a:','["Al año", "Los dos años", "Los seis meses", "Los tres años"]'::jsonb,3,'Art. 78.1 LO 3/2018','Hasta 40.000 € prescriben al año; entre 40.001 y 300.000 €, a los dos años; y las superiores a 300.000 €, a los tres años.',null),
('adm-cm:24-2bdb49d573','adm-cm',24,'¿Se aplica el régimen sancionador de la LO 3/2018 al delegado de protección de datos?','["No", "Sí, en todo caso", "Solo por infracciones muy graves", "Solo si es personal laboral"]'::jsonb,0,'Art. 70.2 LO 3/2018','El régimen sancionador de la ley no es de aplicación al delegado de protección de datos.',null),
('adm-cm:24-b6e6cda164','adm-cm',24,'Los herederos de una persona fallecida, ¿pueden solicitar el acceso, la rectificación o la supresión de sus datos?','["No, salvo que el fallecido lo hubiese autorizado expresamente en vida", "Sí, salvo que el fallecido lo hubiese prohibido expresamente o lo establezca una ley", "Sí, pero solo con autorización judicial y acreditando un interés legítimo", "Sí, durante el primer año tras el fallecimiento, salvo prohibición expresa del fallecido"]'::jsonb,1,'Art. 3.1 LO 3/2018','Pueden hacerlo las personas vinculadas al fallecido por razones familiares o de hecho y sus herederos, salvo prohibición expresa del fallecido o de una ley.',null),
('adm-cm:24-c1bb174363','adm-cm',24,'El derecho al olvido en búsquedas de Internet permite pedir a los motores de búsqueda:','["Que eliminen de los resultados de una búsqueda por el nombre los enlaces a información inadecuada, inexacta, no pertinente, no actualizada o excesiva", "Que paguen una indemnización automática", "Que borren la página web original en todo caso, junto con todas sus copias y enlaces, aunque la información sea exacta, pertinente y actualizada y su difusión sea lícita", "Que cierren la cuenta del usuario"]'::jsonb,0,'Art. 93.1 LO 3/2018','Es el derecho al olvido frente a buscadores.',null),
('adm-cm:24-54de055a92','adm-cm',24,'El acceso a los contenidos gestionados por prestadores de servicios digitales de personas fallecidas se regula en la LO 3/2018 como:','["Testamento digital", "Herencia yacente", "Derecho de rectificación", "Derecho de portabilidad"]'::jsonb,0,'Art. 96 LO 3/2018','Salvo que el fallecido lo hubiese prohibido expresamente.',null),
('adm-cm:24-d54a0d64a2','adm-cm',24,'En ningún caso se admitirá la instalación de sistemas de grabación de sonidos o videovigilancia en:','["Las entradas de los edificios", "Los aparcamientos", "Lugares destinados al descanso o esparcimiento de los trabajadores, como vestuarios, aseos o comedores", "Las zonas de caja y de atención al público, aunque se informe previamente a los trabajadores"]'::jsonb,2,'Art. 89.2 LO 3/2018','Protección de la intimidad en el trabajo.',null),
('adm-cm:24-5b07e83928','adm-cm',24,'En los sistemas de información crediticia, los datos solo pueden mantenerse mientras persista el incumplimiento, con el límite máximo de:','["Cinco años desde la fecha de vencimiento de la obligación", "Diez años", "Un año", "Seis años desde la fecha de inclusión en el sistema"]'::jsonb,0,'Art. 20.1 d) LO 3/2018','Límite temporal de los ficheros de morosos.',null),
('adm-cm:24-0ab72dbf83','adm-cm',24,'Quienes pretendan realizar comunicaciones de mercadotecnia directa deben consultar previamente:','["El censo electoral", "El Registro Civil", "El padrón municipal de habitantes y el censo de empresas", "Los sistemas de exclusión publicitaria"]'::jsonb,3,'Art. 23.4 LO 3/2018','Salvo que el afectado haya prestado su consentimiento a recibirlas.',null),
('adm-cm:24-2d40697a01','adm-cm',24,'El tratamiento de los datos de un menor de catorce años fundado en el consentimiento solo es lícito si consta:','["El consentimiento del propio menor, si tiene madurez suficiente", "El consentimiento del titular de la patria potestad o tutela", "El consentimiento del centro escolar", "Una autorización judicial en todo caso"]'::jsonb,1,'Art. 7.2 LO 3/2018','A partir de los 14 años el menor puede consentir por sí mismo.',null),
('adm-cm:24-97c296445d','adm-cm',24,'La prueba del cumplimiento del deber de responder a la solicitud de ejercicio de derechos corresponde a:','["El encargado del tratamiento", "La AEPD", "El responsable del tratamiento", "El afectado"]'::jsonb,2,'Art. 12.4 LO 3/2018','La carga de la prueba recae en el responsable.',null),
('adm-cm:24-6cfc7761f8','adm-cm',24,'El procedimiento sancionador en materia de protección de datos tendrá una duración máxima de:','["Doce meses desde la fecha del acuerdo de inicio", "Dos años desde la fecha de la reclamación del interesado", "Seis meses desde la fecha de presentación de la denuncia", "Tres meses"]'::jsonb,0,'Art. 64.2 LO 3/2018','Así lo establece el art. 64.2.',null),
('adm-cm:24-85a084044b','adm-cm',24,'El plazo para resolver el procedimiento cuando se reclama exclusivamente la falta de atención de una solicitud de ejercicio de derechos es de:','["Un mes", "Doce meses", "Tres meses", "Seis meses"]'::jsonb,3,'Art. 64.1 LO 3/2018','El procedimiento sancionador tiene una duración máxima de doce meses (art. 64.2).',null),
('adm-cm:24-3a507fd39d','adm-cm',24,'Las imágenes captadas por sistemas de videovigilancia deben suprimirse, con carácter general, en el plazo máximo de:','["Una semana desde su captación", "Un mes desde su captación", "Tres meses desde su captación", "Un año desde su captación"]'::jsonb,1,'Art. 22.3 LO 3/2018','Salvo que deban conservarse para acreditar actos contra personas, bienes o instalaciones.','nov. 2024 · 1.er ejercicio'),
('adm-cm:24-c98fa13d60','adm-cm',24,'Según el art. 2.2 de la LO 3/2018, la ley NO se aplica, sin perjuicio de su art. 3, a:','["Los tratamientos de las Administraciones Públicas", "Los datos de menores", "Los tratamientos de datos de personas fallecidas", "Los datos de salud"]'::jsonb,2,'Art. 2.2 LO 3/2018','También quedan excluidos los tratamientos fuera del RGPD y las materias clasificadas.',null),
('adm-cm:24-250b2ee352','adm-cm',24,'La Presidencia y el Adjunto de la AEPD son nombrados:','["Por elección directa de los ciudadanos entre los candidatos propuestos por el Congreso, el Senado y el Consejo General del Poder Judicial, por cinco años", "Por el Consejo de Ministros mediante real decreto, a propuesta del Gobierno y tras su ratificación por la Comisión de Justicia del Congreso", "Por el Consejo General del Poder Judicial", "Por el Rey a propuesta del Senado, por mayoría de tres quintos, tras una comparecencia pública ante la Comisión Constitucional y previo informe favorable del Consejo de Estado"]'::jsonb,1,'Art. 48.3 LO 3/2018','El mandato es de cinco años renovable.',null),
('adm-cm:24-f36342148c','adm-cm',24,'Las actuaciones del responsable para atender las solicitudes de ejercicio de derechos serán, con carácter general:','["De pago obligatorio", "Gratuitas solo para menores", "Sujetas a tasa estatal", "Gratuitas"]'::jsonb,3,'Art. 12.7 LO 3/2018','Sin perjuicio de lo dispuesto en el RGPD para solicitudes infundadas o excesivas.',null),
('adm-cm:24-9c34aee146','adm-cm',24,'Las infracciones graves en materia de protección de datos prescriben a los:','["Seis meses", "Tres años", "Dos años", "Un año"]'::jsonb,2,'Art. 73 LO 3/2018','Las muy graves a los tres años.',null),
('adm-cm:24-8a072081c3','adm-cm',24,'Según el art. 81 de la LO 3/2018:','["Solo los mayores de edad pueden acceder a Internet", "Todos tienen derecho a acceder a Internet independientemente de su condición personal, social, económica o geográfica", "El acceso a Internet depende de autorización administrativa", "Todos tienen derecho a acceder a Internet, salvo las limitaciones que establezca cada prestador por razones económicas o geográficas"]'::jsonb,1,'Art. 81.1 LO 3/2018','Derecho de acceso universal a Internet.',null),
('adm-cm:24-afc1146cf0','adm-cm',24,'Las infracciones muy graves en materia de protección de datos prescriben a los:','["Un año", "Tres años", "Dos años", "Cinco años"]'::jsonb,1,'Art. 72.1 LO 3/2018','Las graves a los dos años y las leves al año.',null),
('adm-cm:24-1a8ae62b34','adm-cm',24,'Los responsables y encargados deben comunicar a la AEPD o autoridad autonómica las designaciones, nombramientos y ceses de los delegados de protección de datos en el plazo de:','["Un mes", "Tres días", "Diez días", "Quince días"]'::jsonb,2,'Art. 34.3 LO 3/2018','Plazo de diez días.',null),
('adm-cm:24-846bd25a8b','adm-cm',24,'El derecho a la desconexión digital garantiza a los trabajadores y empleados públicos:','["El uso libre de redes sociales en el trabajo", "Que puedan desconectar los dispositivos de la oficina durante la jornada laboral cuando lo consideren necesario para concentrarse en sus tareas", "Que no se use el correo electrónico en la empresa", "El respeto de su tiempo de descanso, permisos y vacaciones fuera del tiempo de trabajo legal o convencionalmente establecido"]'::jsonb,3,'Art. 88.1 LO 3/2018','El empleador debe elaborar una política interna, previa audiencia de los representantes.',null),
('adm-cm:24-a7239d845f','adm-cm',24,'El ejercicio del derecho de acceso más de una vez durante el plazo de ___ podrá considerarse repetitivo, salvo causa legítima:','["Seis meses", "Tres meses", "Un año", "Un mes"]'::jsonb,0,'Art. 13.3 LO 3/2018','Así lo dispone el art. 13.3.',null),
('adm-cm:24-7e2cace560','adm-cm',24,'Transcurrido el plazo de prescripción de las posibles responsabilidades, los datos bloqueados deberán ser:','["Destruidos", "Transferidos a la AEPD", "Publicados", "Conservados indefinidamente"]'::jsonb,0,'Art. 32.2 LO 3/2018','El bloqueo es temporal hasta la prescripción.',null),
('adm-cm:24-05f22c005e','adm-cm',24,'Si el afectado presenta una reclamación previa ante el delegado de protección de datos, este deberá comunicar su decisión en el plazo máximo de:','["Un mes", "Diez días", "Seis meses", "Dos meses"]'::jsonb,3,'Art. 37.1 LO 3/2018','Si la AEPD remite la reclamación al delegado, este responde en un mes (art. 37.2).',null),
('adm-cm:25-9a3342dead','adm-cm',25,'Según el art. 8.2 del TREBEP, los empleados públicos se clasifican en:','["Funcionarios de carrera, funcionarios interinos, personal laboral y personal eventual", "Funcionarios de carrera, funcionarios interinos, personal laboral, personal eventual y personal directivo profesional", "Funcionarios de carrera, personal laboral, personal eventual y personal directivo", "Funcionarios de carrera, funcionarios interinos y personal laboral fijo o temporal"]'::jsonb,0,'Art. 8.2 TREBEP','Se clasifican en funcionarios de carrera, funcionarios interinos, personal laboral (fijo, por tiempo indefinido o temporal) y personal eventual.','abr. 2026 · 1.er ejercicio'),
('adm-cm:25-5b04e4287c','adm-cm',25,'Las funciones que implican participación directa o indirecta en el ejercicio de potestades públicas corresponden:','["A cualquier empleado público, sea funcionario o laboral", "Exclusivamente a los funcionarios públicos", "Al personal laboral fijo y a los funcionarios de carrera, en los términos que establezca la ley de cada Administración", "Exclusivamente a los funcionarios de carrera, nunca a los interinos"]'::jsonb,1,'Art. 9.2 TREBEP','Corresponden exclusivamente a los funcionarios públicos, en los términos que establezca la ley de desarrollo de cada Administración.',null),
('adm-cm:25-fb86a3b5d9','adm-cm',25,'Un funcionario interino nombrado para cubrir una plaza vacante puede ocuparla como máximo:','["Un año", "Dos años", "Tres años", "Cinco años"]'::jsonb,2,'Art. 10.1 a) TREBEP','Las plazas vacantes pueden cubrirse por interinos cuando no sea posible su cobertura por funcionarios de carrera, por un máximo de tres años.',null),
('adm-cm:25-22947fe7c3','adm-cm',25,'El nombramiento de interinos por exceso o acumulación de tareas tiene un plazo máximo de:','["Seis meses dentro de un periodo de doce", "Doce meses dentro de un periodo de veinticuatro", "Tres años", "Nueve meses dentro de un periodo de dieciocho"]'::jsonb,3,'Art. 10.1 d) TREBEP','El plazo máximo es de nueve meses dentro de un periodo de dieciocho meses.',null),
('adm-cm:25-71a4bb4e93','adm-cm',25,'El nombramiento de interinos para ejecutar programas de carácter temporal no puede superar:','["Tres años, ampliable hasta doce meses más por las leyes de Función Pública", "Dos años, ampliable hasta seis meses más por las leyes de Función Pública que se dicten en desarrollo del Estatuto", "Tres años, sin posibilidad de ampliación", "Cuatro años, ampliable hasta doce meses más por las leyes de Función Pública"]'::jsonb,0,'Art. 10.1 c) TREBEP','No puede ser superior a tres años, ampliable hasta doce meses más por las leyes de Función Pública de cada Administración.',null),
('adm-cm:25-9fd3d0d0ef','adm-cm',25,'El personal eventual realiza funciones:','["De carácter técnico permanente, previstas en la relación de puestos de trabajo de cada Administración", "Expresamente calificadas como de confianza o asesoramiento especial", "De inspección y control, expresamente calificadas como tales", "De confianza, pero que implican el ejercicio de potestades públicas"]'::jsonb,1,'Art. 12.1 TREBEP','El personal eventual solo realiza funciones expresamente calificadas como de confianza o asesoramiento especial.',null),
('adm-cm:25-ffa2129553','adm-cm',25,'Haber sido personal eventual, ¿puede constituir mérito para el acceso a la función pública?','["Sí, siempre", "Sí, si se prestaron servicios más de un año", "No", "Solo en la promoción interna"]'::jsonb,2,'Art. 12.4 TREBEP','La condición de personal eventual no puede constituir mérito para el acceso a la Función Pública o para la promoción interna.',null),
('adm-cm:25-fb1083c9a9','adm-cm',25,'¿Qué titulación se exige para acceder a un cuerpo del subgrupo C2?','["Bachiller o Técnico", "Graduado en Educación Secundaria Obligatoria", "Técnico Superior o equivalente a efectos profesionales", "Certificado de escolaridad o de estudios primarios"]'::jsonb,1,'Art. 76 TREBEP','Para el subgrupo C2 se exige el título de Graduado en ESO; para el C1, Bachiller o Técnico.',null),
('adm-cm:25-ada34b9833','adm-cm',25,'Según la Ley 1/1986 de la Función Pública de la Comunidad de Madrid, su personal se integra por:','["Funcionarios de carrera y personal eventual", "Funcionarios de carrera, personal laboral y personal directivo", "Únicamente funcionarios de carrera", "Funcionarios de carrera, funcionarios interinos y personal laboral"]'::jsonb,3,'Art. 5 Ley 1/1986 CM','La ley madrileña distingue funcionarios de carrera, funcionarios interinos y personal laboral.',null),
('adm-cm:25-1e7b618c1c','adm-cm',25,'En la Comunidad de Madrid, ¿quién aprueba la oferta anual de empleo público?','["El Consejo de Gobierno", "La Asamblea de Madrid", "La Dirección General de Función Pública", "El Presidente de la Comunidad"]'::jsonb,0,'Art. 7.2 e) Ley 1/1986 CM','Corresponde al Consejo de Gobierno aprobar la oferta anual de empleo público.',null),
('adm-cm:25-3eef4dc8f9','adm-cm',25,'Según la Ley 1/1986, ¿puede alguien ser incluido en la nómina sin estar inscrito en el Registro de Personal?','["Sí, de forma provisional durante un mes", "No", "Sí, si es personal laboral", "Sí, con autorización del Consejero"]'::jsonb,1,'Art. 11.3 Ley 1/1986 CM','Nadie puede ser incluido en nómina sin haber sido inscrito antes en el Registro de Personal.',null),
('adm-cm:25-34ff2223e1','adm-cm',25,'¿En cuántos niveles se clasifican los puestos de trabajo reservados a funcionarios en la Comunidad de Madrid?','["Veinte", "Veinticinco", "Treinta", "Cuarenta"]'::jsonb,2,'Art. 42.1 Ley 1/1986 CM','Los puestos reservados a funcionarios se clasifican en treinta niveles.',null),
('adm-cm:25-a00dd0dfba','adm-cm',25,'El grado personal se adquiere por el desempeño de puestos del nivel correspondiente durante:','["Un año consecutivo o dos con interrupción", "Tres años consecutivos o cuatro con interrupción, en puestos de nivel igual o superior", "Cinco años consecutivos", "Dos años consecutivos o tres con interrupción"]'::jsonb,3,'Art. 44.2 Ley 1/1986 CM','Se adquiere tras desempeñar uno o más puestos del nivel correspondiente durante dos años consecutivos o tres con interrupción.',null),
('adm-cm:25-bb3612176f','adm-cm',25,'Los Delegados de Personal representan a los funcionarios en unidades electorales que cuenten con:','["Más de 50 funcionarios", "Menos de 6 funcionarios", "Entre 6 y 49 funcionarios", "Más de 250 funcionarios"]'::jsonb,2,'Art. 39.2 TREBEP','A partir de 50 funcionarios hay Juntas de Personal.',null),
('adm-cm:25-136b2ba37c','adm-cm',25,'El personal eventual:','["Tiene derecho a la inamovilidad tras dos años de servicio, y su nombramiento corresponde al órgano de selección tras un concurso de méritos con convocatoria pública", "Ocupa puestos reservados a funcionarios de carrera", "Solo realiza funciones expresamente calificadas como de confianza o asesoramiento especial, y su nombramiento y cese son libres", "Accede mediante concurso de méritos"]'::jsonb,2,'Art. 12.1 y 12.3 TREBEP','El cese tiene lugar, en todo caso, cuando se produzca el de la autoridad a la que preste su función de confianza.',null),
('adm-cm:25-59ab978ae8','adm-cm',25,'La oferta de empleo público deberá desarrollarse dentro del plazo improrrogable de:','["Tres años", "Un año", "Dos años", "Cinco años"]'::jsonb,0,'Art. 70.1 TREBEP','La oferta puede contener hasta un 10 % adicional de plazas.',null),
('adm-cm:25-030f8b6bea','adm-cm',25,'Quedan excluidas de la obligatoriedad de la negociación:','["Las retribuciones complementarias de los funcionarios", "Las decisiones que afecten a las potestades de organización de las Administraciones Públicas", "Los criterios generales de acceso, carrera, provisión, sistemas de clasificación de puestos y planes de recursos humanos", "La evaluación del desempeño"]'::jsonb,1,'Art. 37.2 a) TREBEP','Las demás opciones son materias objeto de negociación (art. 37.1).',null),
('adm-cm:25-f5d32b2bc7','adm-cm',25,'Transcurridos tres años desde el nombramiento de un interino en plaza vacante, esta:','["Solo podrá ser ocupada por personal funcionario de carrera, salvo que el proceso selectivo quede desierto", "Se amortiza automáticamente y el interino cesa sin derecho a indemnización, aunque el proceso selectivo no se haya convocado", "Pasa a ser plaza de personal laboral", "Se convierte automáticamente en plaza en propiedad del interino que la ocupa, sin necesidad de proceso selectivo"]'::jsonb,0,'Art. 10.4 TREBEP','Se produce el fin de la relación de interinidad.',null),
('adm-cm:25-d75dcb88e1','adm-cm',25,'La designación del personal directivo profesional atenderá a principios de:','["Libre designación política por el titular del órgano superior", "Sorteo entre funcionarios del subgrupo A1", "Antigüedad en el cuerpo, y en caso de empate, mérito y capacidad mediante procedimientos que garanticen la publicidad y la concurrencia", "Mérito y capacidad y criterios de idoneidad, mediante procedimientos que garanticen la publicidad y concurrencia"]'::jsonb,3,'Art. 13.2 TREBEP','Así lo establece el art. 13.2.',null),
('adm-cm:25-059bb2021f','adm-cm',25,'Los Pactos y Acuerdos, salvo que se establezca otra cosa:','["Se prorrogarán de año en año si no media denuncia expresa de una de las partes", "Caducan al año de su firma, salvo que se renueven expresamente", "Se prorrogarán por periodos de cuatro años, salvo que una de las partes los denuncie con seis meses de antelación", "Duran cuatro años improrrogables"]'::jsonb,0,'Art. 38.11 TREBEP','Prórroga anual salvo denuncia.',null),
('adm-cm:25-8f688d7462','adm-cm',25,'Las Mesas de Negociación quedarán válidamente constituidas cuando las organizaciones sindicales presentes representen, como mínimo:','["El 10 % de los miembros de los órganos unitarios de representación", "La totalidad de los miembros de los órganos unitarios de representación", "La mayoría absoluta de los miembros de los órganos unitarios de representación en el ámbito de que se trate", "Un tercio de los miembros de los órganos unitarios de representación en el ámbito de que se trate"]'::jsonb,2,'Art. 35.1 TREBEP','Ninguna de las partes puede superar quince miembros (art. 35.4).',null),
('adm-cm:25-de3a58eca6','adm-cm',25,'La duración del mandato de los Delegados de Personal y de las Juntas de Personal es de:','["Tres años", "Cinco años", "Dos años", "Cuatro años"]'::jsonb,3,'Art. 42 TREBEP','Pueden ser reelegidos en sucesivos procesos electorales.',null),
('adm-cm:26-de39acc919','adm-cm',26,'¿Qué edad mínima se exige para participar en los procesos selectivos?','["Dieciséis años", "Dieciocho años", "Diecisiete años", "Veintiún años"]'::jsonb,0,'Art. 56.1 c) TREBEP','Tener cumplidos dieciséis años y no exceder, en su caso, la edad máxima de jubilación forzosa.',null),
('adm-cm:26-bbff3d3256','adm-cm',26,'¿Cuáles son los sistemas selectivos de los funcionarios de carrera?','["Concurso y libre designación con convocatoria pública", "Oposición y concurso-oposición; el concurso, solo con carácter excepcional y en virtud de ley", "Oposición y concurso-oposición; el concurso, con carácter ordinario y sin necesidad de previsión en una ley", "Oposición, concurso y entrevista personal, que pueden utilizarse indistintamente según lo que decida cada convocatoria"]'::jsonb,1,'Art. 61.6 TREBEP','Son la oposición y el concurso-oposición. El concurso de valoración de méritos solo cabe excepcionalmente y en virtud de ley.',null),
('adm-cm:26-4522d5e48c','adm-cm',26,'¿Cuál de los siguientes NO es un requisito para adquirir la condición de funcionario de carrera?','["Superar el proceso selectivo", "Acatar la Constitución", "Haber prestado servicios previos como interino", "Tomar posesión dentro del plazo establecido"]'::jsonb,2,'Art. 62.1 TREBEP','Se requiere superar el proceso selectivo, el nombramiento publicado en el diario oficial, el acatamiento de la Constitución (y Estatuto de Autonomía y resto del ordenamiento) y la toma de posesión.',null),
('adm-cm:26-5991c78f4a','adm-cm',26,'¿Cuál de las siguientes NO es causa de pérdida de la condición de funcionario de carrera?','["La renuncia", "La jubilación total", "La pérdida de la nacionalidad", "La excedencia voluntaria"]'::jsonb,3,'Art. 63 TREBEP','Son causas la renuncia, la pérdida de la nacionalidad, la jubilación total, la pena de inhabilitación firme y la sanción firme de separación del servicio. La excedencia es una situación administrativa.',null),
('adm-cm:26-f807c9d425','adm-cm',26,'La jubilación forzosa de los funcionarios se declara al cumplir:','["65 años, pudiendo solicitar la prolongación hasta los 70", "67 años, sin posibilidad de solicitar la prolongación de la permanencia en el servicio activo", "65 años, pudiendo solicitar la prolongación hasta los 72", "60 años, pudiendo solicitar la prolongación hasta los 65"]'::jsonb,0,'Art. 67.3 TREBEP','Se declara a los sesenta y cinco años, aunque el funcionario puede solicitar la prolongación de la permanencia hasta los setenta.',null),
('adm-cm:26-f10bad8393','adm-cm',26,'En las ofertas de empleo público se reservará un cupo para personas con discapacidad no inferior al:','["2 % de las vacantes", "5 % de las vacantes", "10 % de las vacantes", "7 % de las vacantes"]'::jsonb,3,'Art. 59.1 TREBEP','De ese cupo, al menos el 2 % de las plazas para personas con discapacidad intelectual.',null),
('adm-cm:26-ca478f71f1','adm-cm',26,'Los funcionarios pueden solicitar la prolongación de la permanencia en el servicio activo, una vez cumplida la edad de jubilación forzosa, como máximo hasta:','["Sin límite", "Los setenta años", "Los sesenta y siete años", "Los sesenta y ocho años"]'::jsonb,1,'Art. 67.3 TREBEP','La jubilación forzosa se declara al cumplir 65 años.',null),
('adm-cm:26-4b47392ec7','adm-cm',26,'Los procedimientos de provisión de puestos de trabajo de los funcionarios de carrera son, con carácter general:','["La entrevista y la valoración del currículum", "La oposición y el concurso-oposición", "El concurso y la libre designación con convocatoria pública", "El concurso y la libre designación sin convocatoria pública"]'::jsonb,2,'Art. 78.2 TREBEP','El concurso es el procedimiento normal de provisión.',null),
('adm-cm:26-8fd755646f','adm-cm',26,'La libre designación con convocatoria pública consiste en:','["Una prueba de conocimientos eliminatoria sobre las funciones del puesto, seguida de la valoración de méritos por una comisión técnica independiente", "La antigüedad del candidato", "Un sorteo entre los candidatos", "La apreciación discrecional por el órgano competente de la idoneidad de los candidatos en relación con los requisitos del puesto"]'::jsonb,3,'Art. 80.1 TREBEP','Se aplica a los puestos que determinen las leyes por su especial responsabilidad.',null),
('adm-cm:26-06da7d6933','adm-cm',26,'NO pueden formar parte de los órganos de selección:','["Los funcionarios de carrera de otras Administraciones públicas", "Los funcionarios del mismo cuerpo o escala al que se aspira a ingresar y el personal laboral fijo de la misma Administración", "El personal de elección o designación política, los funcionarios interinos y el personal eventual", "El personal laboral fijo y los funcionarios de carrera que hayan preparado a aspirantes en los cinco años anteriores"]'::jsonb,2,'Art. 60.2 TREBEP','Los órganos de selección son colegiados y tienden a la paridad.',null),
('adm-cm:26-21f3323ae1','adm-cm',26,'Los nacionales de los Estados miembros de la Unión Europea pueden acceder como funcionarios en igualdad de condiciones que los españoles, salvo a los empleos que impliquen:','["Funciones de atención al público en lengua cooficial", "Participación en el ejercicio del poder público o en las funciones de salvaguardia de los intereses del Estado", "Trabajos en entidades locales", "Funciones administrativas, de gestión o de auxilio, aunque no impliquen ejercicio de potestades públicas"]'::jsonb,1,'Art. 57.1 TREBEP','Los extranjeros con residencia legal pueden acceder como personal laboral (art. 57.4).',null),
('adm-cm:26-118d4e3cbf','adm-cm',26,'La renuncia voluntaria a la condición de funcionario:','["Habrá de ser manifestada por escrito y será aceptada expresamente por la Administración, salvo que el funcionario esté sujeto a expediente disciplinario o procesado", "Puede manifestarse verbalmente ante el superior jerárquico", "No necesita aceptación expresa y surte efectos desde su presentación, aunque el funcionario esté sujeto a expediente disciplinario o haya sido procesado por un delito", "No está permitida mientras el funcionario no haya cumplido la edad de jubilación, salvo que lo autorice expresamente el Consejo de Gobierno por razones excepcionales de interés público"]'::jsonb,0,'Art. 64 TREBEP','La renuncia no inhabilita para volver a ingresar por el procedimiento de selección.',null),
('adm-cm:26-a7d9e8e4d1','adm-cm',26,'Los órganos de selección no podrán proponer el acceso a la condición de funcionario de un número superior de aprobados al de plazas convocadas:','["Salvo en la Administración Local, cuando lo acuerde el Pleno", "Salvo que la convocatoria prevea otra cosa", "En ningún caso, y cualquier propuesta que lo contravenga será nula de pleno derecho", "Salvo que lo solicite el tribunal"]'::jsonb,1,'Art. 61.8 TREBEP','Regla general con la excepción prevista.',null),
('adm-cm:26-9640cc0d02','adm-cm',26,'Según el TREBEP, ¿cuál es el procedimiento normal de provisión de puestos de trabajo de los funcionarios de carrera?','["La adscripción provisional", "El concurso", "La comisión de servicios", "La libre designación"]'::jsonb,1,'Art. 78 TREBEP','La libre designación con convocatoria pública es el otro procedimiento ordinario, reservado a puestos determinados por su especial responsabilidad o confianza.',null),
('adm-cm:26-3d389c5e5a','adm-cm',26,'Según el TREBEP, en las ofertas de empleo público se reserva para personas con discapacidad intelectual, dentro del cupo general, al menos:','["El 7 % de las plazas ofertadas", "El 2 % de las plazas ofertadas", "El 1 % de las plazas ofertadas", "El 5 % de las plazas ofertadas"]'::jsonb,1,'Art. 59.1 TREBEP','El cupo total para personas con discapacidad no es inferior al 7 %, y de él al menos el 2 % es para personas con discapacidad intelectual.',null),
('adm-cm:27-c9a41f4f24','adm-cm',27,'¿Cuál de estos es un derecho individual que se ejerce de forma colectiva?','["La inamovilidad en la condición de funcionario", "La formación continua", "Las vacaciones", "El ejercicio de la huelga"]'::jsonb,3,'Art. 15 TREBEP','Son derechos individuales ejercidos colectivamente la libertad sindical, la negociación colectiva y participación, la huelga, el planteamiento de conflictos colectivos y la reunión.',null),
('adm-cm:27-a9df4fca5c','adm-cm',27,'¿Cuántos días de permiso por asuntos particulares tienen los funcionarios al año?','["Seis días", "Cuatro días", "Tres días", "Ocho días"]'::jsonb,0,'Art. 48 k) TREBEP','Por asuntos particulares, seis días al año.',null),
('adm-cm:27-d71a3710ba','adm-cm',27,'¿Cuántos días de permiso corresponden por matrimonio o registro de pareja de hecho?','["Diez días", "Quince días", "Veinte días", "Siete días"]'::jsonb,1,'Art. 48 l) TREBEP','Quince días por matrimonio o registro o constitución formalizada por documento público de pareja de hecho.',null),
('adm-cm:27-fcf9be38d6','adm-cm',27,'¿Qué duración tiene el permiso por nacimiento para la madre biológica según el TREBEP vigente?','["Dieciséis semanas", "Doce semanas", "Diecinueve semanas", "Veinticuatro semanas"]'::jsonb,2,'Art. 49 a) TREBEP','Tras la última reforma son diecinueve semanas (treinta y dos en caso de familia monoparental). Muchos tests antiguos siguen diciendo dieciséis.',null),
('adm-cm:27-a9130b5e20','adm-cm',27,'¿Cuántos días de vacaciones retribuidas tienen los funcionarios por año completo de servicio?','["Treinta días naturales", "Veinte días hábiles", "Veinticinco días hábiles", "Veintidós días hábiles"]'::jsonb,3,'Art. 50.1 TREBEP','Veintidós días hábiles, o los que correspondan proporcionalmente si el tiempo de servicio fue menor.',null),
('adm-cm:27-0201fb536e','adm-cm',27,'Según el art. 54.11, los empleados públicos garantizarán la atención al ciudadano en:','["La lengua oficial que solicite y, si lo pide, también en inglés", "Castellano exclusivamente", "La lengua que lo solicite siempre que sea oficial en el territorio", "La lengua que elija el funcionario"]'::jsonb,2,'Art. 54.11 TREBEP','Es otro principio de conducta.',null),
('adm-cm:27-e5aaf6a92a','adm-cm',27,'Por traslado de domicilio sin cambio de residencia, el funcionario tiene un permiso de:','["Ningún día", "Dos días", "Un día", "Tres días"]'::jsonb,2,'Art. 48 b) TREBEP','Permiso de un día por traslado de domicilio.',null),
('adm-cm:27-07d632e82f','adm-cm',27,'La funcionaria víctima de violencia de género que reduzca su jornada en un tercio o menos:','["Pierde las retribuciones básicas", "Solo cobra el 50 %", "Mantendrá sus retribuciones íntegras", "Pierde todas sus retribuciones"]'::jsonb,2,'Art. 49 d) TREBEP','Si la reducción es mayor, la disminución de retribuciones es proporcional.',null),
('adm-cm:27-941b314597','adm-cm',27,'El permiso parental para el cuidado de hijo o menor acogido por tiempo superior a un año, hasta que cumpla ocho años, tiene una duración máxima de:','["Ocho semanas, y no es retribuido", "Un año", "Dieciséis semanas retribuidas", "Cuatro semanas retribuidas"]'::jsonb,0,'Art. 49 g) TREBEP','Se requiere un preaviso de quince días.',null),
('adm-cm:27-170209b383','adm-cm',27,'El teletrabajo de los empleados públicos:','["Es irreversible una vez concedido y solo puede revocarse como sanción disciplinaria tras el expediente correspondiente", "Solo se permite al personal interino", "Es obligatorio para los puestos cuyas funciones permitan prestarse a distancia, salvo renuncia justificada del empleado", "Tendrá carácter voluntario y reversible, salvo en supuestos excepcionales debidamente justificados"]'::jsonb,3,'Art. 47 bis.2 TREBEP','Se realizará en los términos de las normas que se dicten en desarrollo del Estatuto.',null),
('adm-cm:27-81b14ba8f6','adm-cm',27,'Por accidente o enfermedad grave de un familiar de primer grado de consanguinidad o afinidad, el funcionario tiene un permiso de:','["Cinco días hábiles", "Diez días hábiles", "Tres días naturales", "Dos días hábiles"]'::jsonb,0,'Art. 48 a) TREBEP','Para familiares de segundo grado, cuatro días hábiles.',null),
('adm-cm:27-9bc20410d3','adm-cm',27,'Según el art. 54.6 TREBEP, los empleados públicos:','["Pueden aceptar regalos de cualquier valor siempre que los declaren a su superior jerárquico en el plazo de diez días desde su recepción y los inscriban en el registro", "Deben declarar los regalos recibidos en su declaración de bienes", "Solo pueden aceptar regalos de otros empleados públicos o de los ciudadanos, siempre que no superen el valor que fije cada Administración en su código ético", "Rechazarán cualquier regalo, favor o servicio en condiciones ventajosas que vaya más allá de los usos habituales, sociales y de cortesía"]'::jsonb,3,'Art. 54.6 TREBEP','Es un principio de conducta.',null),
('adm-cm:27-44cb7333fd','adm-cm',27,'Es un derecho individual de los empleados públicos del art. 14 TREBEP:','["La formación continua y la actualización permanente de sus conocimientos", "La negociación colectiva y la participación en la determinación de las condiciones de trabajo", "La huelga y el planteamiento de conflictos colectivos de trabajo en su unidad", "El planteamiento de conflictos colectivos de trabajo"]'::jsonb,0,'Art. 14 g) TREBEP','Los demás citados son derechos individuales ejercidos colectivamente (art. 15).',null),
('adm-cm:27-da12b76869','adm-cm',27,'A efectos de vacaciones de los funcionarios, los sábados:','["No se consideran días hábiles, salvo en los horarios especiales", "Computan doble", "Se consideran hábiles solo en agosto", "Se consideran siempre días hábiles, cualquiera que sea el horario del funcionario"]'::jsonb,0,'Art. 50.1 TREBEP','Las vacaciones son de 22 días hábiles.',null),
('adm-cm:27-e29493c705','adm-cm',27,'Para participar en la promoción interna, los funcionarios deben poseer una antigüedad de, al menos:','["Un año de servicio activo en el mismo cuerpo o escala", "Dos años de servicio activo en el inferior subgrupo o grupo de clasificación profesional", "Tres años de servicio activo en el mismo cuerpo o escala, de los cuales al menos uno en la misma Administración", "Cinco años de servicio activo en cualquier cuerpo o escala de la misma Administración pública"]'::jsonb,1,'Art. 18.2 TREBEP','Además de la titulación y demás requisitos exigidos.',null),
('adm-cm:27-45ccf459a6','adm-cm',27,'Por fallecimiento de un familiar de primer grado en la misma localidad, el permiso es de:','["Cinco días hábiles", "Tres días hábiles", "Dos días hábiles", "Un día"]'::jsonb,1,'Art. 48 a) TREBEP','Si es en distinta localidad, cinco días hábiles.',null),
('adm-cm:27-39e9ef683e','adm-cm',27,'Si la incapacidad temporal impide disfrutar las vacaciones en el año natural, podrán disfrutarse una vez finalizada, siempre que no hayan transcurrido más de:','["Un año a partir del final del año en que se hayan originado", "Tres años", "Seis meses a partir del final del año en que se hayan originado", "Dieciocho meses a partir del final del año en que se hayan originado"]'::jsonb,3,'Art. 50.2 TREBEP','Las vacaciones no pueden sustituirse por una cuantía económica, salvo cese no voluntario.',null),
('adm-cm:27-f3bf44ca5c','adm-cm',27,'En el permiso por nacimiento, ¿cuántas semanas inmediatas posteriores al parto son de descanso obligatorio?','["Dos semanas", "Seis semanas", "Diez semanas", "Cuatro semanas"]'::jsonb,1,'Art. 49 a) TREBEP','Las seis semanas posteriores al parto son obligatorias e ininterrumpidas.',null),
('adm-cm:28-f7d5da4687','adm-cm',28,'¿Cuál de estas NO es una situación administrativa de los funcionarios de carrera?','["Servicios especiales", "Excedencia", "Comisión de servicios", "Suspensión de funciones"]'::jsonb,2,'Art. 85.1 TREBEP','Las situaciones son servicio activo, servicios especiales, servicio en otras Administraciones Públicas, excedencia y suspensión de funciones. La comisión de servicios es una forma de provisión de puestos.','oct. 2026 · 1.er ejercicio'),
('adm-cm:28-9f4e2816e7','adm-cm',28,'Para obtener la excedencia voluntaria por interés particular hay que haber prestado servicios efectivos durante un mínimo de:','["Un año inmediatamente anterior a la solicitud", "Dos años inmediatamente anteriores", "Tres años, consecutivos o no, en cualquier Administración", "Cinco años inmediatamente anteriores"]'::jsonb,3,'Art. 89.2 TREBEP','Se exige haber prestado servicios efectivos en cualquier Administración durante un mínimo de cinco años inmediatamente anteriores.',null),
('adm-cm:28-ea8e04dd43','adm-cm',28,'La excedencia por cuidado de cada hijo tiene una duración:','["No superior a tres años", "No superior a un año", "No superior a cinco años", "Sin límite"]'::jsonb,0,'Art. 89.4 TREBEP','El periodo de excedencia por cuidado de cada hijo no puede ser superior a tres años.',null),
('adm-cm:28-f142c8ee7d','adm-cm',28,'La suspensión firme de funciones por sanción disciplinaria no puede exceder de:','["Tres años", "Seis años", "Dos años", "Un año"]'::jsonb,1,'Art. 90.2 TREBEP','No puede exceder de seis años. Si supera seis meses, el funcionario pierde su puesto de trabajo (art. 90.1).',null),
('adm-cm:28-2c43e53a6b','adm-cm',28,'Según el TREBEP, las faltas disciplinarias se clasifican en:','["Graves y leves", "Penales y administrativas", "Muy graves, graves y leves", "Muy graves y graves"]'::jsonb,2,'Art. 95.1 TREBEP','Las faltas disciplinarias pueden ser muy graves, graves y leves.',null),
('adm-cm:28-3a335bf7a9','adm-cm',28,'¿Cuál de las siguientes sanciones NO aparece expresamente en la lista del art. 96.1 del TREBEP?','["Apercibimiento", "Demérito", "Traslado forzoso", "Multa económica"]'::jsonb,3,'Art. 96.1 TREBEP','Recoge la separación del servicio, el despido disciplinario, la suspensión firme de funciones, el traslado forzoso, el demérito, el apercibimiento y cualquier otra que establezca una ley.',null),
('adm-cm:28-663ed39c97','adm-cm',28,'¿Cuándo prescriben las faltas leves?','["A los seis meses", "Al año", "A los dos años", "A los tres meses"]'::jsonb,0,'Art. 97 TREBEP','Las faltas muy graves prescriben a los tres años, las graves a los dos años y las leves a los seis meses.',null),
('adm-cm:28-c7f15e5bdb','adm-cm',28,'¿Cuándo prescriben las sanciones impuestas por faltas leves?','["A los seis meses", "Al año", "A los dos años", "A los tres años"]'::jsonb,1,'Art. 97 TREBEP','Las sanciones por faltas muy graves prescriben a los tres años, las graves a los dos años y las leves al año.','oct. 2026 · 1.er ejercicio'),
('adm-cm:28-bcc3aa10a8','adm-cm',28,'La suspensión provisional como medida cautelar en un expediente disciplinario no puede exceder de:','["Tres meses, salvo paralización del procedimiento imputable al interesado", "Un año, salvo paralización del procedimiento imputable a la Administración que lo tramita", "Seis meses, salvo paralización del procedimiento imputable al interesado", "Seis meses, sin excepción alguna"]'::jsonb,2,'Art. 98.3 TREBEP','No puede exceder de seis meses, salvo en caso de paralización del procedimiento imputable al interesado.',null),
('adm-cm:28-55ebbab79e','adm-cm',28,'El plazo de prescripción de las sanciones comenzará a contarse:','["Desde la firmeza de la resolución sancionadora", "Desde la notificación del pliego de cargos", "Desde la incoación del expediente", "Desde la comisión de la falta"]'::jsonb,0,'Art. 97 TREBEP','El de las faltas, desde que se hubieran cometido, o desde el cese de su comisión si son continuadas.',null),
('adm-cm:28-ee58187867','adm-cm',28,'Las faltas leves se sancionarán:','["Solo por un juez", "Sin procedimiento", "Por el procedimiento previsto para las faltas graves y muy graves", "Por un procedimiento sumario con audiencia al interesado"]'::jsonb,3,'Art. 98.1 TREBEP','Las faltas muy graves y graves exigen el procedimiento previamente establecido.',null),
('adm-cm:28-b5334a28b3','adm-cm',28,'La suspensión de funciones determinará la pérdida del puesto de trabajo cuando exceda de:','["Un año", "Tres meses", "Un mes", "Seis meses"]'::jsonb,3,'Art. 90.1 TREBEP','El funcionario suspenso queda privado del ejercicio de sus funciones.',null),
('adm-cm:28-43d44fd226','adm-cm',28,'Durante la suspensión provisional como medida cautelar, el funcionario:','["Percibe íntegramente sus retribuciones hasta que se resuelva el expediente disciplinario", "No percibe ninguna retribución", "Percibirá las retribuciones básicas y, en su caso, las prestaciones familiares por hijo a cargo", "Percibirá las retribuciones complementarias, pero no las básicas"]'::jsonb,2,'Art. 98.3 TREBEP','Si la suspensión se eleva a definitiva, deberá devolver lo percibido.',null),
('adm-cm:28-a062ed9c72','adm-cm',28,'Durante los dos primeros años de excedencia por cuidado de hijos o familiares, el funcionario tiene derecho a:','["Ascender automáticamente de grado", "Nada, salvo el cómputo de antigüedad", "La reserva del puesto de trabajo que desempeñaba", "Seguir percibiendo las retribuciones básicas y la reserva de un puesto en la misma localidad"]'::jsonb,2,'Art. 89.4 TREBEP','Transcurrido ese periodo, la reserva lo es a un puesto en la misma localidad y de igual retribución.',null),
('adm-cm:28-27d42b52b6','adm-cm',28,'Las sanciones impuestas por faltas graves prescriben a los:','["Un año", "Dos años", "Tres años", "Seis meses"]'::jsonb,1,'Art. 97 TREBEP','Las muy graves a los tres años y las leves al año.',null),
('adm-cm:28-1082ba238b','adm-cm',28,'Las faltas muy graves prescriben a los:','["Dos años", "Seis meses", "Cinco años", "Tres años"]'::jsonb,3,'Art. 97 TREBEP','Las graves a los dos años y las leves a los seis meses.',null),
('adm-cm:28-0029c292e3','adm-cm',28,'Durante los dos primeros meses de excedencia por razón de violencia de género, la funcionaria tendrá derecho a:','["No percibir retribución alguna, aunque se le reserva el puesto de trabajo y se computa el tiempo a efectos de antigüedad", "Percibir las retribuciones íntegras y, en su caso, las prestaciones familiares por hijo a cargo", "Percibir el 50 % de sus retribuciones básicas y complementarias", "Percibir solo las retribuciones básicas, pero no las complementarias ni las prestaciones familiares por hijo a cargo"]'::jsonb,1,'Art. 89.5 TREBEP','Durante los seis primeros meses tiene reserva del puesto, prorrogable por periodos de tres meses hasta dieciocho.',null),
('adm-cm:28-26d384f094','adm-cm',28,'La excedencia por cuidado de un familiar hasta el segundo grado que no pueda valerse por sí mismo tiene una duración no superior a:','["Tres años", "Dos años", "Cinco años", "Un año"]'::jsonb,0,'Art. 89.4 TREBEP','Igual que la excedencia por cuidado de cada hijo.',null),
('adm-cm:28-f3f0a931f4','adm-cm',28,'Es una falta muy grave según el art. 95.2 TREBEP:','["El descuido leve en el trabajo", "El abandono del servicio", "La falta de puntualidad ocasional", "Un retraso de diez minutos"]'::jsonb,1,'Art. 95.2 c) TREBEP','Otras faltas muy graves: desobediencia abierta, acoso laboral, etc.','nov. 2024 · 1.er ejercicio'),
('adm-cm:28-3df95677b7','adm-cm',28,'La sanción de separación del servicio de los funcionarios solo podrá imponerse por:','["Faltas graves reiteradas en el plazo de un año", "Cualquier falta", "La comisión de faltas muy graves", "Faltas graves cometidas de forma reiterada"]'::jsonb,2,'Art. 96.1 a) TREBEP','En los interinos implica la revocación del nombramiento.',null),
('adm-cm:28-3558366430','adm-cm',28,'¿Cuál de las siguientes NO es una situación administrativa de los funcionarios de carrera según el artículo 85 del TREBEP?','["Servicios especiales", "Suspensión de funciones", "Servicio en otras Administraciones Públicas", "Expectativa de destino indefinida"]'::jsonb,3,'Art. 85.1 TREBEP','Las situaciones son servicio activo, servicios especiales, servicio en otras Administraciones Públicas, excedencia y suspensión de funciones.',null),
('adm-cm:28-b20ea97764','adm-cm',28,'Los funcionarios que acceden a la condición de diputado o senador de las Cortes Generales pasan a la situación de:','["Suspensión provisional de funciones", "Servicio activo con dispensa de funciones", "Excedencia voluntaria por interés particular", "Servicios especiales"]'::jsonb,3,'Art. 87.1 TREBEP','Tienen derecho a reingresar al servicio activo en la misma localidad y en las mismas condiciones y con las retribuciones correspondientes a su categoría.',null),
('adm-cm:28-88c5f0ee26','adm-cm',28,'Según el TREBEP, los funcionarios en situación de servicios especiales:','["Pierden la condición de funcionario mientras dure la situación", "No tienen derecho a reserva de puesto ni a que se les compute el tiempo a ningún efecto", "Solo tienen derecho al cómputo de trienios, pero no a la reserva de puesto", "Tienen derecho a que se les compute el tiempo en esa situación a efectos de ascensos, reconocimiento de trienios y derechos en el régimen de Seguridad Social"]'::jsonb,3,'Art. 87.2 TREBEP','No se les aplica, sin embargo, el régimen de derechos pasivos si les corresponde otro.',null),
('adm-cm:29-6367240502','adm-cm',29,'Según el TREBEP, ¿por qué normas se rige el personal laboral al servicio de las Administraciones públicas?','["Por el TREBEP en su totalidad, igual que los funcionarios de carrera, sin aplicar la legislación laboral", "Por la ley de función pública de cada comunidad autónoma", "Por la legislación laboral, las normas convencionales y los preceptos del Estatuto que así lo dispongan", "Exclusivamente por el Estatuto de los Trabajadores"]'::jsonb,2,'Art. 7 TREBEP','El personal laboral se rige por la legislación laboral, las normas convencionales y los preceptos del Estatuto que así lo dispongan.',null),
('adm-cm:29-349408f252','adm-cm',29,'¿Qué norma se aplica al personal laboral de las Administraciones en materia de permiso por nacimiento o lactancia?','["El Estatuto de los Trabajadores, en todo caso", "El TREBEP, y no las suspensiones del contrato del Estatuto de los Trabajadores", "La Ley General de la Seguridad Social exclusivamente", "El convenio colectivo, con preferencia sobre cualquier ley"]'::jsonb,1,'Art. 7 TREBEP','En permisos de nacimiento, adopción, del otro progenitor, lactancia y parental, el personal laboral se rige por el TREBEP.',null),
('adm-cm:29-dbc905f20d','adm-cm',29,'Según el TREBEP, ¿cómo debe formalizarse el contrato del personal laboral de las Administraciones?','["Mediante resolución publicada en el boletín oficial", "Por escrito", "De palabra o por escrito, indistintamente", "En documento administrativo ante el secretario general técnico"]'::jsonb,1,'Art. 11.1 TREBEP','Es personal laboral el que, en virtud de contrato de trabajo formalizado por escrito, presta servicios retribuidos por las Administraciones.',null),
('adm-cm:29-523088010a','adm-cm',29,'Según su duración, ¿cómo puede ser el contrato del personal laboral de las Administraciones?','["Estable, discontinuo o de obra", "Indefinido o de interinidad", "Fijo, por tiempo indefinido o temporal", "Fijo o eventual"]'::jsonb,2,'Art. 11.1 TREBEP','En función de la duración del contrato, el personal laboral puede ser fijo, por tiempo indefinido o temporal.',null),
('adm-cm:29-4eb2681522','adm-cm',29,'¿Por qué principios se rige la selección del personal laboral temporal según el TREBEP?','["Igualdad, mérito, capacidad y celeridad", "Antigüedad y proximidad geográfica", "Igualdad y antigüedad únicamente", "Libre designación y confianza"]'::jsonb,0,'Art. 11.3 TREBEP','La selección del personal laboral es pública y se rige por igualdad, mérito y capacidad; la del temporal, además, por la celeridad.',null),
('adm-cm:29-eacea1704c','adm-cm',29,'¿Por qué se rige la negociación colectiva del personal laboral de las Administraciones?','["Por la Ley Orgánica de Libertad Sindical únicamente", "Exclusivamente por el TREBEP", "Por los acuerdos de las mesas generales de funcionarios", "Por la legislación laboral, sin perjuicio de los preceptos del TREBEP aplicables"]'::jsonb,3,'Art. 32.1 TREBEP','La negociación colectiva, representación y participación del personal laboral se rige por la legislación laboral, con los preceptos del capítulo aplicables.',null),
('adm-cm:29-ab9c9a3930','adm-cm',29,'¿Pueden los órganos de gobierno de las Administraciones suspender un convenio colectivo del personal laboral ya firmado?','["Solo si lo aprueba la mayoría de los trabajadores", "Sí, por simple decisión del titular de la consejería afectada, sin necesidad de causa justificada ni de informar a los sindicatos", "No, en ningún caso", "Sí, excepcionalmente y por causa grave de interés público derivada de una alteración sustancial de las circunstancias económicas"]'::jsonb,3,'Art. 32.2 TREBEP','Excepcionalmente, por causa grave de interés público derivada de una alteración sustancial de las circunstancias económicas, pueden suspenderse o modificarse en lo estrictamente necesario.',null),
('adm-cm:29-21774ca5cb','adm-cm',29,'Si se suspende o modifica un convenio del personal laboral, ¿a quién debe informar la Administración?','["Al Tribunal Superior de Justicia", "A las organizaciones sindicales", "A la Inspección de Trabajo exclusivamente", "Al Parlamento autonómico"]'::jsonb,1,'Art. 32.2 TREBEP','Las Administraciones deberán informar a las organizaciones sindicales de las causas de la suspensión o modificación.',null),
('adm-cm:29-3fb5697cda','adm-cm',29,'¿Cómo se realiza la provisión de puestos y la movilidad del personal laboral según el TREBEP?','["Por concurso de méritos convocado en todo caso por la Dirección General de Función Pública de la comunidad", "Por el sistema del Estatuto de los Trabajadores exclusivamente", "Según los convenios colectivos y, en su defecto, por el sistema del personal funcionario de carrera", "Siempre por libre designación"]'::jsonb,2,'Art. 83 TREBEP','Se realiza conforme a los convenios colectivos y, en su defecto, por el sistema de provisión y movilidad del personal funcionario de carrera.',null),
('adm-cm:29-338a73ef02','adm-cm',29,'¿Por qué normas se rigen las situaciones del personal laboral según el TREBEP?','["Por el Estatuto de los Trabajadores y los convenios colectivos", "Por el reglamento de situaciones de los funcionarios del Estado", "Por el capítulo de situaciones administrativas del TREBEP", "Por la ley de función pública autonómica"]'::jsonb,0,'Art. 92 TREBEP','Se rigen por el Estatuto de los Trabajadores y los convenios; estos pueden aplicar el capítulo del TREBEP en lo compatible.',null),
('adm-cm:29-4dba9aa69f','adm-cm',29,'¿Cómo se determinan las retribuciones del personal laboral según el TREBEP?','["Libremente por el órgano contratante", "Por decreto del Consejo de Gobierno cada año", "Según las mismas tablas retributivas que los funcionarios del grupo equivalente, fijadas cada año por decreto del Gobierno", "Según la legislación laboral, el convenio colectivo y el contrato, respetando los límites de la ley de presupuestos"]'::jsonb,3,'Art. 27 TREBEP','Se determinan de acuerdo con la legislación laboral, el convenio aplicable y el contrato, respetando el art. 21 del TREBEP.',null),
('adm-cm:30-14233d5cfc','adm-cm',30,'Según el Estatuto de los Trabajadores, ¿a quién se aplica la ley?','["A los trabajadores autónomos económicamente dependientes", "A quienes presten voluntariamente servicios retribuidos por cuenta ajena dentro del ámbito de organización y dirección de otra persona", "A cualquier persona que realice un trabajo, sea o no retribuido", "A todas las personas que presten servicios a una Administración pública, ya sean funcionarios, personal eventual o personal laboral"]'::jsonb,1,'Art. 1.1 ET','El ET se aplica a quienes voluntariamente presten servicios retribuidos por cuenta ajena y dentro del ámbito de organización y dirección del empleador.',null),
('adm-cm:30-2fdd5b4544','adm-cm',30,'¿Cuál de estas relaciones excluye el Estatuto de los Trabajadores de su ámbito?','["Los trabajos realizados a título de amistad, benevolencia o buena vecindad", "La del personal laboral de las Administraciones públicas", "La de los trabajadores a tiempo parcial", "La de los trabajadores contratados por empresas de trabajo temporal y cedidos a empresas usuarias"]'::jsonb,0,'Art. 1.3 ET','Se excluyen, entre otros, los trabajos a título de amistad, benevolencia o buena vecindad; el personal laboral público sí se rige por el ET.',null),
('adm-cm:30-3742d393dd','adm-cm',30,'¿A partir de qué edad se permite la admisión al trabajo según el Estatuto de los Trabajadores?','["Quince años", "Dieciocho años", "Dieciséis años", "Catorce años"]'::jsonb,2,'Art. 6.1 ET','Se prohíbe la admisión al trabajo a los menores de dieciséis años.',null),
('adm-cm:30-5117ffd71c','adm-cm',30,'¿Pueden realizar horas extraordinarias los menores de dieciocho años?','["Sí, con autorización de sus padres", "Sí, hasta un máximo de 40 al año", "Sí, si lo prevé el convenio colectivo", "No"]'::jsonb,3,'Art. 6.3 ET','Se prohíbe realizar horas extraordinarias a los menores de dieciocho años.',null),
('adm-cm:30-c25c9b230d','adm-cm',30,'¿Cómo puede celebrarse el contrato de trabajo según el Estatuto de los Trabajadores?','["De palabra solo si dura menos de una semana", "Por escrito o de palabra", "Por escrito y ante la oficina de empleo", "Solo por escrito"]'::jsonb,1,'Art. 8.1 ET','El contrato de trabajo se podrá celebrar por escrito o de palabra.',null),
('adm-cm:30-056b6c8131','adm-cm',30,'Si no se formaliza por escrito un contrato que debía serlo, ¿cómo se presume celebrado?','["Por tiempo indefinido y a jornada completa, salvo prueba en contrario", "Por obra o servicio determinado y a tiempo parcial, salvo prueba en contrario", "Nulo de pleno derecho", "Por seis meses y a jornada completa"]'::jsonb,0,'Art. 8.2 ET','Se presumirá celebrado por tiempo indefinido y a jornada completa, salvo prueba en contrario.',null),
('adm-cm:30-a2171c0cd1','adm-cm',30,'¿En qué plazo debe comunicar el empresario a la oficina pública de empleo el contenido de los contratos?','["Quince días", "Cinco días", "Diez días", "Un mes"]'::jsonb,2,'Art. 8.3 ET','El empresario debe comunicarlo en los diez días siguientes a su concertación.',null),
('adm-cm:30-b274e7fbf3','adm-cm',30,'¿Cuál es la duración mínima y máxima del contrato de formación en alternancia?','["Mínimo tres meses y máximo dos años", "Mínimo seis meses y máximo un año", "Mínimo seis meses y máximo dos años", "Mínimo un mes y máximo tres años"]'::jsonb,0,'Art. 11.2 ET','La duración será la del plan formativo, con un mínimo de tres meses y un máximo de dos años.',null),
('adm-cm:30-0a858dd092','adm-cm',30,'En el contrato de formación en alternancia, ¿qué porcentaje máximo de tiempo de trabajo efectivo se permite el primer año?','["El 85 % de la jornada máxima", "El 65 % de la jornada máxima", "El 50 % de la jornada máxima", "El 75 % de la jornada máxima"]'::jsonb,1,'Art. 11.2 ET','No puede superar el 65 % el primer año ni el 85 % el segundo, de la jornada máxima de convenio o legal.',null),
('adm-cm:30-311ca7ed85','adm-cm',30,'¿Puede establecerse periodo de prueba en el contrato de formación en alternancia?','["Sí, el que fije el convenio colectivo", "Sí, de un mes como máximo", "No", "Sí, de quince días"]'::jsonb,2,'Art. 11.2 ET','No podrá establecerse periodo de prueba en el contrato de formación en alternancia.',null),
('adm-cm:30-11cd269e14','adm-cm',30,'¿Dentro de qué plazo tras terminar los estudios debe concertarse el contrato para la obtención de práctica profesional?','["Cinco años, o siete si es una persona con discapacidad", "Cuatro años desde la obtención del título", "Dos años, sin excepciones", "Tres años, o cinco si se trata de una persona con discapacidad"]'::jsonb,3,'Art. 11.3 ET','Debe concertarse dentro de los tres años, o cinco si se trata de una persona con discapacidad, siguientes a la terminación de los estudios.',null),
('adm-cm:30-d658f430bb','adm-cm',30,'¿Qué duración tiene el contrato para la obtención de práctica profesional?','["No inferior a un año ni superior a tres", "No inferior a seis meses ni superior a un año", "No inferior a un mes ni superior a seis meses", "No inferior a tres meses ni superior a dos años"]'::jsonb,1,'Art. 11.3 ET','La duración no podrá ser inferior a seis meses ni exceder de un año.',null),
('adm-cm:30-2b9639e21e','adm-cm',30,'Salvo justificación en convenio, ¿cuál es la duración máxima del periodo de prueba para técnicos titulados?','["Dos meses", "Tres meses", "Un año", "Seis meses"]'::jsonb,3,'Art. 14.1 ET','No podrá exceder de seis meses para técnicos titulados ni de dos meses para las demás personas trabajadoras.',null),
('adm-cm:30-e96860a4d7','adm-cm',30,'En empresas de menos de veinticinco trabajadores, ¿cuál es el periodo de prueba máximo para quienes no son técnicos titulados?','["Seis meses", "Dos meses", "Tres meses", "Un mes"]'::jsonb,2,'Art. 14.1 ET','En empresas de menos de veinticinco personas trabajadoras no podrá exceder de tres meses para quienes no sean técnicos titulados.',null),
('adm-cm:30-2c48381c09','adm-cm',30,'En contratos de duración determinada de seis meses o más, ¿cuál es el periodo de prueba máximo?','["Un mes", "Tres meses", "Quince días", "Dos meses"]'::jsonb,0,'Art. 14.1 ET','En contratos de duración determinada por periodo igual o superior a seis meses, el periodo de prueba no podrá exceder de un mes.',null),
('adm-cm:30-693863f22d','adm-cm',30,'¿Es válido un periodo de prueba si el trabajador ya desempeñó las mismas funciones en la empresa?','["No, el pacto es nulo", "Sí, si lo prevé el convenio colectivo", "Sí, si se reduce a la mitad", "Sí, si ha pasado más de un año"]'::jsonb,0,'Art. 14.1 ET','Es nulo el pacto de periodo de prueba cuando la persona ya haya desempeñado las mismas funciones en la empresa bajo cualquier modalidad.',null),
('adm-cm:30-dbfe4ea9da','adm-cm',30,'¿Cómo se presume concertado el contrato de trabajo según el art. 15 del Estatuto?','["A tiempo parcial", "Por obra o servicio determinado", "Por tiempo determinado de un año", "Por tiempo indefinido"]'::jsonb,3,'Art. 15.1 ET','El contrato de trabajo se presume concertado por tiempo indefinido.',null),
('adm-cm:30-047baae2fb','adm-cm',30,'¿Por qué causas puede celebrarse un contrato de duración determinada según el Estatuto?','["Por circunstancias de la producción, obra o servicio y sustitución", "Por obra o servicio determinado o por lanzamiento de nueva actividad", "Por circunstancias de la producción o por sustitución de persona trabajadora", "Por cualquier causa que se especifique en el contrato"]'::jsonb,2,'Art. 15.1 ET','Solo puede celebrarse por circunstancias de la producción o por sustitución de persona trabajadora.',null),
('adm-cm:30-79ed606553','adm-cm',30,'¿Cuál es la duración máxima legal del contrato por circunstancias de la producción imprevisibles?','["Tres meses, sin posibilidad de ampliación", "Seis meses, ampliable a un año por convenio sectorial", "Doce meses en un periodo de dieciocho", "Un año, ampliable a dieciocho meses por convenio"]'::jsonb,1,'Art. 15.2 ET','No podrá ser superior a seis meses; por convenio sectorial podrá ampliarse hasta un año.',null),
('adm-cm:30-40888c6b04','adm-cm',30,'¿Cuántos días al año pueden usar las empresas, con carácter general, el contrato por circunstancias de la producción previsibles y de duración reducida?','["Treinta días por trimestre", "Sesenta días en el año natural", "Noventa días en el año natural", "Ciento veinte días en el año natural"]'::jsonb,2,'Art. 15.2 ET','Solo podrán utilizarlo un máximo de noventa días en el año natural (120 en el sector agrario y agroalimentario), sin uso continuado.',null),
('adm-cm:30-16696e90ff','adm-cm',30,'Cuando el contrato de sustitución cubre un puesto durante un proceso de selección, ¿cuál es su duración máxima legal?','["Seis meses", "Tres meses", "Hasta que termine el proceso, sin límite", "Un año"]'::jsonb,1,'Art. 15.3 ET','No podrá ser superior a tres meses, o el plazo inferior del convenio colectivo.',null),
('adm-cm:30-64ebae726c','adm-cm',30,'¿Cuándo adquiere la condición de fija una persona encadenando contratos por circunstancias de la producción?','["Si en doce meses ha estado contratada más de seis", "Si en treinta meses ha estado contratada más de veinticuatro mediante tres o más contratos temporales", "Si encadena tres contratos, sea cual sea su duración total", "Si en veinticuatro meses ha estado contratada más de dieciocho meses mediante dos o más contratos"]'::jsonb,3,'Art. 15.5 ET','Adquiere la condición de fija quien en veinticuatro meses haya estado contratado más de dieciocho mediante dos o más contratos por circunstancias de la producción.',null),
('adm-cm:30-bc4532c81c','adm-cm',30,'Al finalizar un contrato temporal por circunstancias de la producción, ¿qué indemnización corresponde?','["La parte proporcional de doce días de salario por año de servicio", "Ninguna, al tratarse de un contrato temporal", "Veinte días de salario por año de servicio", "Ocho días de salario por año de servicio"]'::jsonb,0,'Art. 49.1 ET','Excepto en los formativos y de sustitución, corresponde la parte proporcional de doce días de salario por año de servicio.',null),
('adm-cm:30-a22a06512a','adm-cm',30,'Si un contrato de duración determinada es superior a un año, ¿con qué antelación debe notificarse su terminación?','["Un mes", "Quince días", "Siete días", "Diez días"]'::jsonb,1,'Art. 49.1 ET','La parte que formule la denuncia debe notificar la terminación con una antelación mínima de quince días.',null),
('adm-cm:30-4198b09ea6','adm-cm',30,'En caso de muerte, jubilación o incapacidad del empresario persona física, ¿a qué tiene derecho el trabajador?','["Al abono de una cantidad equivalente a un mes de salario", "A la readmisión por los herederos en todo caso", "A veinte días de salario por año de servicio", "A treinta y tres días de salario por año de servicio"]'::jsonb,0,'Art. 49.1 ET','En los casos de muerte, jubilación o incapacidad del empresario, el trabajador tiene derecho a una cantidad equivalente a un mes de salario.',null),
('adm-cm:30-61c754b8eb','adm-cm',30,'¿Qué indemnización corresponde por la extinción del contrato por causas objetivas?','["Cuarenta y cinco días por año, con un máximo de cuarenta y dos mensualidades", "Treinta y tres días por año, con un máximo de veinticuatro mensualidades", "Veinte días por año de servicio, con un máximo de doce mensualidades", "Doce días por año, sin máximo"]'::jsonb,2,'Art. 53.1 ET','Se debe poner a disposición la indemnización de veinte días por año de servicio, con un máximo de doce mensualidades.',null),
('adm-cm:30-244ce2edd1','adm-cm',30,'Declarado improcedente un despido, ¿en qué plazo puede optar el empresario entre readmisión o indemnización?','["Quince días desde la firmeza de la sentencia", "Tres días desde el acto de conciliación", "Diez días desde la notificación de la sentencia", "Cinco días desde la notificación de la sentencia"]'::jsonb,3,'Art. 56.1 ET','El empresario puede optar en el plazo de cinco días desde la notificación de la sentencia.',null),
('adm-cm:30-ab6f0ba076','adm-cm',30,'¿Qué indemnización corresponde por despido improcedente si el empresario no readmite?','["Treinta días de salario por año, hasta dieciocho mensualidades", "Cuarenta y cinco días de salario por año, hasta cuarenta y dos mensualidades", "Treinta y tres días de salario por año, hasta veinticuatro mensualidades", "Veinte días de salario por año, hasta doce mensualidades"]'::jsonb,2,'Art. 56.1 ET','La indemnización equivale a treinta y tres días de salario por año de servicio, hasta un máximo de veinticuatro mensualidades.',null),
('adm-cm:31-491461492d','adm-cm',31,'El sistema de la Seguridad Social se fundamenta en los principios de:','["Universalidad, unidad, solidaridad e igualdad", "Contributividad, capitalización y rentabilidad", "Descentralización y autonomía", "Voluntariedad y suficiencia"]'::jsonb,0,'Art. 2.1 TRLGSS','Se fundamenta en los principios de universalidad, unidad, solidaridad e igualdad.','abr. 2026 · 1.er ejercicio'),
('adm-cm:31-367bb8a014','adm-cm',31,'El sistema de la Seguridad Social se integra por:','["Un único régimen para todos los trabajadores, sean o no autónomos", "El Régimen General y los Regímenes Especiales", "El Régimen General, los regímenes autonómicos y las mutualidades privadas de previsión social", "El Régimen de Autónomos y el de funcionarios"]'::jsonb,1,'Art. 9.1 TRLGSS','Lo integran el Régimen General y los Regímenes Especiales.','abr. 2026 · 1.er ejercicio'),
('adm-cm:31-1144cb14fb','adm-cm',31,'La afiliación a la Seguridad Social es:','["Voluntaria, y se renueva al comienzo de cada actividad o empleo", "Obligatoria solo para los trabajadores por cuenta ajena, y distinta para cada uno de sus empleos o actividades", "Obligatoria para las personas del art. 7.1 y única para toda su vida y para todo el sistema", "Obligatoria, pero se renueva para cada régimen en que se trabaje"]'::jsonb,2,'Art. 15 TRLGSS','Es obligatoria para las personas del art. 7.1 y única para toda su vida y para todo el sistema.',null),
('adm-cm:31-713a5b9624','adm-cm',31,'La obligación de cotizar nace:','["Al año del inicio de la actividad", "Con la firma del contrato de trabajo, aunque la actividad comience más tarde", "Al cobrar la primera nómina", "Desde el momento de iniciación de la actividad correspondiente"]'::jsonb,3,'Art. 18.2 TRLGSS','Nace desde el momento de iniciación de la actividad correspondiente.',null),
('adm-cm:31-99e5437f19','adm-cm',31,'¿En qué plazo prescribe el derecho de la Administración a determinar y exigir las deudas por cuotas?','["Cuatro años", "Cinco años", "Tres años", "Diez años"]'::jsonb,0,'Art. 24.1 TRLGSS','Prescriben a los cuatro años.',null),
('adm-cm:31-26bce6dd02','adm-cm',31,'En el Régimen General de la Seguridad Social están comprendidos:','["Los trabajadores autónomos y asimilados", "Los trabajadores por cuenta ajena y asimilados", "Los trabajadores por cuenta ajena, salvo los que presten servicios en Administraciones públicas o en empresas públicas", "Los funcionarios de carrera de todas las Administraciones"]'::jsonb,1,'Art. 136.1 TRLGSS','Están comprendidos los trabajadores por cuenta ajena y los asimilados, salvo que deban estar en un régimen especial.',null)
insert into public.preguntas (id,oposicion,tema,pregunta,opciones,correcta,articulo,explicacion,examen) values
('adm-cm:31-d707bfec79','adm-cm',31,'Según el art. 137 TRLGSS, NO dan lugar a inclusión en el Régimen General:','["Los trabajos por cuenta ajena de carácter temporal", "Los funcionarios incluidos por ley", "Los trabajos ocasionales realizados por servicios amistosos, benévolos o de buena vecindad", "Los socios trabajadores de cooperativas asimilados por ley a trabajadores por cuenta ajena"]'::jsonb,2,'Art. 137 a) TRLGSS','Es una de las exclusiones del Régimen General.',null),
('adm-cm:31-145ecd86c2','adm-cm',31,'Si se ingresan las cuotas durante el primer mes natural siguiente al vencimiento del plazo reglamentario, habiendo presentado los documentos de cotización en plazo, el recargo es del:','["10 %", "20 %", "35 %", "5 %"]'::jsonb,0,'Art. 30.1 a) TRLGSS','Si se pagan a partir del segundo mes, el recargo es del 20 %.',null),
('adm-cm:31-7d4955a134','adm-cm',31,'Las bases y tipos de cotización a la Seguridad Social se fijan cada año en:','["Una orden de la Tesorería General de la Seguridad Social", "Los convenios colectivos de cada sector", "La Ley de Presupuestos Generales del Estado", "Un real decreto del Gobierno, previo acuerdo con los agentes sociales"]'::jsonb,2,'Art. 19.1 TRLGSS','La base mínima es, salvo disposición en contrario, el SMI incrementado en un sexto.','abr. 2026 · 1.er ejercicio'),
('adm-cm:31-d18c78405e','adm-cm',31,'Es un régimen especial de la Seguridad Social según el art. 10.2 TRLGSS:','["El de los trabajadores por cuenta propia o autónomos", "El de los empleados de comercio", "El de los trabajadores de banca y entidades financieras", "El de los trabajadores de la construcción"]'::jsonb,0,'Art. 10.2 a) TRLGSS','También el de trabajadores del mar, funcionarios públicos civiles y militares y estudiantes.',null),
('adm-cm:31-3acb5d3937','adm-cm',31,'El derecho a la devolución de ingresos indebidos en materia de Seguridad Social prescribe a los:','["Cinco años desde el día siguiente al ingreso", "Diez años desde el día siguiente al ingreso", "Un año desde el día siguiente al ingreso", "Cuatro años desde el día siguiente al ingreso"]'::jsonb,3,'Art. 26.3 TRLGSS','Coincide con el plazo de prescripción de las deudas por cuotas.',null),
('adm-cm:31-e788b8bc0f','adm-cm',31,'Están comprendidos en el sistema de la Seguridad Social, a efectos de las prestaciones contributivas, los trabajadores por cuenta propia o autónomos:','["Mayores de dieciocho años", "Mayores de dieciséis años", "Mayores de veintiún años", "De cualquier edad"]'::jsonb,0,'Art. 7.1 b) TRLGSS','El art. 7.1 enumera los incluidos en el campo de aplicación contributivo.',null),
('adm-cm:32-5c931b8b14','adm-cm',32,'La acción protectora de la Seguridad Social comprende, entre otras:','["Las becas universitarias, las ayudas a la vivienda para jóvenes y los préstamos personales sin interés a los afiliados y a sus familiares directos", "La asistencia sanitaria y las prestaciones por incapacidad temporal, nacimiento y cuidado de menor, incapacidad permanente y jubilación", "La asistencia sanitaria, las becas de estudio, las ayudas a la vivienda y los préstamos personales sin interés a los afiliados y a sus familiares", "Las prestaciones por jubilación, pero no la asistencia sanitaria"]'::jsonb,1,'Art. 42.1 TRLGSS','Incluye la asistencia sanitaria y prestaciones por incapacidad temporal, nacimiento y cuidado de menor, incapacidad permanente, jubilación, desempleo y muerte y supervivencia, entre otras.',null),
('adm-cm:32-625e8fb5d1','adm-cm',32,'¿Cuál de las siguientes NO figura entre las entidades gestoras del art. 66.1 del TRLGSS?','["El Instituto Nacional de la Seguridad Social", "El Instituto de Mayores y Servicios Sociales", "La Tesorería General de la Seguridad Social", "El Instituto Nacional de Gestión Sanitaria"]'::jsonb,2,'Arts. 66.1 y 74.1 TRLGSS','Las entidades gestoras son el INSS, el INGESA y el IMSERSO. La Tesorería General es un servicio común.','oct. 2026 · 1.er ejercicio'),
('adm-cm:32-9a49545059','adm-cm',32,'La Tesorería General de la Seguridad Social es:','["Una entidad gestora con personalidad jurídica propia", "Una mutua colaboradora con la Seguridad Social, sin ánimo de lucro", "Un organismo autónomo dependiente de cada Comunidad Autónoma, que gestiona sus recursos financieros propios", "Un servicio común con personalidad jurídica propia, en el que se unifican los recursos financieros"]'::jsonb,3,'Art. 74.1 TRLGSS','Es un servicio común con personalidad jurídica propia que aplica los principios de solidaridad financiera y caja única.',null),
('adm-cm:32-1fd85cbf42','adm-cm',32,'Las mutuas colaboradoras con la Seguridad Social son:','["Asociaciones privadas de empresarios, sin ánimo de lucro", "Asociaciones privadas de trabajadores, sin ánimo de lucro, autorizadas por el Ministerio competente en materia de Seguridad Social", "Empresas públicas de la Administración del Estado", "Compañías de seguros con ánimo de lucro"]'::jsonb,0,'Art. 80.1 TRLGSS','Son asociaciones privadas de empresarios, autorizadas por el Ministerio, que actúan sin ánimo de lucro.',null),
('adm-cm:32-a96fd0231b','adm-cm',32,'Se entiende por accidente de trabajo:','["Toda enfermedad del trabajador, aunque no tenga relación con el trabajo que realiza", "Solo la lesión sufrida en el centro de trabajo durante la jornada", "Toda lesión corporal sufrida durante la jornada, aunque sea por fuerza mayor extraña al trabajo y por imprudencia temeraria del trabajador", "Toda lesión corporal que el trabajador sufra con ocasión o por consecuencia del trabajo por cuenta ajena"]'::jsonb,3,'Art. 156.1 TRLGSS','Es toda lesión corporal que el trabajador sufra con ocasión o por consecuencia del trabajo que ejecute por cuenta ajena.',null),
('adm-cm:32-f0e3bb44e5','adm-cm',32,'El accidente que sufre el trabajador al ir o volver del lugar de trabajo:','["Tiene la consideración de accidente de trabajo", "Es siempre accidente no laboral", "Solo es accidente de trabajo si ocurre en transporte público", "Es una enfermedad profesional"]'::jsonb,0,'Art. 156.2 a) TRLGSS','Tienen la consideración de accidente de trabajo los sufridos al ir o volver del lugar de trabajo (accidente in itinere).',null),
('adm-cm:32-b7be5eb933','adm-cm',32,'La enfermedad profesional es la contraída a consecuencia del trabajo por cuenta ajena:','["En cualquier actividad, siempre que lo acredite un informe médico", "En las actividades del cuadro aprobado reglamentariamente, provocada por los elementos o sustancias que en él se indiquen", "En las actividades que fije cada convenio colectivo, provocada por los elementos o sustancias que señale la mutua o la empresa en cada caso concreto", "En la industria química y minera, tras al menos diez años de trabajo"]'::jsonb,1,'Art. 157 TRLGSS','Es la contraída en las actividades del cuadro reglamentario y provocada por los elementos o sustancias que ese cuadro indica.',null),
('adm-cm:32-f894c89284','adm-cm',32,'La incapacidad temporal por enfermedad o accidente tiene una duración máxima de:','["180 días, prorrogables por otros 180", "Dos años, prorrogables por otros seis meses cuando se prevea el alta", "365 días, prorrogables por otros 180 cuando se prevea el alta médica por curación", "365 días, prorrogables por otros 365 cuando se prevea el alta médica por curación o mejoría"]'::jsonb,2,'Art. 169.1 a) TRLGSS','Trescientos sesenta y cinco días, prorrogables por otros ciento ochenta cuando se presuma que el trabajador será dado de alta por curación.',null),
('adm-cm:32-28d028f7cb','adm-cm',32,'¿Cuál de estas situaciones protege la prestación del art. 177 del TRLGSS?','["La jubilación anticipada por voluntad del interesado o por causa no imputable", "La situación legal de desempleo derivada de la extinción del contrato por cuidado de menores", "La incapacidad permanente total para la profesión habitual del trabajador", "El nacimiento, la adopción, la guarda con fines de adopción y el acogimiento"]'::jsonb,3,'Art. 177 TRLGSS','Protege el nacimiento, la adopción, la guarda con fines de adopción y el acogimiento.',null),
('adm-cm:32-c673766368','adm-cm',32,'La incapacidad permanente se clasifica en los grados de:','["Parcial, total, absoluta y gran incapacidad", "Leve, moderada, grave y gran dependencia, según el baremo", "Parcial, total y absoluta, sin más grados", "Temporal, parcial, total, absoluta y gran incapacidad"]'::jsonb,0,'Art. 194.1 TRLGSS','Incapacidad permanente parcial, total, absoluta y gran incapacidad.',null),
('adm-cm:32-705d3abe0d','adm-cm',32,'Para causar derecho a la pensión de jubilación se exige un periodo mínimo de cotización de:','["Diez años, de los cuales al menos dos dentro de los diez inmediatamente anteriores", "Quince años, de los cuales al menos dos dentro de los quince inmediatamente anteriores", "Quince años, de los cuales al menos cinco dentro de los quince inmediatamente anteriores al hecho causante", "Veinte años, de los cuales al menos cinco dentro de los quince inmediatamente anteriores"]'::jsonb,1,'Art. 205.1 b) TRLGSS','Quince años, de los cuales al menos dos deben estar dentro de los quince años inmediatamente anteriores.',null),
('adm-cm:32-fabbc6fc63','adm-cm',32,'La pensión de viudedad de un causante en alta exige, con carácter general, un periodo de cotización de:','["Quinientos días dentro de un periodo ininterrumpido de cinco años inmediatamente anteriores al hecho causante", "Ninguno, si el causante estaba en alta", "Quinientos días dentro de un periodo ininterrumpido de diez años inmediatamente anteriores al hecho causante", "Quince años, de los cuales al menos dos en los últimos quince"]'::jsonb,0,'Art. 219.1 TRLGSS','Si el causante no estaba en alta ni en situación asimilada, se exigen quince años.',null),
('adm-cm:32-49196e93ad','adm-cm',32,'La gestión de las pensiones no contributivas de invalidez y jubilación corresponde a:','["El INGESA", "La TGSS", "El INSS", "El IMSERSO"]'::jsonb,3,'Art. 66.1 c) TRLGSS','El INSS gestiona las prestaciones económicas del sistema, salvo las del IMSERSO.',null),
('adm-cm:32-89011d523a','adm-cm',32,'En la jubilación parcial, la reducción de la jornada debe estar comprendida entre:','["Un mínimo del 10 % y un máximo del 50 %", "Un mínimo del 30 % y un máximo del 60 %", "Un mínimo del 25 % y un máximo del 75 %", "Un mínimo del 50 % y un máximo del 90 %"]'::jsonb,2,'Art. 215.1 TRLGSS','Según el art. 215 en su redacción consolidada.',null),
('adm-cm:32-4ba984bb0d','adm-cm',32,'Con carácter general, la edad ordinaria de jubilación es de 67 años, o de 65 años cuando se acrediten:','["40 años de cotización", "38 años y 6 meses de cotización", "35 años de cotización", "36 años y 6 meses de cotización"]'::jsonb,1,'Art. 205.1 a) TRLGSS','Según el texto consolidado del TRLGSS en el BOE.',null),
('adm-cm:32-ad77f59ea3','adm-cm',32,'La prestación por riesgo durante el embarazo consiste en un subsidio equivalente al:','["50 % de la base reguladora de contingencias comunes", "100 % de la base reguladora de la incapacidad temporal derivada de contingencias profesionales", "75 % de la base reguladora de la incapacidad temporal derivada de contingencias comunes", "60 % de la base"]'::jsonb,1,'Art. 187.3 TRLGSS','Se trata como contingencia profesional.',null),
('adm-cm:32-45f8f383bf','adm-cm',32,'La incapacidad temporal se puede prorrogar, tras los 365 días, por otros:','["30 días", "365 días", "180 días, cuando se presuma que durante ellos el trabajador puede ser dado de alta por curación", "90 días, cuando se presuma que durante ellos el trabajador puede ser dado de alta por curación"]'::jsonb,2,'Art. 169.1 a) TRLGSS','La duración máxima es de 365 días prorrogables por otros 180.',null),
('adm-cm:32-3ff44a9c77','adm-cm',32,'Las prestaciones por muerte y supervivencia incluyen:','["Solo la pensión de viudedad, la pensión de orfandad y, en su caso, la pensión de jubilación que hubiera correspondido al fallecido, que se transmite a sus herederos", "Auxilio por defunción, pensión de viudedad, prestación temporal de viudedad, pensión de orfandad y pensión en favor de familiares", "La pensión de jubilación del fallecido", "Solo el auxilio por defunción"]'::jsonb,1,'Art. 216.1 TRLGSS','Se enumeran en el art. 216.1.',null),
('adm-cm:32-81953098fc','adm-cm',32,'Las prestaciones de la Seguridad Social, con carácter general:','["Pueden compensarse con cualquier deuda del beneficiario con la Administración y retenerse por el empresario hasta su liquidación definitiva", "Pueden cederse libremente a terceros y compensarse con las deudas que el beneficiario tenga con la Seguridad Social", "No pueden ser objeto de retención, cesión total o parcial, compensación o descuento, salvo excepciones", "Pueden retenerse por el empresario"]'::jsonb,2,'Art. 44.1 TRLGSS','Excepciones: obligaciones alimenticias a favor del cónyuge e hijos y obligaciones contraídas con la Seguridad Social.','nov. 2024 · 1.er ejercicio'),
('adm-cm:32-def460297e','adm-cm',32,'La jubilación anticipada voluntaria exige tener una edad que sea, como máximo, dos años inferior a la ordinaria y acreditar un periodo mínimo de cotización efectiva de:','["33 años", "38 años y 6 meses", "15 años", "35 años"]'::jsonb,3,'Art. 208.1 TRLGSS','El importe de la pensión debe superar la mínima que correspondería a los 65 años.',null),
('adm-cm:32-f132c27df2','adm-cm',32,'Los bienes y derechos que integran el patrimonio de la Seguridad Social son:','["Embargables por cualquier acreedor", "Inembargables", "Embargables solo por Hacienda", "Transmisibles libremente"]'::jsonb,1,'Art. 108 TRLGSS','El patrimonio de la Seguridad Social es inembargable.',null),
('adm-cm:32-e069774b52','adm-cm',32,'La incapacidad permanente parcial para la profesión habitual se abona mediante:','["Un subsidio temporal", "Una pensión vitalicia del 100 %", "Una pensión vitalicia del 55 %", "Una cantidad a tanto alzado"]'::jsonb,3,'Art. 196.1 TRLGSS','La total y la absoluta dan lugar a pensión vitalicia.',null),
('adm-cm:32-3a15fba24d','adm-cm',32,'El sistema financiero de todos los regímenes que integran el sistema de la Seguridad Social es el de:','["Reparto, para todas las contingencias y situaciones amparadas", "Mixto obligatorio, con una parte de capitalización", "Capitalización individual para la jubilación y reparto para el resto de contingencias", "Capitalización colectiva"]'::jsonb,0,'Art. 110.1 TRLGSS','El sistema funciona por reparto.',null),
('adm-cm:32-45e771caf9','adm-cm',32,'El derecho al reconocimiento de la pensión de jubilación:','["Es imprescriptible", "Prescribe a los cuatro años", "Prescribe a los cinco años", "Caduca al año"]'::jsonb,0,'Art. 212 TRLGSS','Los efectos en alta se retrotraen hasta tres meses antes de la solicitud.',null),
('adm-cm:32-68962fea3a','adm-cm',32,'Se considera recaída en un mismo proceso de incapacidad temporal cuando se produzca una nueva baja médica por la misma o similar patología dentro de los:','["90 días naturales siguientes a la fecha de efectos del alta médica anterior", "180 días naturales siguientes a la fecha de efectos del alta médica anterior", "365 días siguientes", "30 días siguientes"]'::jsonb,1,'Art. 169.2 TRLGSS','Se computan juntos ambos periodos.',null),
('adm-cm:32-5d133a4442','adm-cm',32,'La obligación de reintegrar el importe de las prestaciones indebidamente percibidas prescribe a los:','["Diez años", "Cuatro años", "Cinco años", "Un año"]'::jsonb,1,'Art. 55.3 TRLGSS','Desde la fecha de su cobro o desde que fue posible ejercitar la acción.',null),
('adm-cm:32-3c757f77b4','adm-cm',32,'La jubilación anticipada por causa no imputable al trabajador permite anticipar la jubilación, como máximo:','["Seis años antes de la edad ordinaria, con 35 años de cotización", "Cuatro años antes de la edad ordinaria, con 33 años de cotización", "Diez años antes", "Dos años antes de la edad ordinaria, con 30 años de cotización"]'::jsonb,1,'Art. 207.1 TRLGSS','Además se exige inscripción como demandante de empleo durante seis meses.',null),
('adm-cm:32-875d5ba430','adm-cm',32,'En la gran incapacidad, el pensionista tiene derecho a una pensión vitalicia incrementada con:','["Un complemento destinado a que pueda remunerar a la persona que le atienda", "Un complemento por mínimos, siempre que carezca de otras rentas", "Una indemnización a tanto alzado por una sola vez, equivalente a veinticuatro mensualidades de la base reguladora", "Una vivienda adaptada a cargo de la entidad gestora y una indemnización a tanto alzado"]'::jsonb,0,'Art. 196.4 TRLGSS','El complemento es el 45 % de la base mínima de cotización más el 30 % de la última base, con un mínimo del 45 % de la pensión.',null),
('adm-cm:32-ed62464e1e','adm-cm',32,'En la incapacidad temporal por accidente de trabajo o enfermedad profesional, el subsidio se abona:','["Desde el decimosexto día de baja, a cargo de la mutua", "Desde el primer día del mes siguiente", "Desde el cuarto día de baja, a cargo del empresario hasta el decimoquinto", "Desde el día siguiente al de la baja en el trabajo"]'::jsonb,3,'Art. 173.1 TRLGSS','El salario del día de la baja corre a cargo del empresario.',null),
('adm-cm:32-0053d4ba23','adm-cm',32,'Se presume, salvo prueba en contrario, que son constitutivas de accidente de trabajo:','["Todas las enfermedades comunes padecidas durante la vigencia del contrato", "Las lesiones sufridas durante las vacaciones anuales retribuidas", "Las lesiones sufridas en el domicilio un domingo", "Las lesiones que sufra el trabajador durante el tiempo y en el lugar del trabajo"]'::jsonb,3,'Art. 156.3 TRLGSS','Presunción iuris tantum de accidente de trabajo.',null),
('adm-cm:32-8eeceb4ccb','adm-cm',32,'La prestación por cuidado de menores afectados por cáncer u otra enfermedad grave exige una reducción de jornada de, al menos:','["Un 50 % de su duración", "Un 25 % de su duración", "Un 10 % de su duración", "Un 33 % de su duración"]'::jsonb,0,'Art. 190.1 TRLGSS','Puede mantenerse hasta los 23 años del hijo (26 con discapacidad ≥ 65 % acreditada antes).',null),
('adm-cm:32-cce521cdec','adm-cm',32,'Las lesiones permanentes no incapacitantes causadas por accidente de trabajo o enfermedad profesional se indemnizan:','["Con un subsidio mensual mientras dure la lesión", "Con una pensión vitalicia del 55 % de la base reguladora, incompatible con la continuación en la empresa y con cualquier otra prestación de la Seguridad Social", "Por una sola vez, con las cantidades alzadas fijadas en el baremo, sin perjuicio del derecho a continuar en la empresa", "No se indemnizan"]'::jsonb,2,'Art. 201 TRLGSS','Son incompatibles con las prestaciones de incapacidad permanente salvo lesiones independientes.',null),
('adm-cm:32-699c1d83e1','adm-cm',32,'Para tener derecho a la incapacidad temporal derivada de enfermedad común se exige un periodo de cotización de:','["180 días dentro de los cinco años inmediatamente anteriores al hecho causante", "Un año dentro de los diez años inmediatamente anteriores al hecho causante", "365 días en el último año", "No se exige cotización previa"]'::jsonb,0,'Art. 172 a) TRLGSS','En accidente (sea o no de trabajo) y enfermedad profesional no se exige periodo previo.',null),
('adm-cm:32-03102b4039','adm-cm',32,'El derecho al subsidio por incapacidad temporal se extingue, entre otras causas, por el transcurso de:','["365 días naturales desde la baja médica", "545 días naturales desde la baja médica", "730 días naturales desde la primera baja médica", "180 días naturales desde la baja médica"]'::jsonb,1,'Art. 174.1 TRLGSS','Es el plazo máximo total del proceso.',null),
('adm-cm:32-6d73c8af26','adm-cm',32,'La prestación por riesgo durante la lactancia natural se extingue cuando el hijo cumple:','["Dieciocho meses", "Doce meses", "Nueve meses", "Seis meses"]'::jsonb,2,'Art. 189 TRLGSS','Salvo que la beneficiaria se haya reincorporado antes a su puesto.',null),
('adm-cm:32-31803110ab','adm-cm',32,'Las pensiones contributivas se revalorizan al comienzo de cada año en función de:','["El valor medio de las tasas de variación interanual del IPC de los doce meses previos a diciembre del año anterior", "El IPREM", "El SMI", "El crecimiento del PIB y la evolución de la masa salarial de los afiliados en los doce meses previos"]'::jsonb,0,'Art. 58.2 TRLGSS','Si el valor es negativo, el importe de las pensiones no varía.',null),
('adm-cm:32-b500b97c9c','adm-cm',32,'La administración y gestión de servicios sanitarios corresponde, como entidad gestora, a:','["Las mutuas colaboradoras con la Seguridad Social", "La TGSS", "El Instituto Nacional de Gestión Sanitaria (INGESA)", "El IMSERSO"]'::jsonb,2,'Art. 66.1 b) TRLGSS','El INGESA es la entidad gestora sanitaria.',null),
('adm-cm:32-235c3fe573','adm-cm',32,'La pensión vitalicia por incapacidad permanente total puede sustituirse excepcionalmente por una indemnización a tanto alzado cuando el beneficiario sea menor de:','["Cuarenta y cinco años", "Cincuenta años", "Sesenta y cinco años", "Sesenta años"]'::jsonb,3,'Art. 196.2 TRLGSS','Es una sustitución excepcional.',null),
('adm-cm:32-e51356371a','adm-cm',32,'Para tener derecho a la prestación por nacimiento y cuidado de menor, a las personas trabajadoras menores de 21 años:','["No se les exige periodo mínimo de cotización", "Se les exigen 90 días cotizados dentro de los siete años inmediatamente anteriores al inicio del descanso", "Se les exige un año cotizado a lo largo de su vida laboral", "Se les exigen 180 días cotizados"]'::jsonb,0,'Art. 178.1 a) TRLGSS','Entre 21 y 26 años no cumplidos se exigen 90 días en los siete años anteriores (o 180 en la vida laboral).',null),
('adm-cm:32-c6744d98f0','adm-cm',32,'La prestación temporal de viudedad tiene una duración de:','["Seis meses", "Cinco años", "Un año", "Dos años"]'::jsonb,3,'Art. 222 TRLGSS','Se concede cuando no se reúnen los requisitos de la pensión de viudedad por el periodo de matrimonio.',null),
('adm-cm:32-a61f2e16e3','adm-cm',32,'El derecho al percibo de las prestaciones a tanto alzado y por una sola vez caduca:','["A los cinco años, a contar desde el día siguiente a su notificación", "Nunca", "A los tres meses, a contar desde el día siguiente a su notificación", "Al año, a contar desde el día siguiente a su notificación"]'::jsonb,3,'Art. 54.1 TRLGSS','En las prestaciones periódicas, cada mensualidad caduca al año de su vencimiento.',null),
('adm-cm:32-05302f7850','adm-cm',32,'El derecho al reconocimiento de las prestaciones de la Seguridad Social prescribe, con carácter general, a los:','["Cuatro años, contados desde el día siguiente al hecho causante", "Cinco años, contados desde el día siguiente al hecho causante", "Diez años", "Un año, contado desde el día siguiente al hecho causante"]'::jsonb,1,'Art. 53.1 TRLGSS','Sin perjuicio de las excepciones legales.',null),
('adm-cm:32-582980e977','adm-cm',32,'En caso de enfermedad común o accidente no laboral, el subsidio de incapacidad temporal se abona:','["Desde el primer día de baja", "Desde el día siguiente a la baja en el trabajo", "A partir del decimosexto día de baja, a cargo de la entidad gestora", "A partir del cuarto día de baja en el trabajo"]'::jsonb,3,'Art. 173.1 TRLGSS','Del cuarto al decimoquinto día el abono corresponde al empresario.',null),
('adm-cm:32-7226172b58','adm-cm',32,'El subsidio por nacimiento y cuidado de menor consiste en un subsidio equivalente al:','["60 % de la base reguladora correspondiente", "75 % de la base reguladora durante las seis primeras semanas", "100 % de la base reguladora correspondiente", "75 % de la base reguladora de contingencias comunes"]'::jsonb,2,'Art. 179.1 TRLGSS','La base reguladora es la de incapacidad temporal por contingencias comunes.',null),
('adm-cm:32-c2b682bb36','adm-cm',32,'Tienen derecho a la pensión de orfandad, con carácter general, los hijos del causante:','["Menores de dieciocho años solamente", "Menores de dieciséis años o incapacitados para el trabajo", "Menores de veintiún años o incapacitados para el trabajo", "De cualquier edad"]'::jsonb,2,'Art. 224.1 TRLGSS','Puede extenderse hasta los 25 años si el huérfano no trabaja o sus ingresos son inferiores a determinados límites.',null),
('adm-cm:33-c65fc0f548','adm-cm',33,'Según la Ley General Tributaria, ¿cómo se clasifican los tributos?','["En tasas, contribuciones especiales e impuestos", "En impuestos directos, indirectos y precios públicos", "En impuestos, cotizaciones sociales y tasas", "En tasas, precios públicos e impuestos"]'::jsonb,0,'Art. 2.2 LGT','Los tributos, cualquiera que sea su denominación, se clasifican en tasas, contribuciones especiales e impuestos.',null),
('adm-cm:33-0567bcd603','adm-cm',33,'¿Qué son los impuestos según la Ley General Tributaria?','["Tributos por el beneficio obtenido con obras públicas", "Prestaciones voluntarias por servicios que también presta el sector privado en régimen de concurrencia", "Tributos por la utilización privativa del dominio público", "Tributos exigidos sin contraprestación cuyo hecho imponible pone de manifiesto la capacidad económica"]'::jsonb,3,'Art. 2.2 c) LGT','Impuestos son los tributos exigidos sin contraprestación cuyo hecho imponible está constituido por negocios, actos o hechos que ponen de manifiesto la capacidad económica.',null),
('adm-cm:33-59a9398fa6','adm-cm',33,'¿Qué tributo tiene como hecho imponible el beneficio o aumento de valor de los bienes por obras o servicios públicos?','["La tasa", "La contribución especial", "El impuesto", "El precio público"]'::jsonb,1,'Art. 2.2 b) LGT','Las contribuciones especiales gravan el beneficio o aumento de valor de los bienes del obligado por obras públicas o servicios públicos.',null),
('adm-cm:33-5334ff2ab8','adm-cm',33,'¿Qué tributo grava la utilización privativa o el aprovechamiento especial del dominio público?','["El recargo", "El impuesto", "La tasa", "La contribución especial"]'::jsonb,2,'Art. 2.2 a) LGT','Las tasas gravan la utilización privativa o el aprovechamiento especial del dominio público y ciertos servicios o actividades en régimen de derecho público.',null),
('adm-cm:33-6983c4ecc2','adm-cm',33,'¿En qué principios se basa la ordenación del sistema tributario según la Ley General Tributaria?','["Capacidad económica, justicia, generalidad, igualdad, progresividad, equitativa distribución y no confiscatoriedad", "Eficacia, eficiencia, economía, limitación de costes indirectos y respeto de los derechos y garantías de los obligados", "Legalidad, seguridad jurídica, jerarquía e irretroactividad", "Proporcionalidad, simplicidad, neutralidad y suficiencia"]'::jsonb,0,'Art. 3.1 LGT','La ordenación se basa en la capacidad económica y en los principios de justicia, generalidad, igualdad, progresividad, equitativa distribución de la carga y no confiscatoriedad.',null),
('adm-cm:33-d2fce9db7f','adm-cm',33,'¿A quién corresponde la potestad originaria para establecer tributos?','["A las Cortes y a los parlamentos autonómicos indistintamente", "Exclusivamente al Estado, mediante ley", "Al Gobierno, mediante real decreto", "Al Estado y a las comunidades autónomas por igual"]'::jsonb,1,'Art. 4.1 LGT','La potestad originaria para establecer tributos corresponde exclusivamente al Estado, mediante ley.',null),
('adm-cm:33-8685f95ab8','adm-cm',33,'¿Qué carácter tienen en el ordenamiento tributario las disposiciones generales del derecho administrativo?','["Interpretativo únicamente", "Ninguno, no se aplican a los tributos", "Preferente sobre la Ley General Tributaria", "Supletorio"]'::jsonb,3,'Art. 7.2 LGT','Tienen carácter supletorio las disposiciones generales del derecho administrativo y los preceptos del derecho común.',null),
('adm-cm:33-3c6e98814a','adm-cm',33,'¿Cuál de estas materias está reservada a la ley según el art. 8 de la Ley General Tributaria?','["La organización de la Agencia Tributaria", "El calendario del contribuyente", "La aprobación de los modelos de autoliquidación", "El establecimiento y modificación de los plazos de prescripción y caducidad"]'::jsonb,3,'Art. 8 LGT','Se regulan por ley, entre otros, los plazos de prescripción y caducidad, el hecho imponible, el tipo, las exenciones y las infracciones y sanciones.',null),
('adm-cm:33-4b99ae1827','adm-cm',33,'Si no disponen otra cosa, ¿cuándo entran en vigor las normas tributarias?','["Al día siguiente de su publicación", "A los veinte días naturales de su completa publicación", "El 1 de enero del año siguiente", "A los veinte días hábiles de su publicación"]'::jsonb,1,'Art. 10.1 LGT','Entran en vigor a los veinte días naturales de su completa publicación en el boletín oficial, si en ellas no se dispone otra cosa.',null),
('adm-cm:33-ae11874531','adm-cm',33,'¿Qué normas tributarias tienen efecto retroactivo respecto de actos no firmes cuando son más favorables?','["Las que regulan infracciones, sanciones y recargos", "Las que regulan el hecho imponible y el tipo", "Todas las normas tributarias", "Las que regulan los plazos de prescripción"]'::jsonb,0,'Art. 10.2 LGT','Las normas sobre infracciones, sanciones y recargos tienen efecto retroactivo respecto de actos no firmes cuando resulten más favorables.',null),
('adm-cm:33-7abd7e6a3a','adm-cm',33,'¿Pueden los particulares alterar mediante convenios los elementos de la obligación tributaria?','["Sí, si los aprueba la Administración", "Solo en los tributos locales", "No producen efectos ante la Administración, sin perjuicio de sus consecuencias privadas", "Sí, si se formalizan en escritura pública y se comunican después a la Administración tributaria"]'::jsonb,2,'Art. 17.5 LGT','Los elementos de la obligación tributaria no pueden ser alterados por actos o convenios de los particulares, que no producirán efectos ante la Administración.',null),
('adm-cm:33-e8249480e1','adm-cm',33,'¿Cuál es el objeto de la obligación tributaria principal?','["La llevanza de libros registro", "El pago de la cuota tributaria", "La presentación de la declaración", "El pago de los intereses de demora"]'::jsonb,1,'Art. 19 LGT','La obligación tributaria principal tiene por objeto el pago de la cuota tributaria.',null),
('adm-cm:33-2bd94ca7d6','adm-cm',33,'¿Qué es el hecho imponible según la Ley General Tributaria?','["El acto de la Administración que liquida el tributo", "La cantidad sobre la que se aplica el tipo de gravamen para calcular la cuota íntegra del tributo", "El presupuesto fijado por la ley cuya realización origina la obligación tributaria principal", "El momento en que se exige el pago del tributo"]'::jsonb,2,'Art. 20.1 LGT','Es el presupuesto fijado por la ley para configurar cada tributo cuya realización origina el nacimiento de la obligación tributaria principal.',null),
('adm-cm:33-401610aaff','adm-cm',33,'¿Qué es el devengo?','["La fecha de notificación de la liquidación", "El momento en que la deuda no pagada en periodo voluntario pasa a periodo ejecutivo con recargo", "El plazo de pago en periodo voluntario", "El momento en que se entiende realizado el hecho imponible y nace la obligación tributaria principal"]'::jsonb,3,'Art. 21.1 LGT','El devengo es el momento en que se entiende realizado el hecho imponible y se produce el nacimiento de la obligación tributaria principal.',null),
('adm-cm:33-eca8a553d0','adm-cm',33,'¿Requiere la exigencia del interés de demora tributario la previa intimación de la Administración?','["No, ni la intimación ni un retraso culpable", "Sí, siempre debe intimarse antes", "Sí, salvo que el retraso sea culpable", "Solo si el retraso supera seis meses"]'::jsonb,0,'Art. 26.1 LGT','La exigencia del interés de demora no requiere la previa intimación de la Administración ni la concurrencia de un retraso culpable.',null),
('adm-cm:33-84568db17a','adm-cm',33,'Salvo que la Ley de Presupuestos disponga otro, ¿cuál es el interés de demora tributario?','["El interés legal incrementado en un 50 %", "El interés legal del dinero sin incremento", "El interés legal del dinero incrementado en un 25 %", "El tipo de interés del Banco Central Europeo"]'::jsonb,2,'Art. 26.6 LGT','Es el interés legal del dinero vigente incrementado en un 25 %, salvo que la Ley de Presupuestos establezca otro.',null),
('adm-cm:33-12b400fb47','adm-cm',33,'¿Qué recargo se aplica a una autoliquidación presentada sin requerimiento previo con tres meses completos de retraso?','["El 5 %", "El 10 %", "El 3 %", "El 4 %"]'::jsonb,3,'Art. 27.2 LGT','El recargo es del 1 % más otro 1 % por cada mes completo de retraso: con tres meses completos, el 4 %.',null),
('adm-cm:33-e9b5a96e48','adm-cm',33,'¿Qué recargo se aplica si la autoliquidación se presenta transcurridos doce meses desde el fin del plazo, sin requerimiento previo?','["El 15 %, excluyendo las sanciones", "El 20 %, con sanciones", "El 13 %, sin intereses", "El 25 %, con intereses de demora"]'::jsonb,0,'Art. 27.2 LGT','Transcurridos 12 meses el recargo es del 15 % y excluye las sanciones, con intereses desde el día siguiente a esos 12 meses.',null),
('adm-cm:33-ef5c57b96f','adm-cm',33,'¿En qué porcentaje se reduce el recargo por declaración extemporánea si se paga en plazo?','["En el 10 %", "En el 25 %", "En el 50 %", "En el 30 %"]'::jsonb,1,'Art. 27.5 LGT','El importe del recargo se reduce en el 25 % si se realiza el ingreso total en los plazos previstos.',null),
('adm-cm:33-fb322cdcb7','adm-cm',33,'¿Quién es contribuyente según la Ley General Tributaria?','["El sujeto pasivo que realiza el hecho imponible", "Quien soporta la repercusión del tributo", "Quien, por ley, cumple la obligación en lugar del que realiza el hecho imponible", "Quien responde de la deuda de otro"]'::jsonb,0,'Art. 36.2 LGT','Es contribuyente el sujeto pasivo que realiza el hecho imponible; el sustituto cumple en su lugar por imposición de la ley.',null),
('adm-cm:33-5e638d513f','adm-cm',33,'Cuando concurren varios obligados tributarios en un mismo presupuesto, ¿cómo quedan obligados?','["Subsidiariamente, por orden de participación", "Responde solo el primero que figure en la declaración", "Mancomunadamente, por partes iguales", "Solidariamente, salvo que la ley disponga otra cosa"]'::jsonb,3,'Art. 35.7 LGT','La concurrencia determina que queden solidariamente obligados, salvo que por ley se disponga expresamente otra cosa.',null),
('adm-cm:33-e5cc8e5d72','adm-cm',33,'¿Forman parte de la deuda tributaria las sanciones tributarias?','["Sí, como prestación accesoria", "No, aunque en su recaudación se aplican las normas de la deuda", "Solo las sanciones por infracciones graves", "Sí, junto con el interés de demora"]'::jsonb,1,'Art. 58.3 LGT','Las sanciones tributarias no forman parte de la deuda tributaria, pero en su recaudación se aplican las normas del capítulo V del título III.',null),
('adm-cm:33-2f46d75c0c','adm-cm',33,'¿Cuál de estos conceptos forma parte de la deuda tributaria además de la cuota?','["Las costas judiciales", "Las sanciones tributarias", "Los recargos del periodo ejecutivo", "Las multas de tráfico"]'::jsonb,2,'Art. 58.2 LGT','La deuda tributaria incluye, en su caso, el interés de demora, los recargos por declaración extemporánea, los del periodo ejecutivo y otros recargos legales.',null),
('adm-cm:33-870f881e80','adm-cm',33,'¿En qué plazo prescribe el derecho de la Administración a determinar la deuda tributaria mediante liquidación?','["Cuatro años", "Cinco años", "Seis años", "Tres años"]'::jsonb,0,'Art. 66 LGT','Prescriben a los cuatro años el derecho a liquidar, a exigir el pago, a solicitar devoluciones y a obtenerlas.',null),
('adm-cm:33-ca2f16c3a0','adm-cm',33,'¿Desde cuándo se computa la prescripción del derecho a liquidar?','["Desde la fecha en que el obligado tributario presentó efectivamente la declaración o la autoliquidación", "Desde el día siguiente al fin del plazo reglamentario para presentar la declaración o autoliquidación", "Desde el día del devengo en todos los casos", "Desde el 1 de enero del año siguiente al devengo"]'::jsonb,1,'Art. 67.1 LGT','Se computa desde el día siguiente a aquel en que finalice el plazo reglamentario para presentar la declaración o autoliquidación; en tributos periódicos por recibo, desde el devengo.',null),
('adm-cm:33-dff36243c4','adm-cm',33,'Producida la interrupción de la prescripción tributaria, ¿qué ocurre con el plazo?','["Se reanuda por el tiempo que quedaba", "Se amplía en seis meses", "Queda suspendido hasta que resuelva el tribunal", "Se inicia de nuevo el cómputo"]'::jsonb,3,'Art. 68.6 LGT','Producida la interrupción, se iniciará de nuevo el cómputo del plazo de prescripción, salvo las excepciones del apartado 7.',null),
('adm-cm:34-091b4742d8','adm-cm',34,'Según la Ley 5/2025, el sector público autonómico está formado por:','["La Administración de la Comunidad de Madrid y el sector público institucional", "La Administración de la Comunidad de Madrid, el sector público institucional y las entidades locales de su territorio", "La Administración de la Comunidad de Madrid, sin incluir el sector público institucional", "La Asamblea, el Gobierno y la Administración"]'::jsonb,0,'Art. 2.1 Ley 5/2025 CM','Lo forman la Administración de la Comunidad de Madrid y el sector público institucional.',null),
('adm-cm:34-ab39b84fe0','adm-cm',34,'A efectos de la Ley de Hacienda, la Cámara de Cuentas:','["Queda totalmente fuera de su ámbito de aplicación", "Forma parte del sector público autonómico, con las peculiaridades de su independencia funcional", "Forma parte del sector público institucional como organismo autónomo, sometido a la tutela de la Consejería competente en hacienda", "Es una entidad de Derecho público dependiente del Gobierno"]'::jsonb,1,'Art. 2.3 Ley 5/2025 CM','Forma parte del sector público autonómico a efectos de la ley, con las peculiaridades derivadas de su independencia funcional.',null),
('adm-cm:34-b06c8bcfe6','adm-cm',34,'Según la Ley 5/2025, los organismos autónomos se clasifican en:','["Estatales y autonómicos", "Públicos y privados", "Generales y de régimen especial", "Administrativos y mercantiles"]'::jsonb,3,'Art. 4.2 Ley 5/2025 CM','Los organismos autónomos son administrativos o mercantiles.',null),
('adm-cm:34-e4b0151018','adm-cm',34,'Las sociedades mercantiles de la Comunidad de Madrid, ¿pueden ejercer facultades que impliquen autoridad pública?','["No, salvo que una ley lo prevea excepcionalmente", "Sí, siempre", "Sí, si lo autoriza su consejo de administración", "Solo en materia tributaria"]'::jsonb,0,'Art. 7.2 Ley 5/2025 CM','No pueden ejercer facultades que impliquen autoridad pública, salvo excepción legal.',null),
('adm-cm:34-49ba8dd353','adm-cm',34,'La Hacienda Pública de la Comunidad de Madrid está formada por:','["Los bienes inmuebles y derechos reales de la Comunidad", "Los derechos y obligaciones económicos de la Administración, sus organismos autónomos y sus entes de Derecho público de régimen especial", "Los derechos y obligaciones económicos de la Administración, sus organismos autónomos, sus sociedades mercantiles, sus fundaciones y las universidades públicas", "Los tributos propios y cedidos, sin incluir las obligaciones"]'::jsonb,1,'Art. 11 Ley 5/2025 CM','La integran los derechos y obligaciones de contenido económico de la Administración, sus organismos autónomos y sus entes de Derecho público de régimen especial.',null),
('adm-cm:34-f5b28546a8','adm-cm',34,'¿Cuál de los siguientes NO figura entre los principios de la actividad económico-financiera del art. 13?','["Legalidad", "Solidaridad intrarregional", "Coordinación", "Rentabilidad"]'::jsonb,3,'Art. 13 Ley 5/2025 CM','Los principios son legalidad, eficacia, control, universalidad, solidaridad intrarregional y coordinación.',null),
('adm-cm:34-9e75f31dab','adm-cm',34,'La concesión de créditos extraordinarios y suplementos de crédito se regula:','["Por orden del Consejero de Hacienda", "Por ley de la Asamblea", "Por decreto del Presidente", "Por resolución de la Intervención General"]'::jsonb,1,'Art. 14 b) Ley 5/2025 CM','Está reservada a ley de la Asamblea, igual que los presupuestos generales.',null),
('adm-cm:34-3617ce831d','adm-cm',34,'¿Qué principio implica que la Tesorería Central integra y custodia los recursos financieros de la Administración y sus organismos autónomos?','["Principio de caja única", "Principio de especialidad", "Principio de anualidad", "Principio de no afectación"]'::jsonb,0,'Art. 19 Ley 5/2025 CM','Es el principio de caja única.',null),
('adm-cm:34-8f952b40d6','adm-cm',34,'El principio de no afectación significa que los recursos de la Hacienda Pública:','["Se destinan preferentemente a gastos de personal y, después, al resto de obligaciones", "Se destinan a satisfacer el conjunto de sus obligaciones, salvo que una ley los afecte a fines concretos", "Se destinan a satisfacer el conjunto de sus obligaciones, sin que ninguna norma, ni siquiera con rango de ley, pueda afectarlos a fines concretos", "Deben destinarse a inversiones"]'::jsonb,1,'Art. 28 Ley 5/2025 CM','Se destinan al conjunto de las obligaciones, salvo que una ley establezca su afectación a fines determinados.',null),
('adm-cm:34-ba566ca5b2','adm-cm',34,'¿Cómo se puede transigir judicial o extrajudicialmente sobre los derechos de la Hacienda Pública de la Comunidad?','["Por orden del Consejero competente en hacienda", "Por resolución del Director General de Patrimonio, previo informe de los Servicios Jurídicos", "Mediante decreto acordado en Consejo de Gobierno", "Mediante ley de la Asamblea"]'::jsonb,2,'Art. 31.3 Ley 5/2025 CM','Solo mediante decreto acordado en Consejo de Gobierno.',null),
('adm-cm:34-fa5c9a900e','adm-cm',34,'Salvo que la Ley de Presupuestos Generales del Estado establezca otro, el interés de demora es:','["El interés legal del dinero", "El interés legal del dinero incrementado en un 10 %", "El doble del interés legal", "El interés legal del dinero incrementado en un 25 %"]'::jsonb,3,'Art. 36.2 Ley 5/2025 CM','Es el interés legal del dinero incrementado en un 25 por ciento, salvo que la LPGE fije otro.',null),
('adm-cm:34-395c4ee476','adm-cm',34,'¿En qué plazo prescriben los derechos de naturaleza pública de la Hacienda de la Comunidad de Madrid?','["Cuatro años", "Cinco años", "Tres años", "Diez años"]'::jsonb,0,'Art. 39.1 Ley 5/2025 CM','Prescriben a los cuatro años, tanto para reconocer o liquidar como para cobrar.',null),
('adm-cm:34-a16f5aeead','adm-cm',34,'La prescripción de los derechos de naturaleza pública de la Hacienda:','["Solo se aplica si la alega el deudor", "Se aplica de oficio", "Requiere sentencia judicial", "No existe"]'::jsonb,1,'Art. 39.2 Ley 5/2025 CM','Se aplica de oficio.',null),
('adm-cm:34-9bedf3d603','adm-cm',34,'Salvo leyes especiales, las obligaciones de la Hacienda Pública de la Comunidad prescriben a los:','["Cinco años", "Dos años", "Cuatro años", "Quince años"]'::jsonb,2,'Art. 47.1 Ley 5/2025 CM','Prescriben a los cuatro años, salvo lo que dispongan leyes especiales.',null),
('adm-cm:34-32fd1244dc','adm-cm',34,'¿Quién elabora el anteproyecto de ley de presupuestos y quién aprueba el proyecto y lo remite a la Asamblea?','["Lo elabora la Consejería competente en hacienda y lo aprueba la Asamblea", "Lo elabora el Consejo de Gobierno y lo aprueba y remite a la Asamblea el Presidente de la Comunidad", "Lo elabora cada Consejería por separado y lo aprueba la Intervención General antes de remitirlo a la Asamblea", "Lo elabora la Consejería competente en hacienda y lo aprueba y remite el Consejo de Gobierno"]'::jsonb,3,'Arts. 15 b) y 16.2 b) Ley 5/2025 CM','La Consejería de hacienda elabora el anteproyecto y el Consejo de Gobierno aprueba el proyecto y lo remite a la Asamblea.',null),
('adm-cm:34-4ab3aa3788','adm-cm',34,'El ejercicio presupuestario de la Comunidad de Madrid:','["Coincide con el año natural", "Va de julio a junio", "Va de septiembre a agosto", "Lo fija cada año el Consejo de Gobierno"]'::jsonb,0,'Art. 57.1 Ley 5/2025 CM','El ejercicio presupuestario coincide con el año natural.',null),
('adm-cm:34-f80ce44f9e','adm-cm',34,'¿Antes de qué fecha debe remitirse a la Asamblea el proyecto de ley de presupuestos?','["Antes del 1 de octubre de cada año", "Antes del 1 de noviembre de cada año", "Antes del 15 de diciembre de cada año", "Antes del 1 de septiembre de cada año"]'::jsonb,1,'Art. 71 Ley 5/2025 CM','El proyecto y su documentación se remiten antes del 1 de noviembre de cada año.',null),
('adm-cm:34-410d1c6385','adm-cm',34,'Si la ley de presupuestos no se ha aprobado antes del primer día del ejercicio:','["No se puede realizar ningún gasto hasta su aprobación, salvo los de personal, que se abonan con cargo a anticipos de tesorería", "El Consejo de Gobierno aprueba unos presupuestos provisionales por decreto hasta la publicación de los nuevos", "Se prorrogan automáticamente los presupuestos del ejercicio anterior hasta la publicación de los nuevos", "Se prorrogan los del ejercicio anterior durante un máximo de seis meses"]'::jsonb,2,'Art. 72.1 Ley 5/2025 CM','Se prorrogan automáticamente los del ejercicio anterior hasta la publicación de los nuevos en el BOCM.','abr. 2026 · 1.er ejercicio'),
('adm-cm:34-bb2979b0c6','adm-cm',34,'Entre los principios presupuestarios del art. 50.1 se encuentra:','["La rentabilidad máxima", "La confidencialidad", "La estabilidad presupuestaria", "La provisionalidad del gasto público"]'::jsonb,2,'Art. 50.1 Ley 5/2025 CM','Estabilidad presupuestaria, sostenibilidad financiera, plurianualidad, transparencia, eficiencia, responsabilidad y lealtad institucional.',null),
('adm-cm:34-57395b4275','adm-cm',34,'Según la Ley 5/2025, no son embargables los bienes de la Hacienda Pública de la Comunidad:','["Que estén situados en el extranjero", "Que tengan menos de diez años", "Materialmente afectados a un servicio público o a una función pública, entre otros supuestos", "De ningún tipo, salvo los bienes muebles y los derechos de crédito, que son embargables por mandato judicial en todo caso"]'::jsonb,2,'Art. 44 Ley 5/2025 CM','Privilegio de inembargabilidad.',null),
('adm-cm:34-accf724948','adm-cm',34,'El fondo de contingencia de la Comunidad de Madrid no será inferior al:','["2 % del presupuesto consolidado, incluidos gastos financieros", "5 % del presupuesto no financiero", "0,1 % del presupuesto no financiero", "0,5 % del presupuesto no financiero"]'::jsonb,3,'Art. 53.2 Ley 5/2025 CM','Atiende necesidades imprevistas.',null),
('adm-cm:34-817b6c2e58','adm-cm',34,'Ante un riesgo de incumplimiento de los objetivos de estabilidad, el Consejo de Gobierno puede:','["Declarar la no disponibilidad de créditos", "Disolver la Asamblea", "Subir los impuestos propios por decreto", "Suspender los pagos de nóminas"]'::jsonb,0,'Art. 51.3 Ley 5/2025 CM','Es una medida preventiva.',null),
('adm-cm:34-3086c7ea26','adm-cm',34,'Si la Hacienda de la Comunidad no paga una obligación en los ___ siguientes a la notificación de la resolución que la reconoce, deberá abonar intereses:','["Un año", "Seis meses", "Diez días", "Tres meses"]'::jsonb,3,'Art. 46.1 Ley 5/2025 CM','Desde que el acreedor reclame por escrito el cumplimiento.',null),
('adm-cm:34-14cd9712a3','adm-cm',34,'Según su art. 1, la Ley 5/2025 de Hacienda de la Comunidad de Madrid tiene por objeto:','["El régimen jurídico de los funcionarios de la Comunidad, su sistema retributivo y la gestión de las nóminas de todo el personal del sector público autonómico", "La organización y funcionamiento de la Asamblea de Madrid", "La regulación del régimen presupuestario, económico-financiero, de contabilidad, intervención y control financiero del sector público autonómico", "La regulación de los tributos propios, cedidos y locales del territorio de la Comunidad de Madrid, así como el régimen de los funcionarios encargados de su gestión, inspección y recaudación"]'::jsonb,2,'Art. 1 Ley 5/2025 CM','Es el objeto de la ley.',null),
('adm-cm:34-7370e956c6','adm-cm',34,'Según la Ley 5/2025, el presupuesto de la Asamblea de Madrid:','["No forma parte de los presupuestos generales", "Lo aprueba el Ministerio de Hacienda a propuesta de la Mesa de la Asamblea", "Lo aprueba el Consejo de Gobierno a propuesta de la Mesa de la Asamblea", "Se integra en los presupuestos generales de la Comunidad de Madrid"]'::jsonb,3,'Art. 3 Ley 5/2025 CM','Conforme al art. 61 del Estatuto.',null),
('adm-cm:34-fb83bf4ebd','adm-cm',34,'Según la Ley 5/2025, las universidades públicas madrileñas están obligadas a:','["Rendir cuentas solo ante el Ministerio de Universidades", "Rendir sus cuentas ante la Cámara de Cuentas de la Comunidad de Madrid", "Rendir cuentas ante el Tribunal de Cuentas, pero no ante la Cámara de Cuentas de la Comunidad", "Integrar su presupuesto en los presupuestos generales"]'::jsonb,1,'Art. 10 Ley 5/2025 CM','Sus presupuestos no se integran en los generales (art. 56.3).',null),
('adm-cm:34-0dbd8889ee','adm-cm',34,'Los escenarios presupuestarios plurianuales abarcan:','["Los dos ejercicios siguientes", "Los cuatro ejercicios siguientes", "Los diez ejercicios siguientes", "Solo el ejercicio corriente"]'::jsonb,1,'Art. 65.4 Ley 5/2025 CM','Según el art. 65.4.',null),
('adm-cm:34-c8590c52fc','adm-cm',34,'Según la Ley 5/2025, la superior autoridad sobre la ordenación de los pagos y su efectiva realización corresponde a:','["La Consejería competente en materia de Hacienda", "Cada Consejería respecto de sus propios créditos", "El Consejo de Gobierno, a propuesta de la Intervención General", "La Asamblea de Madrid"]'::jsonb,0,'Art. 16 f) Ley 5/2025 CM','El pago se ejerce bajo la autoridad del titular de Hacienda o del tesorero central (art. 99.3).',null),
('adm-cm:34-da3f3f8848','adm-cm',34,'Las obligaciones de pago de la Hacienda de la Comunidad son exigibles cuando resulten:','["De una noticia publicada en prensa", "De una reclamación escrita del acreedor dirigida a la Consejería competente, aunque no derive de los presupuestos ni de sentencia judicial", "De la voluntad del funcionario", "De la ejecución de los presupuestos, de sentencia judicial firme o de operaciones de tesorería legalmente autorizadas"]'::jsonb,3,'Art. 42.1 Ley 5/2025 CM','Son los títulos de exigibilidad.',null),
('adm-cm:34-97b446c3a0','adm-cm',34,'Según la Ley 5/2025, quienes tengan deudas en periodo ejecutivo con la Comunidad de Madrid:','["Solo pueden recibir subvenciones", "No pueden contratar ni recibir subvenciones, salvo que estén aplazadas, fraccionadas o suspendidas", "Pueden contratar y recibir subvenciones, pero las cantidades se compensan con la deuda", "Quedan inhabilitados de por vida"]'::jsonb,1,'Art. 33.5 Ley 5/2025 CM','Así lo establece la ley.',null),
('adm-cm:34-a05d16ab59','adm-cm',34,'La clasificación económica agrupa los créditos por:','["Programas", "Consejerías", "Capítulos", "Municipios"]'::jsonb,2,'Art. 62.1 Ley 5/2025 CM','La clasificación funcional agrupa los gastos por programas (art. 61).',null),
('adm-cm:34-d6e0922c67','adm-cm',34,'Los empleados públicos de la Comunidad de Madrid, según la Ley 5/2025:','["Pueden percibir un porcentaje de lo recaudado cuando así lo prevea la relación de puestos de trabajo", "No pueden percibir participación alguna en los tributos u otros ingresos de la Hacienda, salvo sus retribuciones", "Pueden quedarse con las multas", "Cobran comisiones por cada expediente"]'::jsonb,1,'Art. 29.3 Ley 5/2025 CM','Así lo prohíbe la ley.',null),
('adm-cm:34-66879a0aa1','adm-cm',34,'Según la Ley 5/2025, el estado de gastos de los presupuestos se estructura de acuerdo con las clasificaciones:','["Territorial y sectorial", "Orgánica, funcional y económica", "Por fondos europeos exclusivamente", "Alfabética"]'::jsonb,1,'Art. 59 Ley 5/2025 CM','La funcional agrupa por programas y la económica por capítulos.',null),
('adm-cm:34-ea3edb80dd','adm-cm',34,'En los encargos a medios propios personificados, los anticipos no podrán superar:','["El 10 % del importe del encargo", "El 25 % del importe del encargo", "El 50 %", "El 100 %"]'::jsonb,0,'Art. 42.3 Ley 5/2025 CM','En convenios con entes del sector público autonómico pueden llegar al 100 %.',null),
('adm-cm:35-d8542191e6','adm-cm',35,'Los créditos para gastos tienen carácter:','["Orientativo", "Estimativo", "Ampliable en todo caso", "Limitativo y vinculante"]'::jsonb,3,'Art. 73 Ley 5/2025 CM','Se destinan exclusivamente a la finalidad para la que fueron autorizados y tienen carácter limitativo y vinculante.',null),
('adm-cm:35-dfc0a9d19e','adm-cm',35,'¿A cuántos ejercicios futuros pueden extenderse, con carácter general, los compromisos de gasto plurianual?','["Cuatro ejercicios", "Dos ejercicios siguientes", "Seis ejercicios", "Tres ejercicios siguientes"]'::jsonb,0,'Art. 74.2 Ley 5/2025 CM','Hasta cuatro ejercicios. Límites sobre el crédito inicial: 70 % el primero, 60 % el segundo y 50 % el tercero y el cuarto.',null),
('adm-cm:35-b1cda494e4','adm-cm',35,'En los gastos plurianuales, el límite para el primer ejercicio siguiente, sobre el crédito inicial, es del:','["50 %", "70 %", "60 %", "100 %"]'::jsonb,1,'Art. 74.2 Ley 5/2025 CM','70 % el primer ejercicio siguiente, 60 % el segundo y 50 % el tercero y el cuarto (100 % en gastos corrientes en bienes y servicios).',null),
('adm-cm:35-b7c6eb606a','adm-cm',35,'La concesión de un crédito extraordinario en la Administración de la Comunidad se tramita:','["Por orden del Consejero competente en hacienda", "Por decreto del Consejo de Gobierno, dando cuenta posteriormente a la Comisión de Presupuestos de la Asamblea", "Mediante un proyecto de ley que el Consejo de Gobierno remite a la Asamblea", "Por acuerdo de la Mesa de la Asamblea"]'::jsonb,2,'Art. 83.1 Ley 5/2025 CM','El titular de Hacienda lo eleva al Consejo de Gobierno, que remite a la Asamblea un proyecto de ley.',null),
('adm-cm:35-8eb9ecef96','adm-cm',35,'¿Cuál es una limitación de las transferencias de crédito?','["Solo pueden acordarse en el último trimestre del ejercicio", "Requieren siempre una ley de la Asamblea", "Solo pueden afectar a créditos de gastos de personal del mismo programa", "No pueden minorar créditos que ya hayan sido incrementados con transferencias"]'::jsonb,3,'Art. 86.2 Ley 5/2025 CM','No afectan a créditos ampliables ni extraordinarios concedidos en el ejercicio, no minoran créditos ya incrementados y no incrementan créditos ya minorados.',null),
('adm-cm:35-9823f16630','adm-cm',35,'Las generaciones de crédito incrementan los créditos como consecuencia de:','["Ingresos no previstos o superiores a los estimados", "La reducción de otros créditos del mismo programa o de otro programa distinto del presupuesto", "La aprobación de un crédito extraordinario", "Préstamos de otras Administraciones"]'::jsonb,0,'Art. 88.1 Ley 5/2025 CM','Se producen por ingresos no previstos o superiores a los estimados.',null),
('adm-cm:35-850f8e4c6d','adm-cm',35,'Según el principio de especialidad cualitativa, los créditos para gastos:','["Solo pueden gastarse en gastos de personal", "Se destinan a lo que decida cada gestor dentro de su sección presupuestaria, sin vinculación a una finalidad concreta", "Se destinarán exclusivamente a la finalidad específica para la que hayan sido autorizados", "Se destinarán a la finalidad para la que hayan sido autorizados o a cualquier otra del mismo capítulo"]'::jsonb,2,'Art. 73.1 Ley 5/2025 CM','La especialidad cuantitativa impide comprometer gasto por encima del crédito (art. 73.3).',null),
('adm-cm:35-d55d21fec1','adm-cm',35,'Los créditos para gastos que el último día del ejercicio no estén afectados al cumplimiento de obligaciones reconocidas:','["Pasan al fondo de contingencia", "Se transfieren a la Asamblea", "Se incorporan automáticamente al ejercicio siguiente", "Quedarán anulados de pleno derecho"]'::jsonb,3,'Art. 81 Ley 5/2025 CM','Es una manifestación del principio de anualidad.',null),
('adm-cm:35-3565732971','adm-cm',35,'Según la Ley 5/2025, son créditos ampliables:','["Los que se relacionen de forma taxativa en la ley de presupuestos", "Los de inversiones reales en todo caso", "Cualquier crédito, a petición motivada del centro gestor y con autorización del Consejero de Hacienda", "Todos los créditos de personal"]'::jsonb,0,'Art. 85.2 Ley 5/2025 CM','La relación es taxativa.',null),
('adm-cm:35-09e8900d6e','adm-cm',35,'Las incorporaciones de crédito requieren:','["Un informe favorable del Tribunal de Cuentas", "La existencia de remanente de tesorería positivo", "Que el crédito sea de personal", "Autorización previa de la Asamblea en todo caso, mediante ley"]'::jsonb,1,'Art. 90.1 Ley 5/2025 CM','Según el art. 90.1.',null),
('adm-cm:35-d1a9f8b563','adm-cm',35,'En los gastos plurianuales corrientes en bienes y servicios, el porcentaje máximo aplicable a cada ejercicio futuro es:','["El 100 %", "El 50 %", "El 60 %", "El 70 %"]'::jsonb,0,'Art. 74.2 Ley 5/2025 CM','Para el resto, los límites son el 70 %, 60 % y 50 %.',null),
('adm-cm:35-a938279fc7','adm-cm',35,'Según la Ley 5/2025 de Hacienda de la Comunidad de Madrid, ¿a cuántos ejercicios futuros pueden aplicarse, como regla general, los gastos plurianuales?','["Cinco", "Tres", "Cuatro", "Seis"]'::jsonb,2,'Art. 74 Ley 5/2025 CM','El número de ejercicios futuros a que pueden aplicarse los gastos plurianuales no será superior a cuatro.',null),
('adm-cm:35-6da6b28a17','adm-cm',35,'En los gastos plurianuales, ¿qué porcentaje del crédito inicial puede imputarse, como máximo, al ejercicio inmediato siguiente?','["El 50 %", "El 70 %", "El 100 %", "El 60 %"]'::jsonb,1,'Art. 74 Ley 5/2025 CM','Los límites son el 70 % en el ejercicio inmediato siguiente, el 60 % en el segundo y el 50 % en el tercero y el cuarto.',null),
('adm-cm:35-7ba9451762','adm-cm',35,'En los gastos plurianuales, ¿qué porcentaje se aplica en los ejercicios tercero y cuarto?','["El 50 %", "El 40 %", "El 60 %", "El 70 %"]'::jsonb,0,'Art. 74 Ley 5/2025 CM','En los ejercicios tercero y cuarto el límite es el 50 % del crédito inicial.',null),
('adm-cm:35-340a98afc0','adm-cm',35,'En los gastos corrientes en bienes y servicios de carácter plurianual, ¿qué porcentaje puede imputarse a cada ejercicio posterior?','["El 70 %", "El 80 %", "El 50 %", "El 100 %"]'::jsonb,3,'Art. 74 Ley 5/2025 CM','En los gastos corrientes en bienes y servicios el porcentaje aplicable a cada ejercicio posterior es el 100 %.',null),
('adm-cm:35-3c12b94442','adm-cm',35,'En los contratos de obra plurianuales, salvo abono total del precio, ¿qué retención adicional de crédito se practica al adjudicar?','["El 3 % del valor estimado", "El 5 % del importe de adjudicación", "El 10 % del importe de adjudicación", "El 20 % del presupuesto de licitación"]'::jsonb,2,'Art. 74 Ley 5/2025 CM','Se efectúa una retención adicional de crédito del 10 % del importe de adjudicación en el momento de la adjudicación.',null),
('adm-cm:35-2d2ce7f24a','adm-cm',35,'¿A cuál de estos compromisos NO se aplican los límites de anualidades y porcentajes de los gastos plurianuales?','["A las subvenciones en concurrencia competitiva", "A los arrendamientos de inmuebles", "A los contratos de obras ordinarios", "A los contratos de suministro"]'::jsonb,1,'Art. 74 Ley 5/2025 CM','No se aplican a la carga financiera de la deuda, la contratación de personal temporal, ciertos interinos y los arrendamientos de inmuebles.',null),
('adm-cm:35-a64904c18a','adm-cm',35,'¿Quién puede modificar excepcionalmente los porcentajes y anualidades de los gastos plurianuales?','["El titular de cada consejería en su ámbito", "El Consejo de Gobierno, previo informe de la Asamblea", "El titular de la consejería competente en materia de hacienda", "La Intervención General"]'::jsonb,2,'Art. 74 Ley 5/2025 CM','En casos especialmente justificados, el titular de la consejería de hacienda puede modificar los límites, a solicitud de la consejería correspondiente.',null),
('adm-cm:35-acb97a5399','adm-cm',35,'¿Hasta qué momento puede llegar la tramitación anticipada de un expediente de gasto?','["Hasta el momento inmediatamente anterior a la autorización del compromiso de gasto", "Hasta la aprobación del gasto incluida", "Hasta la propuesta de pago", "Hasta el reconocimiento de la obligación, siempre que exista crédito en el ejercicio"]'::jsonb,0,'Art. 77 Ley 5/2025 CM','Puede iniciarse en el ejercicio anterior y alcanzar, como máximo, hasta el momento inmediatamente anterior a la autorización del compromiso de gasto.',null),
('adm-cm:35-e18c8ae283','adm-cm',35,'¿Qué ocurre con los créditos no afectados a obligaciones reconocidas el último día del ejercicio?','["Se incorporan automáticamente al ejercicio siguiente", "Se mantienen vigentes tres meses más", "Se transfieren al Fondo de Contingencia", "Quedan anulados de pleno derecho, salvo incorporación"]'::jsonb,3,'Art. 81 Ley 5/2025 CM','Los créditos no afectados a obligaciones reconocidas quedan anulados de pleno derecho, sin perjuicio de las incorporaciones del art. 90.',null),
('adm-cm:35-262f063da3','adm-cm',35,'Si es necesario un gasto inaplazable y no existe crédito, ¿qué se remite a la Asamblea de Madrid?','["Una orden de generación de crédito", "Un proyecto de ley de crédito extraordinario", "Una solicitud de ampliación de crédito", "Un proyecto de ley de suplemento de crédito"]'::jsonb,1,'Art. 83 Ley 5/2025 CM','Si no existe crédito se tramita un crédito extraordinario; si es insuficiente y no ampliable, un suplemento de crédito, ambos por ley.',null),
('adm-cm:35-7b772f6c3c','adm-cm',35,'En un organismo autónomo, ¿quién concede un crédito extraordinario sin aumento del presupuesto general si no excede del 2 % de su presupuesto de gastos?','["La Asamblea de Madrid", "El Consejo de Gobierno", "El gerente del organismo", "El titular de la consejería de hacienda"]'::jsonb,3,'Art. 83 Ley 5/2025 CM','Hasta el 2 % lo concede el titular de la consejería de hacienda; del 2 % al 5 %, el Consejo de Gobierno; en el resto de casos, la Asamblea.',null),
('adm-cm:35-c43c4be9c8','adm-cm',35,'¿Quién autoriza las ampliaciones de crédito según la Ley 5/2025 de Hacienda de Madrid?','["La Comisión de Presupuestos de la Asamblea", "El titular de la consejería afectada", "El titular de la consejería competente en materia de hacienda", "El Consejo de Gobierno"]'::jsonb,2,'Art. 85 Ley 5/2025 CM','Las ampliaciones de crédito son autorizadas por el titular de la consejería competente en materia de hacienda.',null),
('adm-cm:35-d4e4f84616','adm-cm',35,'¿Cuál de estas es una limitación general de las transferencias de crédito?','["No pueden minorar créditos incrementados con suplementos o transferencias", "Necesitan siempre autorización de la Asamblea", "No pueden afectar a créditos de personal", "Solo pueden hacerse en el último trimestre"]'::jsonb,0,'Art. 86 Ley 5/2025 CM','Las transferencias no afectan a créditos ampliables ni extraordinarios del ejercicio, no minoran créditos incrementados y no incrementan créditos minorados.',null),
('adm-cm:35-d6e541f7cb','adm-cm',35,'¿A qué transferencias de crédito NO se aplican las limitaciones generales?','["A las que afecten exclusivamente a créditos para gastos de personal", "A las que creen subvenciones nominativas nuevas", "A todas las que autorice el Consejo de Gobierno", "A las que afecten a créditos ampliables"]'::jsonb,0,'Art. 86 Ley 5/2025 CM','Entre otras, quedan exceptuadas las que afecten exclusivamente a créditos para gastos de personal.',null),
('adm-cm:35-24d8dd7271','adm-cm',35,'¿Qué órgano autoriza las transferencias entre gastos corrientes y de capital de distintas secciones?','["El titular de la consejería de hacienda, sin más trámite ni informe previo de ningún otro órgano", "El Consejo de Gobierno, previo informe favorable de la Comisión de Presupuestos de la Asamblea", "El titular de cada consejería afectada", "La Asamblea de Madrid mediante ley"]'::jsonb,1,'Art. 87 Ley 5/2025 CM','Las autoriza el Consejo de Gobierno, a propuesta del titular de hacienda, previo informe favorable de la comisión de presupuestos de la Asamblea.',null),
('adm-cm:35-83857de2ad','adm-cm',35,'¿Qué requisito exige la incorporación de remanentes de crédito al ejercicio siguiente?','["Que se trate de créditos de personal", "Que lo apruebe la Asamblea en todo caso", "Que exista remanente de tesorería positivo", "Que el crédito se hubiera comprometido en enero"]'::jsonb,2,'Art. 90 Ley 5/2025 CM','Cuando exista remanente de tesorería positivo, el titular de hacienda puede autorizar la incorporación de determinados créditos al ejercicio siguiente.',null),
('adm-cm:35-b98a9f80bb','adm-cm',35,'¿Qué precisa la incorporación de remanentes no comprometidos de ejercicios anteriores?','["Informe de la Cámara de Cuentas", "Acuerdo del Consejo de Gobierno", "Nada especial", "Informe favorable de la Comisión de Presupuestos de la Asamblea de Madrid"]'::jsonb,3,'Art. 90 Ley 5/2025 CM','La incorporación de remanentes no comprometidos precisa informe favorable de la comisión de presupuestos de la Asamblea.',null),
('adm-cm:35-202f1ff680','adm-cm',35,'¿Qué producen los ingresos obtenidos por reintegro de pagos indebidos con cargo a créditos presupuestarios?','["Un mayor remanente de tesorería afectado", "Una generación de crédito previa autorización", "Un ingreso en el Fondo de Contingencia", "La reposición automática del crédito"]'::jsonb,3,'Art. 91 Ley 5/2025 CM','Dan lugar a reposición automática de crédito en la respectiva aplicación presupuestaria.',null),
('adm-cm:36-120c52c5ce','adm-cm',36,'¿Cuál es el orden de las fases de ejecución del gasto?','["Disposición, autorización, reconocimiento de la obligación y propuesta de pago", "Autorización, disposición, reconocimiento de la obligación y propuesta de pago", "Reconocimiento de la obligación, autorización, disposición y propuesta de pago", "Autorización, reconocimiento de la obligación, disposición y propuesta de pago"]'::jsonb,1,'Art. 92 Ley 5/2025 CM','Autorización, disposición, reconocimiento de la obligación y propuesta de pago, en ese orden, aunque pueden acumularse.',null),
('adm-cm:36-1cebf14322','adm-cm',36,'Los anticipos de caja fija son, según la Ley 5/2025:','["Créditos extraordinarios", "Préstamos a empleados públicos", "Provisiones de fondos de carácter permanente para atender gastos periódicos o repetitivos, consideradas operaciones extrapresupuestarias", "Provisiones de fondos de carácter puntual para gastos de inversión, que se aplican al presupuesto antes del pago y se consideran operaciones presupuestarias"]'::jsonb,2,'Art. 102 Ley 5/2025 CM','Son operaciones extrapresupuestarias.',null),
('adm-cm:36-59db60c99d','adm-cm',36,'En los organismos autónomos, la competencia para autorizar y comprometer gastos corresponde, con carácter general, a:','["El Interventor General", "El Consejo de Gobierno", "Sus gerentes", "La Asamblea"]'::jsonb,2,'Art. 94.1 Ley 5/2025 CM','Según el art. 94.1.',null),
('adm-cm:36-211b9d54d2','adm-cm',36,'Según la Ley 5/2025, el proceso de pago comprende las fases de:','["Ordenación del pago y realización del pago", "Autorización y disposición", "Propuesta y fiscalización", "Reconocimiento de la obligación y liquidación"]'::jsonb,0,'Art. 99.1 Ley 5/2025 CM','Ambas se ejercen bajo la autoridad de Hacienda.',null),
('adm-cm:36-19c81edfaf','adm-cm',36,'Corresponde al Consejo de Gobierno autorizar los gastos:','["De capítulo 1 de cada Consejería en todo caso", "De caja fija", "De menos de 3.000 euros", "De cuantía indeterminada, entre otros"]'::jsonb,3,'Art. 95.1 Ley 5/2025 CM','También los plurianuales que superen el límite legal y los que excedan los importes fijados.',null),
('adm-cm:36-ff19d303d8','adm-cm',36,'Según la Ley 5/2025 de Hacienda de Madrid, ¿cuál es el orden de las fases del proceso del gasto?','["Disposición, autorización, propuesta de pago y reconocimiento de la obligación, por este orden", "Autorización, disposición, reconocimiento de la obligación y propuesta de pago", "Compromiso, autorización, ordenación y pago", "Autorización, reconocimiento, disposición y pago material"]'::jsonb,1,'Art. 92 Ley 5/2025 CM','Las fases son autorización, disposición, reconocimiento de la obligación y propuesta de pago, sin omisiones y en ese orden.',null),
('adm-cm:36-706bda9f7a','adm-cm',36,'¿Qué fase del gasto es el acto por el que se acepta una propuesta de gasto y se reserva el crédito adecuado?','["La disposición", "La propuesta de pago", "La autorización", "El reconocimiento de la obligación"]'::jsonb,2,'Art. 92 Ley 5/2025 CM','La autorización es el acto de previsión por el que se acepta una propuesta de gasto, reservando el importe del crédito adecuado.',null),
('adm-cm:36-0596c969b3','adm-cm',36,'¿Con qué fase del gasto queda formalizada la reserva del crédito por importe y condiciones exactamente determinadas?','["Con la disposición o compromiso", "Con la ordenación del pago", "Con la autorización", "Con el reconocimiento de la obligación"]'::jsonb,0,'Art. 92 Ley 5/2025 CM','Con los actos de disposición o compromiso queda formalizada la reserva del crédito por un importe y condiciones exactamente determinadas.',null),
('adm-cm:36-73547dbe0b','adm-cm',36,'¿Qué es el reconocimiento de la obligación?','["La salida material de fondos de la tesorería", "La operación por la que se contraen en cuentas los créditos exigibles contra la Administración", "La solicitud de pago que el centro gestor dirige a la consejería competente en materia de hacienda", "El acto por el que se reserva el crédito"]'::jsonb,1,'Art. 92 Ley 5/2025 CM','Es la operación por la que se contraen en cuentas los créditos exigibles, reconociendo la obligación de cumplir una prestación dineraria.',null),
('adm-cm:36-40ca980f5c','adm-cm',36,'¿Pueden acumularse varias fases del gasto en un solo acto?','["Sí, si el procedimiento y el control previo lo permiten", "Solo la autorización y el pago", "No, cada fase exige un acto distinto", "Solo en los gastos de personal"]'::jsonb,0,'Art. 92 Ley 5/2025 CM','Pueden acumularse en un solo acto y documento siempre que el procedimiento administrativo y el control previo lo permitan.',null)
insert into public.preguntas (id,oposicion,tema,pregunta,opciones,correcta,articulo,explicacion,examen) values
('adm-cm:36-3b5189e804','adm-cm',36,'¿Quién autoriza o compromete en todo caso los gastos del capítulo 1, Gastos de personal, en la Administración de la Comunidad de Madrid?','["El Consejo de Gobierno", "El titular de la consejería de hacienda", "La Dirección General de Función Pública", "El titular de cada consejería"]'::jsonb,3,'Art. 93 Ley 5/2025 CM','Corresponde en todo caso al titular de cada consejería la autorización o el compromiso de los gastos del capítulo 1.',null),
('adm-cm:36-a4fc156416','adm-cm',36,'¿Quién autoriza el gasto cuando afecta a créditos de la sección Deuda Pública?','["El titular de cada consejería", "El Consejo de Gobierno", "El titular de la consejería competente en materia de hacienda", "La Asamblea de Madrid"]'::jsonb,2,'Art. 93 Ley 5/2025 CM','Es competencia del titular de la consejería de hacienda la autorización o el compromiso de gasto que afecte a la sección Deuda Pública.',null),
('adm-cm:36-33c1418e70','adm-cm',36,'En los organismos autónomos, ¿a quién corresponden, con carácter general, los actos del proceso del gasto?','["Al titular de la consejería de adscripción", "A los gerentes", "Al Consejo de Gobierno", "A la Intervención Delegada"]'::jsonb,1,'Art. 94 Ley 5/2025 CM','Salvo los supuestos reservados al Consejo de Gobierno, compete a los gerentes de los organismos autónomos.',null),
('adm-cm:36-6a7b3f0267','adm-cm',36,'¿Cuál de estos gastos está reservado en todo caso al Consejo de Gobierno?','["Los gastos de cuantía indeterminada", "Los gastos menores de 5.000 euros", "Los gastos de arrendamientos prorrogados", "Los gastos de personal de cada consejería"]'::jsonb,0,'Art. 95 Ley 5/2025 CM','Se reservan al Consejo de Gobierno, entre otros, los gastos de cuantía indeterminada y los plurianuales o corrientes que superen los importes de la ley de presupuestos.',null),
('adm-cm:36-adb491317b','adm-cm',36,'¿Qué debe acreditarse antes de reconocer una obligación con cargo a los presupuestos?','["La firma del contrato ante notario", "El informe de la Cámara de Cuentas", "La existencia de remanente de tesorería", "La realización de la prestación o el derecho del acreedor"]'::jsonb,3,'Art. 96 Ley 5/2025 CM','Debe acreditarse documentalmente la realización de la prestación o el derecho del acreedor conforme a los acuerdos de autorización y compromiso.',null),
('adm-cm:36-cc24e0cfe3','adm-cm',36,'¿Qué es el reconocimiento de un derecho económico en la gestión del presupuesto de ingresos?','["La recaudación efectiva del ingreso en la tesorería", "La previsión de ingresos del estado de ingresos", "La operación por la que se contrae en cuentas la deuda exigible a un tercero a favor de la Administración", "El compromiso de un tercero de aportar fondos en el futuro mediante un convenio o un contrato ya firmado"]'::jsonb,2,'Art. 97 Ley 5/2025 CM','Es la operación por la que se contrae en cuentas la deuda a favor de la Administración exigible a un tercero.',null),
('adm-cm:37-d83f711da7','adm-cm',37,'¿Qué modalidades comprende el control interno de la Intervención General de la Comunidad de Madrid?','["Control de legalidad, de oportunidad y de eficacia", "Fiscalización previa, auditoría externa y control parlamentario", "Función interventora, control financiero y control contable", "Intervención formal, material y de pagos"]'::jsonb,2,'Art. 115 Ley 5/2025 CM','El control interno comprende las modalidades de función interventora, control financiero y control contable.',null),
('adm-cm:37-4d8140c9fa','adm-cm',37,'¿Qué carácter tiene la Intervención General de la Comunidad de Madrid?','["Órgano superior de control interno y órgano directivo y gestor de la contabilidad pública", "Órgano consultivo del Consejo de Gobierno", "Unidad administrativa de la secretaría general técnica de la consejería competente en materia de hacienda", "Órgano de control externo dependiente de la Asamblea"]'::jsonb,0,'Art. 111 Ley 5/2025 CM','Es el órgano superior de control interno del sector público autonómico y órgano directivo y gestor de su contabilidad pública.',null),
('adm-cm:37-dc31d93857','adm-cm',37,'¿Con qué principios desarrolla sus funciones la Intervención General de la Comunidad de Madrid?','["Legalidad, publicidad, concurrencia e igualdad", "Autonomía, ejercicio desconcentrado, jerarquía interna y procedimiento contradictorio", "Coordinación, cooperación, lealtad institucional, subsidiariedad y eficacia en la gestión", "Oportunidad, eficacia, economía y celeridad"]'::jsonb,1,'Art. 112 Ley 5/2025 CM','Sus principios son autonomía, ejercicio desconcentrado, jerarquía interna y procedimiento contradictorio.',null),
('adm-cm:37-da8601761c','adm-cm',37,'¿Qué consideración tiene el personal de la Intervención General en el control financiero de subvenciones?','["Auditor externo", "Policía judicial", "Inspector tributario", "Agente de la autoridad"]'::jsonb,3,'Art. 113 Ley 5/2025 CM','En el control financiero de subvenciones, el personal de la Intervención General es considerado agente de la autoridad.',null),
('adm-cm:37-7c590fb693','adm-cm',37,'¿Qué tiene por objeto la función interventora?','["Auditar las cuentas anuales de las empresas públicas", "Controlar, antes de su aprobación, los actos que den lugar a derechos, gastos, ingresos y pagos, para verificar su legalidad", "Comprobar a posteriori, mediante auditorías anuales, la buena gestión financiera de todo el sector público autonómico madrileño", "Verificar la aplicación del plan general de contabilidad pública"]'::jsonb,1,'Art. 116 Ley 5/2025 CM','La función interventora controla previamente los actos que puedan dar lugar a derechos, gastos, ingresos y pagos, para verificar su legalidad.',null),
('adm-cm:37-d63243a6df','adm-cm',37,'¿Por qué se sustituye la fiscalización previa de los derechos?','["Por el control financiero permanente", "Por la intervención material del cobro", "Por la toma de razón en contabilidad", "Por la auditoría pública anual"]'::jsonb,2,'Art. 116 Ley 5/2025 CM','La fiscalización previa de los derechos se sustituye por la inherente a la toma de razón en contabilidad.',null),
('adm-cm:37-f71fa0ea78','adm-cm',37,'¿Quién puede sustituir la función interventora por el control financiero permanente en un organismo?','["El titular de la consejería de hacienda", "El Interventor General", "La Asamblea de Madrid", "El Consejo de Gobierno"]'::jsonb,3,'Art. 116 Ley 5/2025 CM','El Consejo de Gobierno puede sustituir la función interventora por el control financiero permanente en toda la actividad de un organismo o en algunas áreas.',null),
('adm-cm:37-c915571925','adm-cm',37,'¿Qué diferencia la intervención formal de la material?','["La formal verifica los requisitos legales del expediente y la material comprueba la aplicación real de los fondos", "La formal la ejercen siempre los interventores delegados y la material, en exclusiva, el Interventor General en persona", "La formal es previa y la material siempre posterior al pago", "La formal se hace por escrito y la material de palabra"]'::jsonb,0,'Art. 117 Ley 5/2025 CM','La intervención formal verifica los requisitos legales mediante el examen de los documentos; en la material se comprueba la real y efectiva aplicación de los fondos.',null),
('adm-cm:37-e38b09d9fa','adm-cm',37,'En la fiscalización previa de requisitos esenciales, ¿qué se comprueba en todo caso?','["Solo la firma del órgano gestor", "La existencia de crédito adecuado y la competencia del órgano", "La oportunidad del gasto y su eficacia", "La totalidad de los documentos del expediente"]'::jsonb,1,'Art. 118 Ley 5/2025 CM','Se comprueba la existencia de crédito adecuado, la competencia del órgano y que las obligaciones correspondan a gastos aprobados y fiscalizados, más los extremos que fije el Consejo de Gobierno.',null),
('adm-cm:37-e1ad4d1eed','adm-cm',37,'¿Sobre qué gastos puede ejercerse la función interventora sobre una muestra y no sobre el total?','["Los contratos de obras de más de un millón de euros", "Los gastos que aprueba el Consejo de Gobierno", "Los gastos de cuantía indeterminada", "Los gastos de personal y de subvenciones, entre otros de gran volumen"]'::jsonb,3,'Art. 119 Ley 5/2025 CM','Puede ejercerse sobre una muestra en gastos de personal y subvenciones y en otros que afecten a un gran número de actos.',null),
('adm-cm:37-a2b96dad1c','adm-cm',37,'¿Cuál de estos gastos está exento de fiscalización previa en sus fases de autorización y disposición?','["Las subvenciones en concurrencia competitiva", "Los convenios con entidades locales", "Los contratos menores", "Los contratos de obras"]'::jsonb,2,'Art. 120 Ley 5/2025 CM','Están exentos, entre otros, los contratos menores, los gastos periódicos tras el inicial y las subvenciones nominativas.',null),
('adm-cm:37-48fd25da66','adm-cm',37,'¿Hasta qué importe están exentos de fiscalización previa los gastos pagados por anticipo de caja fija?','["Menores de 5.000 euros", "Menores de 50.000 euros", "Menores de 3.000 euros", "Menores de 15.000 euros"]'::jsonb,0,'Art. 120 Ley 5/2025 CM','Están exentos los gastos menores de 5.000 euros cuyo pago se realice mediante anticipo de caja fija.',null),
('adm-cm:37-4103e9ac28','adm-cm',37,'¿Qué es la comprobación material del gasto?','["El examen de la contabilidad del órgano gestor", "La verificación material de la efectiva realización de contratos, convenios y subvenciones", "La comprobación de la existencia de crédito", "La revisión de las cuentas anuales de la Comunidad que realiza cada año la Cámara de Cuentas"]'::jsonb,1,'Art. 122 Ley 5/2025 CM','Es la facultad de verificar materialmente la efectiva realización de los contratos, convenios y subvenciones financiados con fondos públicos.',null),
('adm-cm:37-b1d43d7403','adm-cm',37,'¿Qué efecto tiene la formulación de un reparo por la Intervención?','["Anula el expediente de pleno derecho", "Obliga a remitir el expediente a la Asamblea", "Suspende la tramitación del expediente hasta que se solvente", "Ninguno, es una mera observación"]'::jsonb,2,'Art. 123 Ley 5/2025 CM','El reparo suspende la tramitación del expediente hasta que se subsane o se resuelva la discrepancia.',null),
('adm-cm:37-c7cd1c939b','adm-cm',37,'¿Cuál de estos es un supuesto de reparo en el régimen general de fiscalización previa?','["Que el gasto se proponga a un órgano sin competencia para aprobarlo", "Que el gasto sea inferior al previsto", "Que el gasto se tramite al final del ejercicio", "Que el expediente tenga erratas no esenciales"]'::jsonb,0,'Art. 123 Ley 5/2025 CM','Procede reparo, entre otros, por insuficiencia o inadecuación del crédito, incompetencia del órgano u omisión de requisitos que puedan causar nulidad.',null),
('adm-cm:37-fdde5374c0','adm-cm',37,'¿Tienen efectos suspensivos las observaciones complementarias de la Intervención?','["Solo en gastos superiores a 50.000 euros", "Sí, como los reparos", "Solo si las formula el Interventor General", "No, en ningún caso"]'::jsonb,3,'Art. 123 Ley 5/2025 CM','Las observaciones complementarias no tienen, en ningún caso, efectos suspensivos.',null),
('adm-cm:37-df41e7391d','adm-cm',37,'Si el reparo lo formuló o confirmó la Intervención General y persiste la discrepancia, ¿quién resuelve?','["El Consejo de Gobierno", "La Asamblea de Madrid", "El titular de la consejería de hacienda", "El Tribunal de Cuentas"]'::jsonb,0,'Art. 124 Ley 5/2025 CM','Si el reparo lo formuló o confirmó la Intervención General y subsiste la discrepancia, adopta la resolución definitiva el Consejo de Gobierno.',null),
('adm-cm:37-41243247f4','adm-cm',37,'Si una intervención delegada formula un reparo y el gestor discrepa, ¿quién conoce de la discrepancia?','["La Cámara de Cuentas", "La Intervención General de la Comunidad de Madrid", "El Consejo de Gobierno directamente", "El titular de la consejería afectada"]'::jsonb,1,'Art. 124 Ley 5/2025 CM','Cuando el reparo lo formula una intervención delegada, conoce de la discrepancia la Intervención General, cuya resolución es obligatoria para aquella.',null),
('adm-cm:37-c8378efe7f','adm-cm',37,'Si se ha omitido la fiscalización previa preceptiva, ¿quién acuerda someter la cuestión al Consejo de Gobierno?','["La Intervención General de oficio", "El titular de la consejería de hacienda en todo caso", "El órgano gestor que omitió la fiscalización", "El titular de la consejería del órgano tramitador, sin posibilidad de delegación"]'::jsonb,3,'Art. 125 Ley 5/2025 CM','Corresponde al titular de la consejería del órgano responsable, sin que pueda delegarse, previo informe de la Intervención General.',null),
('adm-cm:38-29b2dc02a7','adm-cm',38,'Las retribuciones básicas están integradas por:','["La productividad y las gratificaciones por servicios extraordinarios", "El sueldo asignado a cada subgrupo o grupo y los trienios", "El complemento de destino y el complemento específico", "El sueldo asignado a cada subgrupo, los trienios y el complemento de destino del puesto que se ocupe"]'::jsonb,1,'Art. 23 TREBEP','Los trienios consisten en una cantidad por cada tres años de servicio.','abr. 2026 · 1.er ejercicio'),
('adm-cm:38-a7fe881a27','adm-cm',38,'Las pagas extraordinarias de los funcionarios serán:','["Una al año, por el importe de una mensualidad de retribuciones básicas", "Cuatro al año", "Tres al año, cada una por el importe de una mensualidad de retribuciones básicas y de la mitad de las complementarias, que se abonan en marzo, junio y diciembre", "Dos al año, cada una por el importe de una mensualidad de retribuciones básicas y de la totalidad de las complementarias, salvo excepciones"]'::jsonb,3,'Art. 22.4 TREBEP','Son dos pagas al año.',null),
('adm-cm:38-19f5a0dba6','adm-cm',38,'La parte de jornada no realizada sin justificación dará lugar a:','["La deducción proporcional de haberes, que no tendrá carácter sancionador", "Ninguna consecuencia económica, aunque deberá recuperarse en otro momento de la semana", "La separación del servicio", "Una sanción disciplinaria grave, previa tramitación del expediente correspondiente"]'::jsonb,0,'Art. 30.1 TREBEP','La deducción no es una sanción.',null),
('adm-cm:38-13b9d0a400','adm-cm',38,'Los trienios consisten en una cantidad, igual para cada subgrupo o grupo, por cada:','["Año de servicio", "Cinco años de servicio", "Dos años de servicio", "Tres años de servicio"]'::jsonb,3,'Art. 23 b) TREBEP','Retribución básica por antigüedad.',null),
('adm-cm:38-193f3ac39d','adm-cm',38,'Las retribuciones de los funcionarios de carrera se clasifican en:','["Ordinarias y extraordinarias", "Directas e indirectas", "Básicas y complementarias", "Fijas y variables"]'::jsonb,2,'Art. 22.1 TREBEP','Las pagas extraordinarias son dos al año.',null),
('adm-cm:38-3cbb6e59cd','adm-cm',38,'Según el TREBEP, ¿dónde deben reflejarse cada año las cuantías de las retribuciones básicas y el incremento de la masa salarial del personal laboral?','["En la relación de puestos de trabajo", "En el convenio colectivo de cada Administración", "En la correspondiente ley de presupuestos", "En un decreto del Consejo de Gobierno"]'::jsonb,2,'Art. 21.1 TREBEP','Deben reflejarse para cada ejercicio presupuestario en la correspondiente ley de presupuestos.',null),
('adm-cm:38-db99c03c3a','adm-cm',38,'¿Cómo se clasifican las retribuciones de los funcionarios de carrera según el TREBEP?','["En ordinarias y extraordinarias", "En salariales y extrasalariales", "En básicas y complementarias", "En fijas y variables"]'::jsonb,2,'Art. 22.1 TREBEP','Las retribuciones de los funcionarios de carrera se clasifican en básicas y complementarias.',null),
('adm-cm:38-d973d934ff','adm-cm',38,'¿Qué retribuyen las retribuciones básicas de los funcionarios?','["Los servicios extraordinarios fuera de la jornada", "Las características del puesto de trabajo", "El rendimiento y los resultados alcanzados", "La adscripción del cuerpo o escala a un subgrupo o grupo y la antigüedad en él"]'::jsonb,3,'Art. 22.2 TREBEP','Retribuyen según la adscripción del cuerpo o escala a un subgrupo o grupo de clasificación profesional y la antigüedad en el mismo.',null),
('adm-cm:38-e33648b9e6','adm-cm',38,'¿Cuántas pagas extraordinarias al año perciben los funcionarios según el TREBEP?','["Dos", "Una", "Tres", "Catorce"]'::jsonb,0,'Art. 22.4 TREBEP','Las pagas extraordinarias serán dos al año.',null),
('adm-cm:38-ea2e98bd6b','adm-cm',38,'¿Qué incluye cada paga extraordinaria de los funcionarios?','["La mitad de las retribuciones anuales", "Una mensualidad de retribuciones básicas y la totalidad de las complementarias, salvo las de productividad y gratificaciones", "Solo el sueldo base y los trienios correspondientes al mes de junio o de diciembre, sin incluir ningún complemento retributivo", "El sueldo y los trienios, sin complementos"]'::jsonb,1,'Art. 22.4 TREBEP','Cada paga incluye una mensualidad de básicas y la totalidad de complementarias, salvo las de las letras c) y d) del art. 24.',null),
('adm-cm:38-ba8ac64e58','adm-cm',38,'¿Por qué está integrado, única y exclusivamente, el conjunto de retribuciones básicas?','["Por el sueldo y los trienios", "Por el sueldo, los trienios y el complemento de destino", "Por el sueldo y el complemento específico", "Por el sueldo, los trienios y la productividad"]'::jsonb,0,'Art. 23 TREBEP','Las retribuciones básicas están integradas única y exclusivamente por el sueldo y los trienios.',null),
('adm-cm:38-77e37d719c','adm-cm',38,'¿Cada cuánto tiempo de servicio se devenga un trienio?','["Cada cuatro años", "Cada tres años", "Cada cinco años", "Cada dos años"]'::jsonb,1,'Art. 23 TREBEP','Los trienios consisten en una cantidad igual para cada subgrupo o grupo por cada tres años de servicio.',null),
('adm-cm:38-3136a26cb8','adm-cm',38,'¿Qué factor retribuyen los servicios extraordinarios prestados fuera de la jornada normal?','["El complemento de puesto", "Los trienios", "Un complemento ligado a los servicios extraordinarios fuera de la jornada", "El complemento de carrera"]'::jsonb,2,'Art. 24 d) TREBEP','Entre los factores de las retribuciones complementarias está la retribución de los servicios extraordinarios prestados fuera de la jornada normal.',null),
('adm-cm:38-3adc6c00cb','adm-cm',38,'¿Qué retribuciones complementarias perciben los funcionarios interinos según el TREBEP?','["Todas las del funcionario de carrera, incluida la progresión alcanzada en la carrera administrativa", "Solo las gratificaciones extraordinarias", "Ninguna, solo las básicas", "Las de los apartados b), c) y d) del art. 24 y las de la categoría de entrada"]'::jsonb,3,'Art. 25.1 TREBEP','Perciben las complementarias de las letras b), c) y d) del art. 24 y las de la categoría de entrada en el cuerpo o escala.',null),
('adm-cm:38-4930f14f6f','adm-cm',38,'¿Cuál es la retribución mínima de los funcionarios en prácticas según el TREBEP?','["Las retribuciones íntegras del puesto que ocuparán", "El salario mínimo interprofesional", "El sueldo del subgrupo o grupo al que aspiran a ingresar", "El 80 % de las retribuciones del puesto"]'::jsonb,2,'Art. 26 TREBEP','Como mínimo, corresponderán al sueldo del subgrupo o grupo en que aspiren a ingresar.',null),
('adm-cm:38-88eb37d27b','adm-cm',38,'¿Qué consideración tienen las cantidades destinadas a planes de pensiones de empleo del personal público?','["Retribución diferida", "Indemnización por razón del servicio", "Complemento personal transitorio", "Acción social"]'::jsonb,0,'Art. 29 TREBEP','Las cantidades destinadas a financiar aportaciones a planes de pensiones o seguros tienen la consideración de retribución diferida.',null),
('adm-cm:38-936149faed','adm-cm',38,'¿Qué carácter tiene la deducción proporcional de haberes por la parte de jornada no realizada?','["Es una sanción disciplinaria grave", "No tiene carácter sancionador", "Solo procede si hay expediente disciplinario", "Es una sanción disciplinaria leve"]'::jsonb,1,'Art. 30.1 TREBEP','La parte de jornada no realizada da lugar a la deducción proporcional de haberes, que no tendrá carácter sancionador.',null),
('adm-cm:38-36b9be2174','adm-cm',38,'¿Afecta a sus prestaciones sociales la deducción de haberes de quien ejerce el derecho de huelga?','["Solo afecta a los trienios", "Sí, si la huelga dura más de tres días", "Sí, reduce proporcionalmente la pensión", "No, ni tiene carácter de sanción"]'::jsonb,3,'Art. 30.2 TREBEP','La deducción de haberes por huelga no tiene carácter de sanción ni afecta al régimen de sus prestaciones sociales.',null),
('adm-cm:39-cc8af42622','adm-cm',39,'Según el marco conceptual del Plan General de Contabilidad Pública, ¿qué documentos forman las cuentas anuales?','["Balance, estado de liquidación del presupuesto, cuenta general de la comunidad autónoma, memoria de gestión del ejercicio, inventario de bienes y estado de la deuda", "Balance de sumas y saldos, libro diario y memoria", "Balance, cuenta del resultado económico patrimonial, estado de cambios en el patrimonio neto, estado de liquidación del presupuesto, estado de flujos de efectivo y memoria", "Balance, cuenta de pérdidas y ganancias e informe de gestión"]'::jsonb,2,'PGCP, 1.ª parte, 1.º Orden EHA/1037/2010','Las cuentas anuales comprenden el balance, la cuenta del resultado económico patrimonial, el estado de cambios en el patrimonio neto, el de liquidación del presupuesto, el de flujos de efectivo y la memoria.',null),
('adm-cm:39-2c766208fb','adm-cm',39,'Según el PGCP, ¿qué constituye la entidad contable?','["Todo ente con personalidad jurídica y presupuesto propio que deba formar y rendir cuentas", "Toda unidad administrativa que gestione fondos públicos, aunque carezca de personalidad jurídica propia", "Todo órgano administrativo con crédito asignado", "Solo la Administración General de cada comunidad"]'::jsonb,0,'PGCP, 1.ª parte, 1.º Orden EHA/1037/2010','Constituye la entidad contable todo ente con personalidad jurídica y presupuesto propio que deba formar y rendir cuentas.',null),
('adm-cm:39-1fcabaaf3d','adm-cm',39,'En la contabilización de las operaciones según el PGCP, ¿a qué se atenderá?','["Exclusivamente a su forma jurídica", "Al criterio del órgano gestor", "A su incidencia presupuestaria únicamente", "A su realidad económica y no solo a su forma jurídica"]'::jsonb,3,'PGCP, 1.ª parte, 1.º Orden EHA/1037/2010','Se atenderá a la realidad económica de las operaciones y no solo a su forma jurídica.',null),
('adm-cm:39-e1027cf894','adm-cm',39,'¿Cuál de estos es un requisito de la información de las cuentas anuales según el PGCP?','["La exhaustividad presupuestaria", "La comparabilidad", "La confidencialidad", "La inmediatez"]'::jsonb,1,'PGCP, 1.ª parte, 2.º Orden EHA/1037/2010','Los requisitos son claridad, relevancia, fiabilidad y comparabilidad.',null),
('adm-cm:39-9bd19d9fe2','adm-cm',39,'¿Qué principio contable presume que la actividad de la entidad continúa por tiempo indefinido?','["Gestión continuada", "Uniformidad", "Devengo", "Prudencia"]'::jsonb,0,'PGCP, 1.ª parte, 3.º Orden EHA/1037/2010','Por el principio de gestión continuada se presume, salvo prueba en contrario, que la actividad continúa por tiempo indefinido.',null),
('adm-cm:39-ca6906abdf','adm-cm',39,'¿Qué principio exige reconocer las transacciones según la corriente real de bienes y servicios y no según la corriente monetaria?','["Gestión continuada", "Devengo", "Imputación presupuestaria", "No compensación"]'::jsonb,1,'PGCP, 1.ª parte, 3.º Orden EHA/1037/2010','El principio de devengo exige reconocer las transacciones en función de la corriente real de bienes y servicios.',null),
('adm-cm:39-8cdc395fee','adm-cm',39,'¿Qué principio obliga a mantener en el tiempo el criterio contable adoptado entre las alternativas permitidas?','["Prudencia", "Desafectación", "Importancia relativa", "Uniformidad"]'::jsonb,3,'PGCP, 1.ª parte, 3.º Orden EHA/1037/2010','Por el principio de uniformidad, el criterio adoptado debe mantenerse en el tiempo mientras no se alteren los supuestos de su elección.',null),
('adm-cm:39-acc359cac9','adm-cm',39,'¿Qué principio impide compensar partidas del activo y del pasivo o de gastos e ingresos?','["Devengo", "Uniformidad", "No compensación", "Importancia relativa"]'::jsonb,2,'PGCP, 1.ª parte, 3.º Orden EHA/1037/2010','Por el principio de no compensación no pueden compensarse partidas del activo y pasivo ni de gastos e ingresos, salvo regulación excepcional.',null),
('adm-cm:39-cf1e2e3647','adm-cm',39,'En caso de conflicto entre principios contables, ¿cuál debe prevalecer según el PGCP?','["El que mejor conduzca a que las cuentas expresen la imagen fiel", "Siempre el de devengo", "El que establezca la Intervención General", "Siempre el de prudencia"]'::jsonb,0,'PGCP, 1.ª parte, 3.º Orden EHA/1037/2010','Debe prevalecer el principio que mejor conduzca a que las cuentas anuales expresen la imagen fiel.',null),
('adm-cm:39-2ca1189dca','adm-cm',39,'¿Cuál de estos es un principio contable de carácter presupuestario según el PGCP?','["Gestión continuada", "No compensación", "Desafectación", "Prudencia"]'::jsonb,2,'PGCP, 1.ª parte, 3.º Orden EHA/1037/2010','Los principios presupuestarios destacados son el de imputación presupuestaria y el de desafectación.',null),
('adm-cm:39-13e71e108d','adm-cm',39,'Según el principio de desafectación, ¿cómo se destinan, con carácter general, los ingresos presupuestarios?','["Cada ingreso a un gasto concreto previamente determinado", "A los gastos de la misma consejería que los recauda", "Primero a la deuda y después al resto de gastos", "A financiar la totalidad de los gastos, sin relación directa entre unos y otros"]'::jsonb,3,'PGCP, 1.ª parte, 3.º Orden EHA/1037/2010','Con carácter general, los ingresos presupuestarios financian la totalidad de los gastos sin relación directa entre unos y otros.',null),
('adm-cm:39-bef42e76e6','adm-cm',39,'Según el marco conceptual del PGCP, ¿qué es el patrimonio neto?','["El conjunto de bienes de dominio público", "La parte residual de los activos una vez deducidos todos los pasivos", "El resultado económico patrimonial del ejercicio", "La suma de activos y pasivos de la entidad"]'::jsonb,1,'PGCP, 1.ª parte, 4.º Orden EHA/1037/2010','El patrimonio neto constituye la parte residual de los activos de la entidad, una vez deducidos todos sus pasivos.',null),
('adm-cm:39-7dda6fa9cd','adm-cm',39,'¿Qué son los pasivos según el PGCP?','["Obligaciones futuras derivadas de compromisos aún no firmados que previsiblemente se asumirán el año siguiente", "Las partidas del presupuesto de gastos", "Obligaciones actuales surgidas de sucesos pasados cuya extinción probablemente disminuirá los recursos", "Los bienes y derechos controlados por la entidad"]'::jsonb,2,'PGCP, 1.ª parte, 4.º Orden EHA/1037/2010','Son obligaciones actuales surgidas de sucesos pasados cuya extinción es probable que dé lugar a una disminución de recursos; incluyen las provisiones.',null),
('adm-cm:39-1b6cecbe7d','adm-cm',39,'¿Qué activos son portadores de potencial de servicio según el PGCP?','["Solo los bienes inmuebles de uso administrativo", "Los que generan flujos de efectivo por su venta", "Los que se poseen para obtener un beneficio comercial", "Los que se poseen con una finalidad distinta a la de generar un rendimiento comercial"]'::jsonb,3,'PGCP, 1.ª parte, 4.º Orden EHA/1037/2010','Los activos portadores de potencial de servicio se poseen con una finalidad distinta a la de generar un rendimiento comercial.',null),
('adm-cm:39-084de8cb49','adm-cm',39,'¿Cuándo se reconoce un gasto presupuestario en el estado de liquidación del presupuesto?','["Cuando se autoriza el gasto", "Cuando se dicta el acto de reconocimiento y liquidación de la obligación presupuestaria", "Cuando se aprueba el presupuesto y se consigna el crédito correspondiente en el estado de gastos", "Cuando se paga la obligación"]'::jsonb,1,'PGCP, 1.ª parte, 5.º Orden EHA/1037/2010','Se reconoce cuando se dicta el acto administrativo de reconocimiento y liquidación de la obligación presupuestaria.',null),
('adm-cm:39-db820bdee3','adm-cm',39,'Según el PGCP, ¿qué es el importe recuperable de un activo?','["El mayor entre su valor razonable menos los costes de venta y su valor en uso", "El valor catastral actualizado", "Su precio de adquisición menos la amortización", "El menor entre su valor contable y su valor razonable"]'::jsonb,0,'PGCP, 1.ª parte, 6.º Orden EHA/1037/2010','El importe recuperable es el mayor entre el valor razonable menos los costes de venta y el valor en uso.',null),
('adm-cm:39-671596838e','adm-cm',39,'¿Cómo se determina el valor en uso de los activos portadores de potencial de servicio?','["Por su valor razonable menos costes de venta", "Por el coste de reposición depreciado", "Por su precio de adquisición actualizado con el IPC", "Por el valor actual de sus flujos de efectivo"]'::jsonb,1,'PGCP, 1.ª parte, 6.º Orden EHA/1037/2010','El valor en uso de los activos portadores de potencial de servicio se determina por el coste de reposición depreciado.',null),
('adm-cm:39-069cce3d14','adm-cm',39,'¿Tiene la consideración de valor razonable el resultado de una transacción forzada o urgente?','["No, en ningún caso", "Sí, si la acepta la Intervención", "Solo si se trata de bienes muebles", "Sí, si se formaliza ante notario"]'::jsonb,0,'PGCP, 1.ª parte, 6.º Orden EHA/1037/2010','No tendrá en ningún caso el carácter de valor razonable el que resulte de una transacción forzada, urgente o de una liquidación involuntaria.',null),
('adm-cm:40-7202659c3a','adm-cm',40,'¿Cuántos bytes tiene un kilobyte (KB) en el sistema binario tradicional?','["1.000 bytes", "1.024 bytes", "1.048 bytes", "512 bytes"]'::jsonb,1,'Unidades de información','1 KB = 2^10 bytes = 1.024 bytes. En el sistema internacional, 1 kB = 1.000 bytes (y 1 KiB = 1.024).',null),
('adm-cm:40-2cdfc77b4e','adm-cm',40,'¿Cuántos bits forman un byte?','["8", "10", "16", "4"]'::jsonb,0,'Unidades de información','Un byte permite representar 256 valores distintos.',null),
('adm-cm:40-f276c7bed2','adm-cm',40,'¿Qué unidad de almacenamiento es mayor?','["Un terabyte", "Un kilobyte", "Un megabyte", "Un gigabyte"]'::jsonb,0,'Unidades de información','Orden creciente: kilobyte, megabyte, gigabyte, terabyte, petabyte.',null),
('adm-cm:40-3c70ed2ad7','adm-cm',40,'La memoria RAM se caracteriza por ser:','["Volátil, de lectura y escritura", "No volátil, de lectura y escritura", "Volátil y de solo lectura", "No volátil y de solo lectura"]'::jsonb,0,'Memoria','Su contenido se pierde al apagar el equipo. La ROM es no volátil y, en principio, de solo lectura.',null),
('adm-cm:40-6aeb633448','adm-cm',40,'¿Qué componente del ordenador ejecuta las instrucciones de los programas?','["La tarjeta de red", "La fuente de alimentación", "El procesador o CPU", "El disco duro"]'::jsonb,2,'Hardware','La CPU incluye la unidad de control y la unidad aritmético-lógica.',null),
('adm-cm:40-4b48ea3a5a','adm-cm',40,'¿Qué parte de la CPU realiza las operaciones aritméticas y lógicas?','["La unidad de control del procesador", "La unidad aritmético-lógica (ALU)", "La memoria caché interna del procesador", "El bus de datos y direcciones del sistema"]'::jsonb,1,'Hardware','La unidad de control interpreta las instrucciones y coordina el resto de componentes.',null),
('adm-cm:40-abd600c32f','adm-cm',40,'¿Cuál de los siguientes es un periférico de entrada?','["Los altavoces", "El monitor", "La impresora", "El escáner"]'::jsonb,3,'Periféricos','Impresora, monitor y altavoces son periféricos de salida.',null),
('adm-cm:40-978f59f8fb','adm-cm',40,'Una pantalla táctil es un periférico:','["De almacenamiento", "De entrada y salida", "Exclusivamente de salida", "Exclusivamente de entrada"]'::jsonb,1,'Periféricos','Muestra información y a la vez recibe órdenes del usuario.',null),
('adm-cm:40-a64bad3c85','adm-cm',40,'¿Qué tipo de unidad de almacenamiento no tiene partes mecánicas móviles?','["El SSD", "El disco duro HDD", "El disquete", "La unidad de cinta"]'::jsonb,0,'Almacenamiento','Los SSD usan memoria flash; por eso son más rápidos y resistentes a golpes que los HDD.',null),
('adm-cm:40-5260294ef1','adm-cm',40,'El firmware que inicia el hardware al encender el ordenador y arranca el sistema operativo es, en los equipos actuales:','["La UEFI, sucesora de la BIOS", "El controlador de la tarjeta gráfica", "El gestor de arranque de la memoria RAM", "El sistema de archivos NTFS"]'::jsonb,0,'Arranque del equipo','La BIOS es el firmware tradicional; la UEFI la sustituye en los equipos modernos.',null),
('adm-cm:40-83d479c7be','adm-cm',40,'¿Cuál de los siguientes es un sistema operativo?','["Chrome", "Excel", "Linux", "Java"]'::jsonb,2,'Software','Excel es una aplicación, Chrome un navegador y Java un lenguaje de programación.',null),
('adm-cm:40-bbbfc921f9','adm-cm',40,'El software cuyo código fuente puede estudiarse, modificarse y redistribuirse libremente se denomina:','["Freeware", "Software propietario", "Shareware", "Software libre"]'::jsonb,3,'Tipos de software','El freeware es gratuito pero no necesariamente permite acceder al código ni modificarlo.',null),
('adm-cm:40-d15fce67f6','adm-cm',40,'¿Qué sistema de numeración utiliza internamente el ordenador?','["El octal", "El decimal", "El binario", "El romano"]'::jsonb,2,'Representación de la información','Solo usa los dígitos 0 y 1.',null),
('adm-cm:40-94422f0671','adm-cm',40,'El número decimal 10 se representa en binario como:','["1100", "1010", "0110", "1001"]'::jsonb,1,'Representación de la información','1010 = 8 + 0 + 2 + 0 = 10.',null),
('adm-cm:40-27986409b5','adm-cm',40,'Una red que conecta los ordenadores de un mismo edificio u oficina se denomina:','["VPN", "MAN", "WAN", "LAN"]'::jsonb,3,'Redes','LAN es red de área local; WAN, de área extensa; MAN, metropolitana; VPN, red privada virtual.',null),
('adm-cm:40-59b0b0da10','adm-cm',40,'¿Qué tipo de puerto se usa habitualmente para conectar un monitor con audio y vídeo digital?','["VGA", "RJ-45", "PS/2", "HDMI"]'::jsonb,3,'Puertos','El RJ-45 se usa para la red, el PS/2 para teclados y ratones antiguos, y el VGA transmite solo vídeo analógico.',null),
('adm-cm:40-2f10b08edc','adm-cm',40,'El malware que cifra los archivos del usuario y pide un rescate para recuperarlos se llama:','["Ransomware", "Spyware", "Gusano", "Adware"]'::jsonb,0,'Seguridad','El spyware espía la actividad del usuario y el adware muestra publicidad no deseada.',null),
('adm-cm:40-13ab6cd066','adm-cm',40,'Un troyano es:','["Un programa malicioso que se presenta como legítimo para que el usuario lo instale", "Un programa que se replica por sí solo a través de la red sin intervención del usuario", "Un programa que muestra publicidad emergente", "Un correo que suplanta a una entidad para robar contraseñas"]'::jsonb,0,'Seguridad','El gusano se replica solo; la suplantación por correo es phishing; la publicidad emergente, adware.',null),
('adm-cm:40-936615f1f0','adm-cm',40,'El phishing consiste en:','["Infectar un equipo a través de una memoria USB que ejecuta automáticamente un programa", "Bloquear un servidor saturándolo con miles de peticiones simultáneas desde muchos equipos", "Suplantar la identidad de una entidad de confianza para obtener datos confidenciales", "Instalar en secreto un programa que registra todas las pulsaciones del teclado del usuario"]'::jsonb,2,'Seguridad','Bloquear un servidor con peticiones masivas es un ataque de denegación de servicio (DoS); registrar pulsaciones, un keylogger.',null),
('adm-cm:40-4291a0991c','adm-cm',40,'Una copia de seguridad incremental guarda:','["Solo los archivos modificados desde la última copia completa, sin tener en cuenta las demás", "Todos los archivos del equipo cada vez", "Solo los archivos modificados desde la última copia, sea completa o incremental", "Únicamente los archivos del sistema operativo"]'::jsonb,2,'Copias de seguridad','La copia diferencial guarda los cambios desde la última copia completa.',null),
('adm-cm:40-00b44b2f8a','adm-cm',40,'La memoria caché es:','["Una memoria de solo lectura que contiene la BIOS", "Un espacio del disco duro que el sistema operativo utiliza como memoria cuando la RAM se llena", "Una memoria muy rápida y pequeña que guarda los datos que el procesador usa con más frecuencia", "La memoria secundaria, como el disco duro o el SSD, donde se instalan los programas y se guardan los archivos"]'::jsonb,2,'Memoria','El espacio en disco usado cuando la RAM se llena es la memoria virtual o archivo de paginación.',null),
('adm-cm:40-1529d23754','adm-cm',40,'¿Qué es un controlador o driver?','["Una aplicación del sistema operativo para crear y restaurar copias de seguridad de los archivos", "El usuario con permisos de administrador que puede instalar y desinstalar programas en el equipo", "Un componente físico de la placa base que conecta el procesador con el resto de dispositivos", "Un programa que permite al sistema operativo comunicarse con un dispositivo de hardware"]'::jsonb,3,'Software','Cada dispositivo necesita su controlador para funcionar correctamente.',null),
('adm-cm:40-7d0fcb6d79','adm-cm',40,'La computación en la nube (cloud computing) consiste en:','["Conectar varios ordenadores de una misma oficina en una red local sin cables mediante tecnología wifi", "Guardar archivos en una memoria USB externa", "Usar recursos informáticos, como almacenamiento o aplicaciones, ofrecidos a través de internet", "Instalar programas solo desde un CD o DVD"]'::jsonb,2,'Cloud computing','Ejemplos: OneDrive, Google Drive o Microsoft 365.',null),
('adm-cm:40-22290331f6','adm-cm',40,'¿Qué significan las siglas SaaS en la computación en la nube?','["Servidor de aplicaciones en red", "Seguridad como servicio", "Sistema de almacenamiento seguro", "Software como servicio"]'::jsonb,3,'Cloud computing','Junto a SaaS están IaaS (infraestructura como servicio) y PaaS (plataforma como servicio).',null),
('adm-cm:40-1490c87c58','adm-cm',40,'¿Cuántos bits forman un nibble o cuarteto?','["2", "4", "16", "8"]'::jsonb,1,'Unidades de información','Un nibble son 4 bits, la mitad de un byte.',null),
('adm-cm:40-b50afb37a3','adm-cm',40,'En el sistema binario tradicional, un gigabyte equivale a:','["1.024 megabytes", "1.000 megabytes", "2.048 megabytes", "512 megabytes"]'::jsonb,0,'Unidades de información','Cada unidad es 1.024 veces la anterior: 1 GB = 1.024 MB.',null),
('adm-cm:40-916444c7e7','adm-cm',40,'El número binario 1111 equivale en decimal a:','["11", "15", "14", "16"]'::jsonb,1,'Representación de la información','8 + 4 + 2 + 1 = 15.',null),
('adm-cm:40-6ab5e04fc8','adm-cm',40,'¿Qué sistema de numeración utiliza los dígitos del 0 al 9 y las letras de la A a la F?','["El hexadecimal", "El binario", "El octal", "El decimal"]'::jsonb,0,'Representación de la información','El sistema hexadecimal tiene base 16: 0-9 y A-F.',null),
('adm-cm:40-92e653e1aa','adm-cm',40,'La memoria ROM se caracteriza por ser:','["Volátil y de solo lectura", "No volátil y, en principio, de solo lectura", "Volátil y de lectura y escritura", "Una memoria de almacenamiento masivo externa"]'::jsonb,1,'Memoria','La ROM conserva los datos sin corriente y está pensada para leerse, no para escribirse en el uso normal.',null),
('adm-cm:40-ddb6f8af2e','adm-cm',40,'¿Qué componente conecta todos los elementos internos del ordenador y permite que se comuniquen?','["La placa base", "El disipador", "La fuente de alimentación", "La tarjeta gráfica"]'::jsonb,0,'Hardware','La placa base aloja y comunica el procesador, la memoria y el resto de componentes.',null),
('adm-cm:40-9772830649','adm-cm',40,'La GPU de un ordenador es:','["La unidad principal de almacenamiento", "El procesador especializado en gráficos", "El controlador de la red inalámbrica", "La memoria intermedia del disco duro"]'::jsonb,1,'Hardware','La GPU (unidad de procesamiento gráfico) se encarga de calcular y mostrar las imágenes.',null),
('adm-cm:40-130ced6056','adm-cm',40,'¿Cuál de los siguientes es un periférico de salida?','["El micrófono", "El lector de códigos de barras", "La impresora", "El ratón"]'::jsonb,2,'Periféricos','La impresora saca información del ordenador; los otros tres la introducen.',null),
('adm-cm:40-8b0dd827b2','adm-cm',40,'Un disco duro tradicional (HDD) guarda la información:','["En platos magnéticos que giran", "En chips de memoria flash", "En la memoria RAM del equipo", "En discos ópticos grabados con láser"]'::jsonb,0,'Almacenamiento','El HDD usa platos magnéticos y un cabezal móvil; el SSD usa memoria flash sin partes móviles.',null),
('adm-cm:40-740962317a','adm-cm',40,'Un procesador de textos es un ejemplo de:','["Controlador de dispositivo", "Software de aplicación", "Firmware", "Software de sistema"]'::jsonb,1,'Tipos de software','Los programas para tareas del usuario (textos, hojas de cálculo) son software de aplicación.',null),
('adm-cm:40-60ca95cf6a','adm-cm',40,'En la computación en la nube, IaaS significa:','["Integración como servicio", "Internet como servicio", "Infraestructura como servicio", "Información como servicio"]'::jsonb,2,'Cloud computing','IaaS ofrece servidores, almacenamiento y redes virtuales como servicio.',null),
('adm-cm:40-6065490d5a','adm-cm',40,'Un gusano informático se caracteriza por:','["Propagarse por sí mismo a otros equipos a través de la red", "Cifrar los archivos del usuario y pedir un rescate económico para liberarlos", "Mostrar publicidad no deseada en el navegador", "Registrar las teclas que pulsa el usuario"]'::jsonb,0,'Seguridad','El gusano se replica solo; el ransomware cifra, el adware muestra anuncios y el keylogger registra pulsaciones.',null),
('adm-cm:40-cff4eefa02','adm-cm',40,'Una copia de seguridad diferencial guarda:','["Los archivos modificados desde la última copia de cualquier tipo", "Solo los archivos creados ese mismo día", "Todos los archivos del equipo cada vez", "Los archivos modificados desde la última copia completa"]'::jsonb,3,'Copias de seguridad','La diferencial toma como referencia la última copia completa; la incremental, la última copia de cualquier tipo.',null),
('adm-cm:40-f409a95b55','adm-cm',40,'La verificación en dos pasos consiste en:','["Iniciar sesión a la vez desde dos dispositivos", "Usar dos contraseñas distintas, una para el usuario y otra para el equipo, en cada acceso", "Cambiar la contraseña cada dos meses", "Pedir, además de la contraseña, un segundo factor, como un código en el móvil"]'::jsonb,3,'Seguridad','Combina algo que sabes (contraseña) con algo que tienes (móvil, llave) o que eres (huella).',null),
('adm-cm:40-32985bce1a','adm-cm',40,'Una red que abarca una zona geográfica amplia, como un país, se denomina:','["WAN", "PAN", "WLAN", "LAN"]'::jsonb,0,'Redes','WAN es red de área amplia; LAN, local; PAN, personal; WLAN, local inalámbrica.',null),
('adm-cm:40-07c723aed2','adm-cm',40,'¿Qué protocolo se usa para transferir páginas web de forma cifrada?','["SMTP", "HTTPS", "HTTP", "FTP"]'::jsonb,1,'Protocolos de internet','HTTPS es HTTP sobre una conexión cifrada con TLS. FTP transfiere archivos y SMTP envía correo.',null),
('adm-cm:40-80f100689e','adm-cm',40,'¿Qué función cumple el sistema DNS en internet?','["Asignar una dirección de correo a cada usuario", "Traducir los nombres de dominio en direcciones IP", "Bloquear el acceso a páginas peligrosas", "Cifrar las comunicaciones entre el navegador y el servidor"]'::jsonb,1,'DNS','Gracias al DNS escribimos «boe.es» en lugar de la dirección IP del servidor.',null),
('adm-cm:40-c92959ffef','adm-cm',40,'En la dirección https://www.boe.es/diario_boe/, ¿cuál es el dominio de primer nivel?','["boe", "diario_boe", ".es", "www"]'::jsonb,2,'Dominios','El dominio de primer nivel es la última parte del nombre: .es, .com, .org, etc.',null),
('adm-cm:40-5183c7f897','adm-cm',40,'¿Qué protocolo se utiliza para enviar correo electrónico?','["HTTP", "POP3", "SMTP", "IMAP"]'::jsonb,2,'Correo electrónico','POP3 e IMAP se usan para recibir o consultar el correo.',null),
('adm-cm:40-e3dcabf7de','adm-cm',40,'¿Quién creó la World Wide Web?','["Bill Gates, en la empresa Microsoft", "Tim Berners-Lee, en el CERN", "Linus Torvalds, en la Universidad de Helsinki", "Vinton Cerf, en el proyecto ARPANET"]'::jsonb,1,'Historia de internet','La propuso en 1989 y desarrolló el primer navegador y servidor web.',null),
('adm-cm:40-341866bae8','adm-cm',40,'El lenguaje de marcado con el que se escriben las páginas web es:','["HTML", "XML", "CSS", "SQL"]'::jsonb,0,'Lenguajes web','CSS se usa para el diseño o estilo, SQL para bases de datos y XML para intercambio de datos.',null),
('adm-cm:40-91904ce258','adm-cm',40,'Una cookie es:','["Un programa malicioso que se instala en el equipo al visitar determinadas páginas web sin que el usuario lo sepa", "Un pequeño archivo que el sitio web guarda en el navegador del usuario para recordar información", "Un buscador alternativo a Google", "Un certificado digital que acredita que la web es segura y que pertenece a la organización que dice ser"]'::jsonb,1,'Navegación','Sirve, por ejemplo, para recordar el idioma, la sesión iniciada o el carrito de compra.',null),
('adm-cm:40-266ddb4f8a','adm-cm',40,'La navegación InPrivate o de incógnito:','["Impide que el proveedor de internet vea las páginas visitadas", "No guarda en el equipo el historial, las cookies ni los datos de formularios al cerrar la ventana", "Oculta la dirección IP del usuario a todos los sitios web que visita, de modo que navega de forma anónima", "Protege el equipo frente a cualquier virus"]'::jsonb,1,'Navegación privada','No hace al usuario anónimo frente a los sitios web, su empresa o su proveedor de internet.',null),
('adm-cm:40-b263a0333e','adm-cm',40,'En Microsoft Edge, ¿qué combinación abre una nueva ventana InPrivate?','["Ctrl + Mayús + I", "Ctrl + Mayús + P", "Ctrl + Mayús + N", "Ctrl + N"]'::jsonb,2,'Atajos del navegador','En Firefox, la ventana privada se abre con Ctrl + Mayús + P.',null),
('adm-cm:40-f47670038e','adm-cm',40,'En los navegadores, Ctrl + Mayús + T sirve para:','["Traducir la página al idioma configurado en el navegador", "Cerrar todas las pestañas abiertas salvo la actual", "Abrir una nueva pestaña en blanco junto a la actual", "Volver a abrir la última pestaña cerrada"]'::jsonb,3,'Atajos del navegador','Ctrl + T abre una pestaña nueva y Ctrl + W cierra la actual.',null),
('adm-cm:40-12cb63d7a9','adm-cm',40,'¿Qué combinación de teclas añade la página actual a Favoritos o Marcadores?','["Ctrl + D", "Ctrl + B", "Ctrl + F", "Ctrl + H"]'::jsonb,0,'Atajos del navegador','Ctrl + F busca en la página y Ctrl + H abre el historial.',null),
('adm-cm:40-09d98b1aed','adm-cm',40,'En los navegadores, Ctrl + J abre:','["Las descargas", "Los favoritos", "El historial", "Una pestaña nueva"]'::jsonb,0,'Atajos del navegador','Ctrl + H abre el historial.',null),
('adm-cm:40-4465a91f37','adm-cm',40,'La tecla F5 en un navegador sirve para:','["Actualizar o recargar la página", "Ir a la página de inicio configurada en el navegador", "Activar o desactivar el modo de pantalla completa", "Imprimir la página o guardarla como PDF"]'::jsonb,0,'Atajos del navegador','F11 activa la pantalla completa.',null),
('adm-cm:40-840dc631c4','adm-cm',40,'Una intranet es:','["La parte de internet que solo puede visitarse con navegadores especiales y que no aparece indexada en los buscadores", "Una red que conecta varias organizaciones entre sí a través de satélites", "Una red privada de una organización que usa las tecnologías de internet y solo es accesible para sus miembros", "Una red pública mundial accesible para cualquier persona"]'::jsonb,2,'Redes','Si se abre a usuarios externos autorizados (proveedores, clientes), se habla de extranet.',null),
('adm-cm:40-39fcc90de4','adm-cm',40,'¿Qué es una dirección IP?','["El nombre de dominio con el que se identifica una página web en internet", "La contraseña que protege el acceso a la red wifi de una casa u oficina", "Un número que identifica a un dispositivo dentro de una red", "El código de un certificado digital"]'::jsonb,2,'Direccionamiento','Existen direcciones IPv4 (32 bits) e IPv6 (128 bits).',null),
('adm-cm:40-4690cc0d7e','adm-cm',40,'¿Cuántos bits tiene una dirección IPv6?','["256", "128", "64", "32"]'::jsonb,1,'Direccionamiento','Las direcciones IPv4 tienen 32 bits.',null),
('adm-cm:40-e3bb5f82aa','adm-cm',40,'La URL es:','["El nombre del programa que se usa para navegar por internet", "El protocolo de cifrado que utilizan las páginas web seguras", "La dirección que identifica un recurso en internet", "El servidor físico en el que se aloja una página web"]'::jsonb,2,'Navegación','Por ejemplo, https://administracion.gob.es.',null),
('adm-cm:40-0dcae52c2b','adm-cm',40,'¿Qué indica el candado que aparece junto a la dirección en el navegador?','["Que la conexión con el sitio está cifrada", "Que el sitio es oficial y no puede ser fraudulento", "Que la web está bloqueada", "Que la página no usa cookies"]'::jsonb,0,'Seguridad','Una web fraudulenta también puede tener conexión cifrada; el candado no garantiza que sea legítima.',null),
('adm-cm:40-f3695db272','adm-cm',40,'Un motor de búsqueda o buscador es:','["La aplicación que muestra las páginas web en pantalla", "Un programa para descargar archivos de forma más rápida", "Un sistema que localiza páginas web según las palabras clave que introduce el usuario", "Un servidor que asigna los nombres de dominio a las organizaciones que los solicitan y pagan por ellos"]'::jsonb,2,'Buscadores','La aplicación que muestra las páginas es el navegador.',null),
('adm-cm:40-beef377c0e','adm-cm',40,'En la mayoría de buscadores, escribir una frase entre comillas sirve para:','["Excluir esas palabras de la búsqueda", "Buscar exactamente esa frase", "Buscar sinónimos", "Buscar solo imágenes"]'::jsonb,1,'Buscadores','El signo menos delante de una palabra la excluye de los resultados.',null),
('adm-cm:40-56479b523d','adm-cm',40,'El protocolo FTP se usa para:','["Cifrar las páginas web que contienen datos personales", "Enviar mensajes de correo electrónico a otros usuarios", "Transferir archivos entre equipos", "Resolver los nombres de dominio en direcciones IP"]'::jsonb,2,'Protocolos de internet','Existe una versión segura llamada SFTP o FTPS.',null),
('adm-cm:40-81563429f8','adm-cm',40,'¿Qué es la caché del navegador?','["La lista de contraseñas y datos de inicio de sesión que el usuario ha decidido guardar en el navegador", "La carpeta del disco duro en la que se guardan por defecto todos los archivos descargados de internet", "Un almacenamiento temporal de elementos de las páginas visitadas para cargarlas más rápido", "El registro de las páginas marcadas como favoritas"]'::jsonb,2,'Navegación','Borrar la caché puede resolver problemas de visualización de algunas páginas.',null),
('adm-cm:40-a7c19de8d1','adm-cm',40,'¿Qué es un navegador web?','["Una red privada virtual", "Un servidor que almacena páginas web y las envía a los usuarios que las solicitan", "Un protocolo de transferencia de archivos", "Una aplicación que permite acceder a las páginas web y visualizarlas"]'::jsonb,3,'Navegadores','Ejemplos: Microsoft Edge, Google Chrome, Mozilla Firefox o Safari.',null),
('adm-cm:40-1b763140d4','adm-cm',40,'¿Qué es una VPN?','["Un servidor de correo electrónico seguro", "Una red privada virtual que crea una conexión cifrada a través de internet", "Un tipo de virus que se propaga por la red infectando los equipos conectados a ella", "Un navegador especial que deben usar los empleados públicos para acceder a la sede"]'::jsonb,1,'Redes','Permite, por ejemplo, teletrabajar accediendo a la red interna de la organización.',null),
('adm-cm:40-725432b36f','adm-cm',40,'¿Qué protocolo permite leer el correo manteniendo los mensajes sincronizados en el servidor?','["FTP", "SMTP", "IMAP", "POP3"]'::jsonb,2,'Correo electrónico','IMAP sincroniza con el servidor; POP3 descarga los mensajes y SMTP sirve para enviar.',null),
('adm-cm:40-232d50e5b1','adm-cm',40,'¿Cuántos bits tiene una dirección IPv4?','["64", "128", "32", "16"]'::jsonb,2,'Direccionamiento','IPv4 usa 32 bits (cuatro números de 0 a 255); IPv6, 128.',null),
('adm-cm:40-335c621b91','adm-cm',40,'¿Cuál de estos es un dominio de primer nivel genérico?','[".fr", ".es", ".org", ".mx"]'::jsonb,2,'Dominios','.org es genérico; .es, .fr y .mx son dominios territoriales de países.',null),
('adm-cm:40-13dd4b0819','adm-cm',40,'¿Qué puerto usa por defecto el protocolo HTTPS?','["21", "443", "25", "80"]'::jsonb,1,'Protocolos de internet','HTTPS usa el 443; HTTP, el 80; FTP, el 21, y SMTP, el 25.',null),
('adm-cm:40-66a0f349a1','adm-cm',40,'En un correo electrónico, los destinatarios añadidos en CCO:','["Pueden modificar el mensaje antes de leerlo", "Reciben el mensaje solo si lo abre el destinatario principal", "Reciben una copia sin los archivos adjuntos", "No son visibles para el resto de destinatarios"]'::jsonb,3,'Correo electrónico','CCO (copia oculta) envía el mensaje sin mostrar esas direcciones a los demás.',null),
('adm-cm:40-1417587f04','adm-cm',40,'Un router es un dispositivo que:','["Almacena las páginas web que se visitan", "Traduce los nombres de dominio de las páginas a sus direcciones IP numéricas", "Protege el equipo frente a los virus", "Conecta redes distintas y encamina los paquetes de datos entre ellas"]'::jsonb,3,'Redes','El router interconecta redes (por ejemplo, la de casa con internet) y decide por dónde enviar los datos.',null),
('adm-cm:40-f096487b2d','adm-cm',40,'¿Qué entidad pública gestiona el registro de los dominios .es?','["El Ministerio de Hacienda", "Red.es", "El Instituto Nacional de Ciberseguridad", "La ICANN directamente"]'::jsonb,1,'Dominios','El registro de nombres de dominio bajo .es lo gestiona la entidad pública Red.es.',null),
('adm-cm:40-d354cab4aa','adm-cm',40,'¿Cuál de los siguientes NO es un navegador web?','["Outlook", "Mozilla Firefox", "Microsoft Edge", "Google Chrome"]'::jsonb,0,'Navegadores','Outlook es un gestor de correo y calendario; los otros tres son navegadores.',null),
('adm-cm:40-756fe36fc9','adm-cm',40,'En los navegadores, Ctrl + T sirve para:','["Volver a abrir la última pestaña cerrada", "Abrir una pestaña nueva", "Cerrar la pestaña actual", "Abrir una ventana privada"]'::jsonb,1,'Atajos del navegador','Ctrl + T abre una pestaña; Ctrl + W la cierra y Ctrl + Mayús + T reabre la última cerrada.',null),
('adm-cm:40-fa76334d87','adm-cm',40,'En los navegadores, Ctrl + W sirve para:','["Guardar la página", "Abrir el historial", "Cerrar la pestaña actual", "Abrir una pestaña nueva"]'::jsonb,2,'Atajos del navegador','Ctrl + W cierra la pestaña activa.',null),
('adm-cm:40-c54e16b9dd','adm-cm',40,'El ancho de banda de una conexión indica:','["La distancia máxima entre el equipo y el router", "La cantidad de datos que puede transmitir por unidad de tiempo", "El número de dispositivos que se pueden conectar", "El tiempo que tarda en cargar por completo una página web concreta"]'::jsonb,1,'Redes','Se mide en bits por segundo (Mbps, Gbps).',null),
('adm-cm:40-4b43009330','adm-cm',40,'Un hipervínculo es:','["Un archivo temporal del navegador", "Un elemento que, al pulsarlo, lleva a otra página o recurso", "Un tipo de dirección IP", "Un programa del navegador que bloquea las ventanas emergentes publicitarias"]'::jsonb,1,'Navegación','Los hipervínculos o enlaces conectan páginas y recursos en la web.',null),
('adm-cm:41-4ff58ecb65','adm-cm',41,'En Windows 11, ¿qué combinación de teclas muestra u oculta el escritorio?','["Windows + L", "Windows + D", "Windows + M + Mayús", "Windows + E"]'::jsonb,1,'Atajos de Windows','Windows + E abre el Explorador de archivos y Windows + L bloquea el equipo.',null),
('adm-cm:41-409a2e2c1e','adm-cm',41,'En Windows 11, la combinación Windows + L sirve para:','["Abrir el Explorador de archivos", "Cerrar la sesión y apagar el equipo", "Bloquear el equipo", "Abrir la configuración de idioma"]'::jsonb,2,'Atajos de Windows','Para volver a entrar hay que identificarse (contraseña, PIN o Windows Hello).',null),
('adm-cm:41-44b382f58e','adm-cm',41,'¿Qué combinación de teclas abre el historial del portapapeles en Windows 11?','["Windows + V", "Ctrl + V", "Ctrl + Mayús + V", "Windows + C"]'::jsonb,0,'Atajos de Windows','Ctrl + V pega el último elemento copiado. El historial debe estar activado en Configuración.',null),
('adm-cm:41-2d6af7ca93','adm-cm',41,'En Windows 11, Windows + Mayús + S permite:','["Abrir el menú de apagado, reinicio y suspensión del sistema operativo", "Capturar una parte de la pantalla con la herramienta Recortes", "Cambiar entre los distintos escritorios virtuales creados por el usuario", "Guardar el documento que está abierto con otro nombre o en otra carpeta"]'::jsonb,1,'Atajos de Windows','La captura se copia en el portapapeles y puede editarse en Recortes.',null),
('adm-cm:41-7410e0b814','adm-cm',41,'¿Qué combinación abre directamente el Administrador de tareas?','["Windows + Ctrl + Esc", "Ctrl + Mayús + Esc", "Windows + Tab", "Alt + F4"]'::jsonb,1,'Atajos de Windows','Ctrl + Alt + Supr muestra una pantalla desde la que también puede abrirse.',null),
('adm-cm:41-9c129f8dcb','adm-cm',41,'En Windows 11, la combinación Windows + Tab abre:','["El menú Inicio con las aplicaciones ancladas y los archivos recomendados recientemente", "El centro de notificaciones", "El cuadro Ejecutar para escribir el nombre de un programa, carpeta o comando", "La vista de tareas, con las ventanas abiertas y los escritorios virtuales"]'::jsonb,3,'Atajos de Windows','Alt + Tab permite cambiar rápidamente entre ventanas abiertas.',null),
('adm-cm:41-2788971d44','adm-cm',41,'En Windows 11, la combinación Windows + I abre:','["Configuración", "El Explorador de archivos", "El Panel de control", "La búsqueda de Windows"]'::jsonb,0,'Atajos de Windows','La aplicación Configuración sustituye progresivamente al Panel de control.',null),
('adm-cm:41-339eed0dc9','adm-cm',41,'¿Qué combinación de teclas abre el cuadro de diálogo Ejecutar?','["Windows + E", "Ctrl + R", "Windows + R", "Alt + R"]'::jsonb,2,'Atajos de Windows','Permite abrir programas, carpetas o comandos escribiendo su nombre, por ejemplo «cmd».',null),
('adm-cm:41-645f3d54be','adm-cm',41,'Al eliminar un archivo del disco duro con Mayús + Supr en Windows:','["Se oculta al usuario, pero sigue ocupando espacio en la misma carpeta del disco", "Se envía a la Papelera de reciclaje, igual que si se pulsara solo la tecla Supr", "Se mueve a la carpeta Documentos", "Se elimina de forma permanente, sin pasar por la Papelera de reciclaje"]'::jsonb,3,'Papelera de reciclaje','Normalmente Windows pide confirmación antes de eliminarlo definitivamente.',null),
('adm-cm:41-4dd33da07a','adm-cm',41,'¿Qué es Copilot en Windows 11?','["El antivirus que viene integrado en el sistema operativo Windows", "Una herramienta para hacer copias de seguridad de los archivos en la nube", "El gestor de contraseñas integrado en el navegador Microsoft Edge", "Un asistente de inteligencia artificial de Microsoft"]'::jsonb,3,'Copilot','Permite hacer preguntas, redactar textos o resumir contenidos en lenguaje natural. Algunos teclados recientes incluyen una tecla Copilot.',null),
('adm-cm:41-68a8c17f64','adm-cm',41,'¿Qué antivirus incluye Windows 11 de forma integrada?','["BitLocker", "Windows Hello", "Microsoft Defender", "OneDrive"]'::jsonb,2,'Seguridad de Windows','Windows Hello sirve para iniciar sesión con rostro, huella o PIN; BitLocker cifra unidades y OneDrive es almacenamiento en la nube.',null),
('adm-cm:41-6e5207130f','adm-cm',41,'BitLocker es una función de Windows que sirve para:','["Limitar el tiempo que cada usuario puede usar los programas del equipo", "Cifrar unidades de disco para proteger los datos", "Comprimir carpetas y archivos en formato ZIP para que ocupen menos", "Bloquear las ventanas emergentes que abren las páginas web en el navegador"]'::jsonb,1,'Seguridad de Windows','Si se pierde el equipo, los datos no pueden leerse sin la clave.',null)
